async function GO() {
  restart: for (;;) {
    g.HERE = HILLTOP;
    move(PLAYER, g.HERE);
    g.WINNER = PLAYER;
    g.LIT$ = true;
    await INITVARS();
    await STARTUP();
    await SETUP_CHARACTER();
    g.WINDIR = random(8) - 1;
    await QUEUE(I_BREEZE.id);
    await V_REFRESH();
    crlf();
    await V_LOOK();
    await DO_MAIN_LOOP();
    continue restart;
  }
}

async function DO_MAIN_LOOP() {
  let x = 0;
  for (;;) {
    x = await MAIN_LOOP();
  }
}

async function MAIN_LOOP() {
  let icnt = 0, ocnt = 0, num = 0, cnt = 0, obj = 0, tbl = 0, v_ = false, ptbl = 0, obj1 = 0, tmp = 0, x = 0;
  cnt = 0;
  obj = false;
  ptbl = true;
  if (!(g.HERE == g.QCONTEXT_ROOM)) {
    g.QCONTEXT = false;
    g.QCONTEXT_ROOM = false;
  }
  g.P_WON = await PARSER();
  if (!(g.P_WON == 0)) {
    icnt = get(g.P_PRSI, P_MATCHLEN);
    ocnt = get(g.P_PRSO, P_MATCHLEN);
    if (!(g.P_IT_OBJECT == 0) && (await ACCESSIBLE$(g.P_IT_OBJECT))) {
      tmp = false;
      loop1: for (;;) {
        if (++cnt > icnt) {
          break loop1;
        } else if (eq(get(g.P_PRSI, cnt), IT)) {
          put(g.P_PRSI, cnt, g.P_IT_OBJECT);
          tmp = true;
          break loop1;
        }
      }
      if (tmp == 0) {
        cnt = 0;
        loop2: for (;;) {
          if (++cnt > ocnt) {
            break loop2;
          } else if (eq(get(g.P_PRSO, cnt), IT)) {
            put(g.P_PRSO, cnt, g.P_IT_OBJECT);
            break loop2;
          }
        }
      }
      cnt = 0;
    }
    num = 1;
    if (ocnt == 0) {
      num = 0;
    } else if (s16(ocnt) > s16(1)) {
      tbl = g.P_PRSO;
      obj = false;
      if (!(icnt == 0)) {
        obj = get(g.P_PRSI, 1);
      }
      num = ocnt;
    } else if (s16(icnt) > s16(1)) {
      ptbl = false;
      tbl = g.P_PRSI;
      obj = get(g.P_PRSO, 1);
      num = icnt;
    }
    if ((obj == 0) && (icnt == 1)) {
      obj = get(g.P_PRSI, 1);
    }
    if (isVerb(V.WALK)) {
      v_ = await PERFORM(g.PRSA, g.PRSO);
    } else if (num == 0) {
      if (!(getb(g.P_SYNTAX, P_SBITS) & P_SONUMS)) {
        v_ = await PERFORM(g.PRSA);
        g.PRSO = false;
      } else if (g.LIT$ == 0) {
        await PCLEAR();
        await TOO_DARK();
      } else {
        await PCLEAR();
        tell("[There isn't anything to ");
        tmp = get(g.P_ITBL, P_VERBN);
        if (x = inTable(g.PRSA, TALKVERBS, NTVERBS)) {
          tell("talk to");
        } else if (!(g.P_MERGED == 0) || !(g.P_OFLAG == 0)) {
          printB(get(tmp, 0));
        } else {
          x = getb(tmp, 3);
          await WORD_PRINT(getb(tmp, 2), x);
        }
        tell(".]\n");
        v_ = false;
      }
    } else {
      x = 0;
      g.P_MULT$ = false;
      if (s16(num) > s16(1)) {
        g.P_MULT$ = true;
      }
      tmp = false;
      loop3: for (;;) {
        if (++cnt > num) {
          if (s16(x) > s16(0)) {
            tell("[The ");
            if (!(x == num)) {
              tell("other ");
            }
            tell("object");
            if (!(x == 1)) {
              tell("s");
            }
            tell(" that you mentioned ");
            if (!(x == 1)) {
              tell("are");
            } else {
              tell("is");
            }
            tell("n't here.]\n");
          } else if (tmp == 0) {
            await REFERRING();
          }
          break loop3;
        }
        if (!(ptbl == 0)) {
          obj1 = get(g.P_PRSO, cnt);
        } else {
          obj1 = get(g.P_PRSI, cnt);
        }
        if ((s16(num) > s16(1)) || eq(get(get(g.P_ITBL, P_NC1), 0), W.ALL, W.EVERYTHING)) {
          if (obj1 == NOT_HERE_OBJECT) {
            ++x;
            continue loop3;
          } else if ((g.P_GETFLAGS == P_ALL) && (await DONT_ALL$(obj1, obj))) {
            continue loop3;
          } else if (!(await ACCESSIBLE$(obj1))) {
            continue loop3;
          } else if (obj1 == PLAYER) {
            continue loop3;
          }
          if (obj1 == IT) {
            if (!(hasFlag(g.P_IT_OBJECT, NOARTICLE))) {
              tell(S(g.XTHE));
            }
            await DPRINT(g.P_IT_OBJECT);
          } else {
            if (!(hasFlag(obj1, NOARTICLE))) {
              tell(S(g.XTHE));
            }
            await DPRINT(obj1);
          }
          tell(": ");
        }
        tmp = true;
        g.PRSO = obj1;
        g.PRSI = obj;
        if (ptbl == 0) {
          g.PRSO = obj;
          g.PRSI = obj1;
        }
        g.PSEUDO_PRSO$ = false;
        if (g.PRSO == PSEUDO_OBJECT) {
          g.PSEUDO_PRSO$ = true;
        }
        v_ = await PERFORM(g.PRSA, g.PRSO, g.PRSI);
        if (v_ == M_FATAL) {
          break loop3;
        }
      }
    }
    if (v_ == M_FATAL) {
      g.P_CONT = false;
    }
  } else {
    g.P_CONT = false;
  }
  if (!(g.P_WON == 0) && !(v_ == M_FATAL) && !(x = inTable(g.PRSA, GAME_VERBS, NGVERBS))) {
    v_ = await CLOCKER();
  }
  g.PRSA = false;
  g.PRSO = false;
  g.PRSI = false;
  return false;
}

async function DONT_ALL$(o, i) {
  let l = 0, x = 0;
  l = loc(o);
  if ((l == 0) || (o == i)) {
    return true;
  } else if (isVerb(V.TAKE)) {
    if (l == g.WINNER) {
      return true;
    } else if ((g.LIT$ == 0) && !(loc(l) == g.WINNER)) {
      return true;
    } else if (hasFlag(o, NOALL)) {
      return true;
    } else if (!(hasFlag(o, TAKEABLE)) && !(hasFlag(o, TRYTAKE))) {
      return true;
    } else if (hasFlag(l, CONTAINER) && !(hasFlag(l, OPENED))) {
      return true;
    } else if (!(i == 0)) {
      if (!(l == i)) {
        return true;
      } else if (await SEE_INSIDE$(i)) {
        return false;
      }
      return true;
    } else if (l == loc(PLAYER)) {
      return false;
    } else if (!(hasFlag(l, TAKEABLE)) && (await SEE_INSIDE$(l))) {
      return false;
    } else {
      return true;
    }
  } else if (x = inTable(g.PRSA, PUTVERBS, NUMPUTS)) {
    if (hasFlag(o, WORN)) {
      return true;
    } else if (hasFlag(o, WIELDED)) {
      return true;
    } else if (l == g.WINNER) {
      return false;
    } else {
      return true;
    }
  } else {
    return false;
  }
}

async function DEQUEUE(rtn) {
  rtn = await QUEUED$(rtn);
  if (!(rtn == 0)) {
    copyTable(rtn, 0, C_INTLEN);
  }
  return false;
}

async function QUEUED$(rtn) {
  let tbl = 0, len = 0;
  tbl = C_TABLE + g.C_INTS;
  len = div((C_TABLE + C_TABLE_LENGTH) - tbl, C_INTLEN);
  if (s16(len) < s16(1)) {
    return false;
  } else if (rtn = inTable(rtn, tbl, len, 132)) {
    if (get(rtn, C_TICK) == 0) {
      return false;
    }
    return rtn;
  }
  return false;
}

async function QUEUE(rtn, tick = (-1)) {
  let c_ = 0, e = 0, int = false;
  e = C_TABLE + C_TABLE_LENGTH;
  c_ = C_TABLE + g.C_INTS;
  loop1: for (;;) {
    if (c_ == e) {
      if (!(int == 0)) {
        c_ = int;
      } else {
        if (s16(g.C_INTS) < s16(C_INTLEN)) {
          return true;
        }
        g.C_INTS = g.C_INTS - C_INTLEN;
        int = C_TABLE + g.C_INTS;
      }
      put(int, C_RTN, rtn);
      break loop1;
    } else if (eq(get(c_, C_RTN), rtn)) {
      int = c_;
      break loop1;
    } else if (get(c_, C_RTN) == 0) {
      int = c_;
    }
    c_ = c_ + C_INTLEN;
  }
  if (s16(int) > s16(g.CLOCK_HAND)) {
    tick = -(tick + 3);
  }
  put(int, C_TICK, tick);
  return int;
}

async function CLOCKER() {
  let flg = 0, q$ = 0, e = 0, tick = 0, rtn = 0, x = 0, ostat = 0, nstat = 0, max = 0, delta = 0;
  if (!(g.CLOCK_WAIT$ == 0)) {
    g.CLOCK_WAIT$ = false;
    return false;
  }
  g.CLOCK_HAND = C_TABLE + g.C_INTS;
  e = C_TABLE + C_TABLE_LENGTH;
  loop1: for (;;) {
    if (g.CLOCK_HAND == e) {
      ++g.MOVES;
      if (await REFRESH_STATS$()) {
        flg = true;
      }
      break loop1;
    } else if (get(g.CLOCK_HAND, C_RTN)) {
      tick = get(g.CLOCK_HAND, C_TICK);
      if (s16(tick) < s16(-1)) {
        put(g.CLOCK_HAND, C_TICK, (-tick) - 3);
        q$ = g.CLOCK_HAND;
      } else if (!(tick == 0)) {
        if (s16(tick) > s16(0)) {
          tick = tick - 1;
          put(g.CLOCK_HAND, C_TICK, tick);
        }
        if (!(tick == 0)) {
          q$ = g.CLOCK_HAND;
        }
        if (!(s16(tick) > s16(0))) {
          rtn = get(g.CLOCK_HAND, C_RTN);
          if (tick == 0) {
            copyTable(g.CLOCK_HAND, 0, C_INTLEN);
          }
          x = await apply(rtn);
          if (!(x == 0)) {
            flg = true;
          }
          if ((q$ == 0) && get(g.CLOCK_HAND, C_RTN)) {
            q$ = true;
          }
        }
      }
    }
    g.CLOCK_HAND = g.CLOCK_HAND + C_INTLEN;
    if (q$ == 0) {
      g.C_INTS = g.C_INTS + C_INTLEN;
    }
  }
  return flg;
}

async function REFRESH_STATS$() {
  let cnt = 0, any = 0, stat = 0, ostat = 0, nstat = 0, delta = 0, max = 0, rate = 0;
  rate = NORMAL_RATE;
  if ((loc(SCABBARD) == PLAYER) && hasFlag(SCABBARD, WORN) && !(hasFlag(SCABBARD, NEUTRALIZED))) {
    rate = BLESSED_RATE;
  }
  stat = ENDURANCE;
  loop1: for (;;) {
    ostat = get(g.STATS, stat);
    max = get(g.MAXSTATS, stat);
    if ((stat == INTELLIGENCE) && (await WEARING_MAGIC$(HELM))) {
    } else if (g.NO_REFRESH == stat) {
      g.NO_REFRESH = -1;
    } else if (!(ostat == max)) {
      delta = div(rate * max, 100);
      if (s16(delta) < s16(1)) {
        delta = 1;
      }
      if (s16(ostat) > s16(max)) {
        nstat = ostat - delta;
        if (s16(nstat) < s16(max)) {
          nstat = max;
        }
      } else {
        nstat = ostat + delta;
        if (s16(nstat) > s16(max)) {
          nstat = max;
        }
      }
      put(g.STATS, stat, nstat);
      if (g.DMODE == 0) {
      } else if ((g.IN_DBOX == SHOWING_STATS) || (!(g.BMODE == 0) && (stat == ENDURANCE))) {
        await SHOW_STAT(stat);
      }
      ++any;
      if (nstat == max) {
        ++cnt;
        putb(NEW_STATS, cnt, stat);
      }
    }
    if (++stat > LUCK) {
      break loop1;
    }
  }
  if (any == 0) {
    return false;
  } else if (g.DMODE == 0) {
    await UPPER_SLINE();
  } else if (g.VT220 == 0) {
    await APPLE_STATS();
  }
  if (cnt == 0) {
    return false;
  } else if (g.SAY_STAT == 0) {
    return false;
  }
  if (!(g.HOST == MACINTOSH)) {
    highlight(H_BOLD);
  }
  tell(S(g.TAB), "[Your ");
  any = cnt;
  loop2: for (;;) {
    tell(S(get(STAT_NAMES, getb(NEW_STATS, any))));
    if (--any < 1) {
      break loop2;
    } else if (any == 1) {
      tell(S(g.AND));
    } else {
      tell(", ");
    }
  }
  tell(C(SP));
  if (s16(cnt) > s16(1)) {
    tell(wordText(W.ARE));
  } else {
    tell(wordText(W.IS));
  }
  tell(" back to normal.]\n");
  highlight(H_NORMAL);
  sound(S_BEEP);
  if (g.AUTO == 0) {
  } else if (eq(getb(NEW_STATS, 1), ENDURANCE)) {
    await BMODE_OFF();
  }
  return true;
}

async function INITVARS() {
  let x = 0;
  g.HOST = getb(0, 30);
  g.COLORS$ = getb(0, 1) & 1;
  g.GRAPHICS$ = get(0, 8) & 8;
  g.BAR_RES = 8;
  if (g.HOST == MACINTOSH) {
    putb(TCHARS, FIRST_MAC_ARROW, MAC_UP_ARROW);
    putb(TCHARS, FIRST_MAC_ARROW + 1, MAC_DOWN_ARROW);
    g.BAR_RES = 6;
  }
  highlight(H_MONO);
  g.CWIDTH = getb(0, 38);
  g.CHEIGHT = getb(0, 39);
  x = setFont(F_NEWFONT);
  x = setFont(F_DEFAULT);
  highlight(H_NORMAL);
  x = get(0, 17);
  g.WIDTH = div(x, g.CWIDTH);
  if (s16(g.WIDTH) > s16(80)) {
    g.WIDTH = 80;
  }
  x = get(0, 18);
  g.HEIGHT = div(x, g.CHEIGHT);
  g.DWIDTH = g.WIDTH - 20;
  g.BOXWIDTH = g.DWIDTH;
  if (g.HOST == APPLE_2C) {
    --g.BOXWIDTH;
  }
  g.MOUSEDGE = (g.WIDTH - MWIDTH) - 1;
  g.SWIDTH = div(STATMAX, g.BAR_RES) + 1;
  g.BARWIDTH = (LABEL_WIDTH + g.SWIDTH) + 5;
  g.CAN_UNDO = 0;
  g.STAT_ROUTINE = RAWBAR.id;
  g.VT220 = true;
  g.MAX_DHEIGHT = NORMAL_DHEIGHT;
  g.DHEIGHT = g.MAX_DHEIGHT;
  g.MAP_ROUTINE = CLOSE_MAP.id;
  if (!(g.VT100 == 0) || (g.HOST == APPLE_2E || g.HOST == APPLE_2C) || ((g.GRAPHICS$ == 0) && (g.HOST == IBM))) {
    await SETUP_APPLE_MODE();
  }
  return false;
}

async function SETUP_APPLE_MODE() {
  g.VT220 = false;
  g.GRAPHICS$ = false;
  g.STAT_ROUTINE = BAR_NUMBER.id;
  g.MAX_DHEIGHT = 8;
  g.MAP_ROUTINE = FAR_MAP.id;
  g.DHEIGHT = g.MAX_DHEIGHT;
  return false;
}

async function CENTER(y, x) {
  await DO_CURSET(y, div(g.WIDTH - x, 2));
  return false;
}

async function DO_CURSET(y, x) {
  if (!(1 == g.CWIDTH || 1 == g.CHEIGHT)) {
    --x;
    x = x * g.CWIDTH;
    ++x;
    --y;
    y = y * g.CHEIGHT;
    ++y;
  }
  cursorSet(y, x);
  return false;
}

async function TO_TOP_WINDOW() {
  let x = 0;
  x = setFont(F_DEFAULT);
  setWindow(S_WINDOW);
  bufOut(false);
  highlight(H_NORMAL);
  highlight(H_MONO);
  setColor(g.GCOLOR, g.BGND);
  return false;
}

async function TO_BOTTOM_WINDOW() {
  let x = 0;
  x = setFont(F_DEFAULT);
  setWindow(S_TEXT);
  bufOut(true);
  highlight(H_NORMAL);
  setColor(g.FORE, g.BGND);
  return false;
}

async function V_REFRESH() {
  let redge = 0, x = 0;
  x = get(0, 8);
  put(0, 8, x & 65531);
  g.OLD_HERE = false;
  g.P_WALK_DIR = false;
  setColor(g.FORE, g.BGND);
  clearScreen(-1);
  if (g.DMODE == 0) {
    splitWindow(2);
    await TO_BOTTOM_WINDOW();
    return true;
  }
  g.NEW_DBOX = g.IN_DBOX;
  splitWindow(12);
  if (g.VT220 == 0) {
    await APPLE_STATS();
    if (g.HOST == APPLE_2C) {
      await _2C_BOX();
    } else if (g.HOST == IBM) {
      await IBM_BOX();
    }
    return true;
  }
  await TO_TOP_WINDOW();
  x = setFont(F_NEWFONT);
  redge = (g.WIDTH - MWIDTH) - 1;
  await DO_CURSET(2, 1);
  printC(TLC);
  x = redge;
  loop1: for (;;) {
    printC(TOP);
    if (--x < 3) {
      break loop1;
    }
  }
  printC(TRC);
  await DO_CURSET(12, 1);
  printC(BLC);
  x = redge;
  loop2: for (;;) {
    printC(BOT);
    if (--x < 3) {
      break loop2;
    }
  }
  printC(BRC);
  x = 3;
  loop3: for (;;) {
    await DO_CURSET(x, 1);
    printC(RSID);
    await DO_CURSET(x, redge);
    printC(LSID);
    if (++x > 11) {
      break loop3;
    }
  }
  g.DHEIGHT = g.MAX_DHEIGHT;
  await TO_BOTTOM_WINDOW();
  if (g.PRIOR == SHOWING_STATS) {
    await SHOW_RANK();
    await DISPLAY_STATS();
  } else if (!(g.BMODE == 0)) {
    await BATTLE_MODE_ON();
  }
  return true;
}

