async function DISPLAY_PLACE() {
  let dir = 0, len = 0, x = 0, dest = 0, end = 0;
  len = getb(ROOMS_MAPPED, 0);
  if (len == 0) {
  } else if (g.OLD_HERE == 0) {
  } else if (dest = inTable(g.OLD_HERE, ROOMS_MAPPED + 1, len, 1)) {
    end = ROOMS_MAPPED + len;
    if (s16(dest) < s16(end)) {
      x = 0 - (end - dest);
      copyTable(dest + 1, dest, x);
    }
    putb(ROOMS_MAPPED, 0, len - 1);
  }
  await SETUP_SLINE();
  await SAY_HERE();
  await CENTER_SLINE();
  await SHOW_SLINE();
  if ((g.P_WALK_DIR == false || g.P_WALK_DIR == P.UP || g.P_WALK_DIR == P.DOWN) || (g.P_WALK_DIR == P.IN || g.P_WALK_DIR == P.OUT)) {
    await NEW_MAP();
  } else {
    loop1: for (;;) {
      if (g.P_WALK_DIR == getb(PDIR_LIST, dir)) {
        x = dir + 4;
        if (s16(x) > s16(I_NW)) {
          x = x - 8;
        }
        len = getProp(g.HERE, getb(PDIR_LIST, x));
        if (len == 0) {
          await NEW_MAP();
          break loop1;
        }
        len = get(len, XTYPE) & 127;
        ++len;
        x = get(YOFFS, dir);
        if (g.MAP_ROUTINE == CLOSE_MAP.id) {
          x = x + x;
        }
        x = x * len;
        g.MAPY = g.MAPY + x;
        x = get(XOFFS, dir);
        if (g.MAP_ROUTINE == CLOSE_MAP.id) {
          x = x + x;
        }
        x = x * len;
        g.MAPX = g.MAPX + x;
        if ((s16(g.MAPY) < s16(1)) || (s16(g.MAPY) > s16(9)) || (s16(g.MAPX) < s16(1)) || (s16(g.MAPX) > s16(15))) {
          await NEW_MAP();
          break loop1;
        }
        await DRAW_MAP();
        break loop1;
      }
      if (++dir > I_NW) {
        break loop1;
      }
    }
  }
  await SHOW_MAP();
  if (!(g.DMODE == 0) && (g.PRIOR == 0 || g.PRIOR == SHOWING_ROOM)) {
    g.DBOX_TOP = 0;
    await UPDATE_ROOMDESC();
  }
  g.OLD_HERE = g.HERE;
  return true;
}

