async function ANNOUNCE_RANK() {
  let level = 0, stat = 0;
  stat = get(g.STATS, EXPERIENCE);
  tell("Level ");
  loop1: for (;;) {
    if (s16(stat) < s16(get(THRESHOLDS, level))) {
      break loop1;
    } else if (++level > MAX_LEVEL) {
      level = 0;
      put(g.STATS, EXPERIENCE, 0);
      if (++g.RANK > 2) {
        g.RANK = 2;
      }
      break loop1;
    }
  }
  tell(N(level), C(SP));
  if (hasFlag(PLAYER, FEMALE)) {
    tell("Fem");
  } else {
    tell("M");
  }
  tell("ale ", S(get(RANK_NAMES, g.RANK)));
  return level;
}

