async function NEW_MAP() {
  let tbl = 0, x = 0;
  if (!(g.SAME_COORDS == 0)) {
    g.SAME_COORDS = false;
  } else {
    g.MAPX = CENTERX;
    g.MAPY = CENTERY;
    tbl = getPropAddr(g.HERE, P.COORDS);
    if (!(tbl == 0)) {
      x = getb(tbl, 0);
      if (!(x == 0)) {
        g.MAPX = x;
      }
      x = getb(tbl, 1);
      if (!(x == 0)) {
        g.MAPY = x;
      }
    }
  }
  await DRAW_MAP();
  return true;
}

async function DRAW_MAP() {
  copyTable(ROOMS_MAPPED, 0, ROOMS_MAPPED_LENGTH);
  putb(MAP, 0, SP);
  copyTable(MAP, MAP + 1, -186);
  await apply(g.MAP_ROUTINE, g.HERE, g.MAPY, g.MAPX);
  return false;
}

async function CLOSE_MAP(rm, y, x) {
  let dir = 0, tbl = 0, char = 0, type = 0, len = 0, dest = 0, ny = 0, nx = 0, yoff = 0, xoff = 0, ctbl = 0;
  len = getb(ROOMS_MAPPED, 0);
  if ((len == 0) || !(char = inTable(rm, ROOMS_MAPPED + 1, len, 1))) {
    if (++len > 45) {
      return true;
    }
    putb(ROOMS_MAPPED, len, rm);
    putb(ROOMS_MAPPED, 0, len);
  }
  if ((s16(y) > s16(-1)) && (s16(y) < s16(MHEIGHT)) && (s16(x) > s16(-1)) && (s16(x) < s16(MWIDTH))) {
    if (!(g.VT220 == 0)) {
      char = await SMART_CHAR$(rm);
    } else {
      char = await DUMB_CHAR$(rm);
    }
    putb(MAP + (y * MWIDTH), x, char);
  }
  setFlag(rm, MAPPED);
  dir = -1;
  loop1: for (;;) {
    if (++dir > I_NW) {
      clearFlag(rm, MAPPED);
      return true;
    }
    len = 0;
    dest = false;
    type = false;
    ctbl = XCHARS;
    tbl = getProp(rm, getb(PDIR_LIST, dir));
    if (!(tbl == 0)) {
      type = get(tbl, XTYPE);
      len = type & 255;
      type = type & 65280;
    }
    if ((tbl == 0) || (type == NO_EXIT || type == SORRY_EXIT) || !(btst(len, MARKBIT))) {
      ctbl = NXCHARS;
    } else if (type == FCONNECT) {
      dest = -1;
      len = len & 127;
      if (len == 0) {
        ctbl = NXCHARS;
      }
    } else {
      dest = get(tbl, XROOM);
      if ((dest == 0) || !(loc(dest) == ROOMS)) {
        return false;
      } else if ((type == SHADOW_EXIT) || ((type == DCONNECT) && !(hasFlag(get(tbl, XDATA), OPENED)))) {
        ctbl = NXCHARS;
      }
    }
    len = len & 127;
    yoff = get(YOFFS, dir);
    xoff = get(XOFFS, dir);
    ny = y + yoff;
    nx = x + xoff;
    if ((s16(ny) < s16(0)) || (s16(ny) > s16(10)) || (s16(nx) < s16(0)) || (s16(nx) > s16(16))) {
      continue loop1;
    }
    char = getb(ctbl, dir);
    if (g.VT220 == 0) {
      char = getb(SHITCHARS, dir);
      if (ctbl == NXCHARS) {
        char = SP;
      }
    } else if (g.HERE == rm) {
      char = char + 17;
    }
    putb(MAP + (ny * MWIDTH), nx, char);
    if ((tbl == 0) || (type == 0) || (dest == 0) || (s16(y) < s16(0)) || (s16(y) > s16(10)) || (s16(x) < s16(0)) || (s16(x) > s16(16))) {
      continue loop1;
    }
    len = len + (len & 254);
    char = getb(MCHARS, dir);
    if (type == X_EXIT) {
      if (btst(dir, 1)) {
        char = XCROSS;
        if (g.VT220 == 0) {
          char = 88;
        }
      } else {
        char = HVCROSS;
        if (g.VT220 == 0) {
          char = 43;
        }
      }
    } else if (ctbl == NXCHARS) {
      char = SOLID;
      if (g.VT220 == 0) {
        char = SP;
      }
    } else if (g.VT220 == 0) {
      char = getb(SHITCHARS, dir);
    }
    loop2: for (;;) {
      ny = ny + yoff;
      nx = nx + xoff;
      if ((s16(ny) < s16(0)) || (s16(ny) > s16(10)) || (s16(nx) < s16(0)) || (s16(nx) > s16(16))) {
        break loop2;
      }
      putb(MAP + (ny * MWIDTH), nx, char);
      if (--len < 1) {
        break loop2;
      }
    }
    if (dest == (-1)) {
      continue loop1;
    } else if (hasFlag(dest, MAPPED)) {
      continue loop1;
    } else if (char = inTable(dest, ROOMS_MAPPED + 1, getb(ROOMS_MAPPED, 0), 1)) {
      continue loop1;
    } else if (!(hasFlag(dest, VIEWED))) {
      continue loop1;
    }
    ny = ny + (yoff + yoff);
    nx = nx + (xoff + xoff);
    if ((s16(ny) < s16(-1)) || (s16(ny) > s16(MHEIGHT)) || (s16(nx) < s16(-1)) || (s16(nx) > s16(MWIDTH))) {
      continue loop1;
    }
    await CLOSE_MAP(dest, ny, nx);
  }
}

async function DUMB_CHAR$(rm) {
  let char = 0;
  char = 42;
  if (g.HERE == rm) {
    char = 64;
  } else if (!(await IS_LIT$(rm))) {
    char = 63;
  }
  return char;
}

async function SMART_CHAR$(rm) {
  let char = 0, tbl = 0;
  char = SOLID;
  if (g.HERE == rm) {
    char = ISOLID;
  }
  if (!(await IS_LIT$(rm))) {
    char = QMARK;
    if (g.HERE == rm) {
      char = IQMARK;
    }
  }
  tbl = getProp(rm, P.UP);
  if (!(tbl == 0) && (await CHECK_EXIT$(rm, tbl))) {
    char = UARROW;
    if (g.HERE == rm) {
      char = IUARROW;
    }
  }
  tbl = getProp(rm, P.DOWN);
  if (!(tbl == 0) && (await CHECK_EXIT$(rm, tbl))) {
    if (char == UARROW) {
      return UDARROW;
    } else if (char == IUARROW) {
      return IUDARROW;
    } else if (g.HERE == rm) {
      return IDARROW;
    }
    return DARROW;
  }
  return char;
}

async function CHECK_EXIT$(rm, tbl) {
  let exit_word = 0, room = 0, xdir = 0, xtbl = 0, type = 0, len = 0;
  exit_word = get(tbl, XTYPE);
  room = get(tbl, XROOM);
  xdir = P.NW;
  loop1: for (;;) {
    xtbl = getProp(rm, xdir);
    if (!(tbl == 0) && eq(get(xtbl, XTYPE), exit_word) && eq(get(xtbl, XROOM), room)) {
      return false;
    }
    if (++xdir > P.NORTH) {
      break loop1;
    }
  }
  type = exit_word & 65280;
  len = exit_word & 127;
  if (type == NO_EXIT || type == SORRY_EXIT) {
    return false;
  } else if (!(btst(exit_word, MARKBIT))) {
    return false;
  } else if (type == CONNECT || type == SCONNECT || type == X_EXIT) {
    return true;
  } else if ((type == DCONNECT) && hasFlag(get(tbl, XDATA), OPENED)) {
    return true;
  } else if ((type == FCONNECT) && !(len == 0)) {
    return true;
  } else {
    return false;
  }
}

async function FAR_MAP(rm, y, x) {
  let dir = 0, tbl = 0, char = 0, type = 0, len = 0, dest = 0, ny = 0, nx = 0, yoff = 0, xoff = 0;
  len = getb(ROOMS_MAPPED, 0);
  if ((len == 0) || !(char = inTable(rm, ROOMS_MAPPED + 1, len, 1))) {
    if (++len > 45) {
      return true;
    }
    putb(ROOMS_MAPPED, len, rm);
    putb(ROOMS_MAPPED, 0, len);
  }
  if ((s16(y) > s16(-1)) && (s16(y) < s16(MHEIGHT)) && (s16(x) > s16(-1)) && (s16(x) < s16(MWIDTH))) {
    if (g.VT220 == 0) {
      char = await DUMB_CHAR$(rm);
    } else {
      char = SMBOX;
      if (g.HERE == rm) {
        char = ISOLID;
      }
    }
    putb(MAP + (y * MWIDTH), x, char);
  }
  setFlag(rm, MAPPED);
  dir = -1;
  loop1: for (;;) {
    if (++dir > I_NW) {
      clearFlag(rm, MAPPED);
      return true;
    }
    len = 0;
    dest = false;
    type = false;
    tbl = getProp(rm, getb(PDIR_LIST, dir));
    if (tbl == 0) {
      continue loop1;
    }
    type = get(tbl, XTYPE);
    len = type & 255;
    type = type & 65280;
    if (type == 0) {
      return false;
    } else if (type == NO_EXIT || type == SORRY_EXIT) {
      continue loop1;
    } else if (!(btst(len, MARKBIT))) {
      continue loop1;
    } else if (type == FCONNECT) {
      dest = -1;
    } else {
      dest = get(tbl, XROOM);
      if ((dest == 0) || !(loc(dest) == ROOMS)) {
        return false;
      }
    }
    if ((dest == 0) || (s16(y) < s16(0)) || (s16(y) > s16(10)) || (s16(x) < s16(0)) || (s16(x) > s16(16))) {
      continue loop1;
    }
    len = len & 127;
    yoff = get(YOFFS, dir);
    xoff = get(XOFFS, dir);
    char = getb(MCHARS, dir);
    if (type == X_EXIT) {
      if (btst(dir, 1)) {
        char = XCROSS;
        if (g.VT220 == 0) {
          char = 88;
        }
      } else {
        char = HVCROSS;
        if (g.VT220 == 0) {
          char = 43;
        }
      }
    } else if ((type == SHADOW_EXIT) || ((type == DCONNECT) && !(hasFlag(get(tbl, XDATA), OPENED)))) {
      char = SOLID;
      if (g.VT220 == 0) {
        char = SP;
      }
    } else if (g.VT220 == 0) {
      char = getb(SHITCHARS, dir);
    }
    ny = y;
    nx = x;
    loop2: for (;;) {
      ny = ny + yoff;
      nx = nx + xoff;
      if ((s16(ny) < s16(0)) || (s16(ny) > s16(10)) || (s16(nx) < s16(0)) || (s16(nx) > s16(16))) {
        break loop2;
      }
      putb(MAP + (ny * MWIDTH), nx, char);
      if (--len < 1) {
        break loop2;
      }
    }
    if (dest == (-1)) {
      continue loop1;
    } else if (hasFlag(dest, MAPPED)) {
      continue loop1;
    } else if (char = inTable(dest, ROOMS_MAPPED + 1, getb(ROOMS_MAPPED, 0), 1)) {
      continue loop1;
    } else if (!(hasFlag(dest, VIEWED))) {
      continue loop1;
    }
    ny = ny + yoff;
    nx = nx + xoff;
    if ((s16(ny) < s16(-1)) || (s16(ny) > s16(MHEIGHT)) || (s16(nx) < s16(-1)) || (s16(nx) > s16(MWIDTH))) {
      continue loop1;
    }
    await FAR_MAP(dest, ny, nx);
  }
}

async function RELOOK(nop = 0) {
  if (nop == 0) {
    printS(g.PERIOD);
  }
  if (!(g.VERBOSITY == 0)) {
    crlf();
  }
  await V_LOOK();
  return false;
}

async function V_LOOK(v_ = true) {
  if (!(g.HOST == MACINTOSH)) {
    highlight(H_BOLD);
  }
  await SAY_HERE();
  crlf();
  highlight(H_NORMAL);
  if (!(g.LIT$ == 0)) {
    await MARK_EXITS();
  }
  if ((g.DMODE == 0) || (g.PRIOR == SHOWING_STATS || g.PRIOR == SHOWING_INV)) {
    await DESCRIBE_HERE(v_);
    if (g.DMODE == 0) {
      await UPPER_SLINE();
      await LOWER_SLINE();
      g.OLD_HERE = g.HERE;
      return true;
    }
    await DISPLAY_PLACE();
    return true;
  }
  await DISPLAY_PLACE();
  if (btst(get(0, 8), 1)) {
    dirOut(D_SCREEN_OFF);
    await DESCRIBE_HERE(v_);
    dirOut(D_SCREEN_ON);
  }
  return true;
}

async function MARK_EXITS() {
  let dir = 0, tbl = 0, wrd = 0, type = 0, len = 0;
  dir = P.NORTH;
  for (;;) {
    tbl = getProp(g.HERE, dir);
    if (!(tbl == 0)) {
      wrd = get(tbl, XTYPE);
      type = wrd & 65280;
      len = wrd & 127;
      if (btst(wrd, MARKBIT)) {
      } else if ((type == CONNECT || type == SCONNECT || type == X_EXIT) || ((type == FCONNECT) && !(len == 0)) || ((type == DCONNECT) && hasFlag(get(tbl, XDATA), OPENED))) {
        put(tbl, XTYPE, wrd + MARKBIT);
      }
    }
    if (--dir < P.DOWN) {
      return false;
    }
  }
}

