async function TEXT_STATS() {
  let stat = 0, x = 0;
  for (;;) {
    tell(S(get(STSTR, stat)));
    printC(58);
    x = get(g.STATS, stat);
    if (s16(x) < s16(10)) {
      printC(48);
    }
    tell(N(x), C(SP));
    if (++stat > 6) {
      return false;
    }
  }
}

async function NEXTLINE() {
  let len = 0;
  dirOut(D_TABLE_OFF);
  len = get(g.AUX_TABLE, 0);
  copyTable(g.AUX_TABLE + 2, SLINE, len);
  dirOut(D_TABLE_ON, g.AUX_TABLE);
  put(g.AUX_TABLE, 0, 0);
  return false;
}

async function PRINTLINE(line) {
  let len = 0, x = 0;
  dirOut(D_TABLE_OFF);
  len = get(g.AUX_TABLE, 0);
  x = SLINE + (g.WIDTH - len);
  copyTable(g.AUX_TABLE + 2, x, len);
  await TO_TOP_WINDOW();
  await DO_CURSET(line, 1);
  highlight(H_INVERSE);
  printTable(SLINE, g.WIDTH);
  await TO_BOTTOM_WINDOW();
  return false;
}

async function LOWER_SLINE() {
  let any = 0, ptr = 0, dir = 0, tbl = 0, type = 0, x = 0;
  await SETUP_SLINE();
  printC(SP);
  await SAY_HERE();
  await NEXTLINE();
  tell("Exits:");
  if (g.LIT$ == 0) {
    tell(" None visible");
  } else {
    copyTable(g.GOOD_DIRS, 0, 32);
    dir = I_NORTH;
    loop1: for (;;) {
      tbl = getProp(g.HERE, getb(PDIR_LIST, dir));
      if (!(tbl == 0)) {
        type = get(tbl, XTYPE);
        x = type & 65280;
        if ((x == CONNECT || x == SCONNECT || x == X_EXIT) || ((x == FCONNECT) && (type & 127)) || ((x == DCONNECT) && hasFlag(get(tbl, XDATA), OPENED))) {
          copyTable(tbl, g.GOOD_DIRS + (dir * 4), -4);
          ++any;
          tell(C(SP), S(get(XLIST_NAMES, dir)));
        }
      }
      if (++dir > I_NW) {
        break loop1;
      }
    }
    ptr = g.GOOD_DIRS + 2;
    loop2: for (;;) {
      tbl = getProp(g.HERE, getb(PDIR_LIST, dir));
      if (!(tbl == 0)) {
        type = get(tbl, XTYPE);
        x = type & 65280;
        if ((x == CONNECT || x == SCONNECT || x == X_EXIT) || ((x == FCONNECT) && (type & 127)) || ((x == DCONNECT) && hasFlag(get(tbl, XDATA), OPENED))) {
          if (!(x = inTable(type, g.GOOD_DIRS, 8, 132)) || !(x = inTable(get(tbl, XROOM), ptr, 8, 132))) {
            ++any;
            tell(C(SP), S(get(XLIST_NAMES, dir)));
          }
        }
      }
      if (++dir > 11) {
        break loop2;
      }
    }
    if (any == 0) {
      tell(" None");
    }
  }
  printC(SP);
  await PRINTLINE(2);
  return true;
}

async function SETUP_DBOX() {
  g.DBOX_LINES = 0;
  putb(DBOX, 0, SP);
  copyTable(DBOX, DBOX + 1, -1551);
  put(DBOX, 0, 0);
  dirOut(D_TABLE_ON, DBOX);
  return false;
}

async function JUSTIFY_DBOX() {
  let more = false, line = 0, base = 0, len = 0, ptr = 0, char = 0, x = 0, source = 0, dest = 0, end = 0, xlen = 0;
  dirOut(D_TABLE_OFF);
  len = get(DBOX, 0);
  line = g.DBOX_LINES;
  base = DBOX + 2;
  base = base + (line * g.BOXWIDTH);
  end = g.BOXWIDTH - 1;
  loop1: for (;;) {
    if (s16(base) > s16((DBOX + 2) + len)) {
      break loop1;
    }
    if (ptr = inTable(EOL, base, end, 1)) {
      ptr = ptr - base;
      x = ptr;
      loop2: for (;;) {
        ++x;
        char = getb(base, x);
        if ((char == EOL) || (s16(char) > s16(31))) {
          break loop2;
        }
      }
      source = base + x;
      dest = base + g.BOXWIDTH;
      if (!(source == dest)) {
        xlen = len - ((line * g.BOXWIDTH) + x);
        copyTable(source, dest, xlen);
        loop3: for (;;) {
          putb(base, ptr, SP);
          if (++ptr > end) {
            break loop3;
          }
          ++len;
        }
      }
    } else {
      ptr = g.BOXWIDTH;
      loop4: for (;;) {
        if (--ptr < 0) {
          break loop4;
        }
        char = getb(base, ptr);
        if ((char == SP) && !(ptr == end)) {
          source = base + ptr;
          ++source;
          dest = base + g.BOXWIDTH;
          if (source == dest) {
            break loop4;
          }
          xlen = line * g.BOXWIDTH;
          xlen = len - (xlen + ptr);
          copyTable(source, dest, xlen);
          loop5: for (;;) {
            if (++ptr > end) {
              break loop5;
            }
            ++len;
            putb(base, ptr, SP);
          }
          break loop4;
        }
      }
    }
    base = base + g.BOXWIDTH;
    if (++line > 24) {
      break loop1;
    }
  }
  g.DBOX_LINES = line;
  return true;
}

async function DISPLAY_DBOX() {
  let more = 0, tlc = 0, base = 0, lines = 0;
  g.NEW_DBOX = 0;
  tlc = 12 - g.MAX_DHEIGHT;
  base = DBOX + 2;
  if (!(g.DBOX_TOP == 0)) {
    base = base + (g.DBOX_TOP * g.BOXWIDTH);
  }
  lines = g.DHEIGHT;
  if (btst(g.IN_DBOX, SHOWING_STATS)) {
    lines = g.MAX_DHEIGHT;
  } else if (s16(g.DBOX_LINES - g.DBOX_TOP) > s16(g.DHEIGHT)) {
    ++more;
    --lines;
  }
  await TO_TOP_WINDOW();
  setColor(g.FORE, g.BGND);
  await DO_CURSET(tlc, 2);
  if (g.HOST == APPLE_2C) {
    printC(SP);
  } else if (g.VT220 == 0) {
    if (!(g.HOST == IBM)) {
      highlight(H_INVERSE);
    }
  }
  printTable(base, g.BOXWIDTH, lines);
  if (!(g.DBOX_TOP == 0)) {
    await SAY_MORE(tlc, true);
  }
  if (!(more == 0)) {
    await SAY_MORE(g.DHEIGHT + (11 - g.MAX_DHEIGHT));
  }
  await TO_BOTTOM_WINDOW();
  return true;
}

async function SAY_MORE(y, up = false) {
  let x = 0;
  setColor(g.GCOLOR, g.BGND);
  await DO_CURSET(y, 2);
  if (g.HOST == APPLE_2C) {
    printC(SP);
  }
  tell("[MORE]");
  if (g.HOST == MACINTOSH) {
    await PRINT_SPACES(g.BOXWIDTH - 30);
    tell("[Press ");
    if (!(up == 0)) {
      tell("\\");
    } else {
      tell("/");
    }
    tell(" or ");
    x = setFont(F_NEWFONT);
    if (!(up == 0)) {
      printC(92);
    } else {
      printC(93);
    }
    x = setFont(F_DEFAULT);
  } else if (!(g.VT220 == 0) || (g.HOST == APPLE_2C || g.HOST == IBM)) {
    await PRINT_SPACES(g.BOXWIDTH - 25);
    tell("[Press ");
    x = setFont(F_NEWFONT);
    if (!(g.VT220 == 0)) {
      x = 93;
      if (!(up == 0)) {
        --x;
      }
    } else if (g.HOST == APPLE_2C) {
      x = 74;
      if (!(up == 0)) {
        ++x;
      }
    } else {
      x = 25;
      if (!(up == 0)) {
        --x;
      }
    }
    printC(x);
    x = setFont(F_DEFAULT);
  } else {
    await PRINT_SPACES(g.BOXWIDTH - 34);
    if (!(up == 0)) {
      tell("  ");
    }
    tell("[Press ");
    if (!(up == 0)) {
      tell("UP");
    } else {
      tell("DOWN");
    }
    tell(" arrow");
  }
  tell(" to scroll]");
  return false;
}

async function DESCRIBE_OBJECTS() {
  let two$ = 0, it$ = 0, any$ = 0, cr = 0, b = 0, _1st$ = 0, obj = 0, nxt = 0, str = 0, x = 0;
  if (g.LIT$ == 0) {
    await TOO_DARK();
    return true;
  } else if (!(obj = first(g.HERE))) {
    return true;
  }
  obj = loc(g.WINNER);
  if (!(obj == g.HERE) && hasFlag(obj, VEHICLE) && (loc(obj) == g.HERE)) {
    move(obj, DUMMY_OBJECT);
    if (await SEE_ANYTHING_IN$(obj)) {
      tell(S(g.TAB), S(g.YOU_SEE));
      await CONTENTS(obj);
      await ON_IN(obj);
      tell(S(g.PERIOD));
    }
  }
  if (obj = first(g.HERE)) {
    loop1: for (;;) {
      nxt = next(obj);
      if (hasFlag(obj, NODESC) || (obj == g.WINNER)) {
        move(obj, DUMMY_OBJECT);
      }
      obj = nxt;
      if (obj == 0) {
        break loop1;
      }
    }
  }
  if (obj = first(g.HERE)) {
    loop2: for (;;) {
      nxt = next(obj);
      str = getProp(obj, P.DESCFCN);
      if (!(str == 0)) {
        g.DESCING = obj;
        tell(S(g.TAB));
        await apply(str, M_OBJDESC);
        crlf();
        await THIS_IS_IT(obj);
        move(obj, DUMMY_OBJECT);
      }
      obj = nxt;
      if (obj == 0) {
        break loop2;
      }
    }
  }
  _1st$ = 1;
  obj = first(g.HERE);
  loop3: for (;;) {
    if (obj == 0) {
      if (!(_1st$ == 0)) {
        break loop3;
      } else if (!(it$ == 0) && (two$ == 0)) {
        await THIS_IS_IT(obj);
      }
      tell(" here.");
      ++any$;
      break loop3;
    }
    nxt = next(obj);
    if (!(_1st$ == 0)) {
      --_1st$;
      tell(S(g.TAB));
      if (!(nxt == 0)) {
        tell(S(g.YOU_SEE));
      } else if (hasFlag(obj, PLURAL)) {
        tell("There are ");
      } else {
        tell("There's ");
      }
    } else {
      if (!(nxt == 0)) {
        tell(", ");
      } else {
        tell(S(g.AND));
      }
    }
    g.DESCING = obj;
    await PRINTA(obj);
    if ((obj == GOBLET) && (loc(BFLY) == obj) && hasFlag(BFLY, LIVING)) {
      ++b;
      tell(S(g.WITH));
      await PRINTA(BFLY);
      printS(" resting on the rim");
      remove(BFLY);
    }
    if ((await SEE_INSIDE$(obj)) && (await SEE_ANYTHING_IN$(obj))) {
      move(obj, X_OBJECT);
    }
    if ((it$ == 0) && (two$ == 0)) {
      it$ = obj;
    } else {
      two$ = true;
      it$ = false;
    }
    obj = nxt;
  }
  if (obj = first(X_OBJECT)) {
    loop4: for (;;) {
      ++any$;
      tell(C(SP));
      if (obj == GURDY) {
        tell("Within");
      } else if (obj == ARCH) {
        tell("Under");
      } else if (hasFlag(obj, SURFACE)) {
        tell("On");
      } else {
        tell("Inside");
      }
      tell(C(SP));
      await THE_PRINT(obj);
      tell(" you see ");
      await CONTENTS(obj);
      printC(PER);
      if (!(obj = next(obj))) {
        break loop4;
      }
    }
  }
  if (!(b == 0)) {
    move(BFLY, GOBLET);
  }
  if (!(any$ == 0)) {
    crlf();
  }
  g.DESCING = false;
  await MOVE_ALL(X_OBJECT, g.HERE);
  await MOVE_ALL(DUMMY_OBJECT, g.HERE);
  return true;
}

async function SEE_ANYTHING_IN$(obj = g.PRSO) {
  if (obj = first(obj)) {
    for (;;) {
      if (hasFlag(obj, NODESC)) {
      } else if (!(obj == g.WINNER)) {
        return true;
      }
      if (!(obj = next(obj))) {
        return false;
      }
    }
  }
  return false;
}

async function SEE_INSIDE$(obj) {
  if (obj == 0) {
    return false;
  } else if (obj == g.WINNER || obj == PLAYER) {
    return true;
  } else if (hasFlag(obj, VEHICLE)) {
    return true;
  } else if (hasFlag(obj, SURFACE)) {
    return true;
  } else if (hasFlag(obj, PERSON)) {
    return true;
  } else if (hasFlag(obj, LIVING)) {
    return true;
  } else if (!(hasFlag(obj, CONTAINER))) {
    return false;
  } else if (hasFlag(obj, OPENED)) {
    return true;
  } else if (hasFlag(obj, TRANSPARENT)) {
    return true;
  } else {
    return false;
  }
}

async function ACCESSIBLE$(obj) {
  let l = 0;
  if (obj == false || obj == NOT_HERE_OBJECT) {
    return false;
  } else if (obj == PSEUDO_OBJECT) {
    if (g.LAST_PSEUDO_LOC == g.HERE) {
      return true;
    }
    return false;
  }
  l = await META_LOC(obj);
  if (l == GLOBAL_OBJECTS) {
    return true;
  } else if ((l == g.WINNER || l == g.HERE || l == loc(g.WINNER)) && (await VISIBLE$(obj))) {
    return true;
  } else {
    return false;
  }
}

async function META_LOC(obj) {
  for (;;) {
    if (obj == 0) {
      return false;
    } else if (loc(obj) == GLOBAL_OBJECTS) {
      return GLOBAL_OBJECTS;
    } else if (loc(obj) == ROOMS) {
      return obj;
    }
    obj = loc(obj);
  }
}

async function VISIBLE$(obj) {
  let l = 0;
  if (obj == false || obj == NOT_HERE_OBJECT) {
    return false;
  } else if (obj == PSEUDO_OBJECT) {
    if (g.LAST_PSEUDO_LOC == g.HERE) {
      return true;
    }
    return false;
  } else if (obj == loc(g.WINNER)) {
    return true;
  }
  l = loc(obj);
  if (l == false || l == GLOBAL_OBJECTS) {
    return false;
  } else if (l == g.WINNER || l == loc(g.WINNER) || l == g.HERE) {
    return true;
  } else if ((l == LOCAL_GLOBALS) && (await GLOBAL_IN$(g.HERE, obj))) {
    return true;
  } else if ((await SEE_INSIDE$(l)) && (await VISIBLE$(l))) {
    return true;
  } else {
    return false;
  }
}

