async function ITALICIZE(str) {
  let ptr = 2, len = 0, char = 0;
  put(g.AUX_TABLE, 0, 0);
  dirOut(D_TABLE_ON, g.AUX_TABLE);
  tell(S(str));
  dirOut(D_TABLE_OFF);
  len = get(g.AUX_TABLE, 0);
  ++len;
  if (s16(len) < s16(2)) {
    return true;
  } else if (btst(getb(0, 1), 8)) {
    highlight(H_ITALIC);
    loop1: for (;;) {
      char = getb(g.AUX_TABLE, ptr);
      if (!(g.HOST == ATARI_ST) && ((char == SP || char == PER || char == 44) || (char == EXCLAM || char == 63 || char == 59) || (char == 58))) {
        highlight(H_NORMAL);
        printC(char);
        highlight(H_ITALIC);
      } else {
        printC(char);
      }
      if (ptr == len) {
        break loop1;
      }
      ++ptr;
    }
    highlight(H_NORMAL);
    return true;
  }
  loop2: for (;;) {
    char = getb(g.AUX_TABLE, ptr);
    if ((s16(char) > s16(96)) && (s16(char) < s16(123))) {
      char = char - SP;
    }
    printC(char);
    if (ptr == len) {
      break loop2;
    }
    ++ptr;
  }
  return true;
}

async function NOUN_USED$(word1, word2 = false, word3 = false) {
  let o = 0, i = 0, oof = 0, iof = 0;
  if (word1 == 0) {
    return false;
  } else if (o = inTable(g.PRSA, R_VERBS, NR_VERBS)) {
    o = get(g.P_NAMW, 1);
    oof = get(g.P_OFW, 1);
    i = get(g.P_NAMW, 0);
    iof = get(g.P_OFW, 0);
  } else {
    o = get(g.P_NAMW, 0);
    oof = get(g.P_OFW, 0);
    i = get(g.P_NAMW, 1);
    iof = get(g.P_OFW, 1);
  }
  if (((g.NOW_PRSI$ == 0) && (word1 == o || word1 == oof)) || (!(g.PRSI == 0) && !(g.NOW_PRSI$ == 0) && (word1 == i || word1 == iof))) {
    return word1;
  } else if (word2 == 0) {
    return false;
  } else if (((g.NOW_PRSI$ == 0) && (word2 == o || word2 == oof)) || (!(g.PRSI == 0) && !(g.NOW_PRSI$ == 0) && (word2 == i || word2 == iof))) {
    return word2;
  } else if (word3 == 0) {
    return false;
  } else if (((g.NOW_PRSI$ == 0) && (word3 == o || word3 == oof)) || (!(g.PRSI == 0) && !(g.NOW_PRSI$ == 0) && (word3 == i || word3 == iof))) {
    return word3;
  } else {
    return false;
  }
}

