async function REPLACE_ADJ$(obj, old, new_) {
  let tbl = 0, len = 0;
  tbl = getPropAddr(obj, P.ADJECTIVE);
  if (tbl == 0) {
    return false;
  }
  len = div(propSize(tbl), 2);
  for (;;) {
    if (--len < 0) {
      return false;
    } else if (eq(get(tbl, len), old)) {
      put(tbl, len, new_);
      return true;
    }
  }
}

