async function DISPLAY_STATS() {
  g.BMODE = false;
  g.DHEIGHT = g.MAX_DHEIGHT;
  g.DBOX_TOP = 0;
  g.DBOX_LINES = 0;
  g.IN_DBOX = SHOWING_STATS;
  putb(DBOX, 0, SP);
  copyTable(DBOX, DBOX + 1, -1551);
  await DISPLAY_DBOX();
  await STATBARS(13 - g.MAX_DHEIGHT);
  return false;
}

async function STATBARS(y, x = 0, n_ = 0) {
  let stat = 0;
  if (x == 0) {
    x = div(g.DWIDTH - g.BARWIDTH, 2) + 1;
  }
  if (!(arguments.length > 2)) {
    n_ = ARMOR_CLASS;
  }
  g.BARY = y;
  g.BARX = x;
  await TO_TOP_WINDOW();
  setColor(g.FORE, g.BGND);
  await DO_CURSET(g.BARY, g.BARX);
  printTable(BAR_LABELS, LABEL_WIDTH, n_ + 1);
  loop1: for (;;) {
    await apply(g.STAT_ROUTINE, stat, get(g.STATS, stat));
    if (++stat > n_) {
      break loop1;
    }
  }
  await TO_BOTTOM_WINDOW();
  return false;
}

async function SHOW_STAT(stat) {
  await TO_TOP_WINDOW();
  await apply(g.STAT_ROUTINE, stat, get(g.STATS, stat));
  await TO_BOTTOM_WINDOW();
  return false;
}

async function BAR_NUMBER(stat, val) {
  let y = 0;
  highlight(H_NORMAL);
  y = stat + g.BARY;
  cursorSet(y, g.BARX + 13);
  if (s16(val) < s16(10)) {
    tell("  ");
  } else if (s16(val) < s16(100)) {
    tell(C(SP));
  }
  tell(N(val));
  return false;
}

async function RAWBAR(stat, val) {
  let ptr = 0, x = 0, y = 0, z = 0;
  putb(SLINE, 0, BASE_CHAR);
  x = 0 - g.SWIDTH;
  copyTable(SLINE, SLINE + 1, x);
  x = BASE_CHAR + g.BAR_RES;
  y = div(val, g.BAR_RES);
  z = g.SWIDTH - 1;
  ptr = 1;
  loop1: for (;;) {
    if (s16(ptr) > s16(y)) {
      break loop1;
    }
    putb(SLINE, ptr, x);
    if (++ptr > z) {
      break loop1;
    }
  }
  putb(SLINE, ptr, BASE_CHAR + mod(val, g.BAR_RES));
  putb(SLINE, 0, LCAP);
  putb(SLINE, g.SWIDTH + 1, RCAP);
  y = stat + g.BARY;
  x = g.BARX + LABEL_WIDTH;
  await DO_CURSET(y, x);
  z = setFont(F_NEWFONT);
  setColor(g.GCOLOR, g.BGND);
  z = g.SWIDTH + 2;
  printTable(SLINE, z);
  await DO_CURSET(y, z + x);
  z = setFont(F_DEFAULT);
  setColor(g.FORE, g.BGND);
  if (s16(val) < s16(10)) {
    printC(SP);
  }
  tell(N(val), "%");
  return false;
}

async function APPLE_STATS() {
  let cnt = 0, x = 0;
  await SETUP_SLINE();
  loop1: for (;;) {
    tell(S(get(STSTR, cnt)), ":");
    x = get(g.STATS, cnt);
    if (s16(x) < s16(10)) {
      tell("0");
    }
    tell(N(x));
    if (++cnt > 6) {
      break loop1;
    }
    printC(SP);
    if (s16(g.DWIDTH) > s16(46)) {
      printC(SP);
    }
  }
  await CENTER_SLINE();
  await SHOW_SLINE(2);
  return true;
}

async function UPDATE_STAT(delta, stat = ENDURANCE, update_max = false) {
  let newrank = 0, nstat = 0, ostat = 0, max = 0, omax = 0, nlvl = 0, olvl = 0, x = 0;
  if (delta == 0) {
    return false;
  }
  ostat = get(g.STATS, stat);
  nstat = ostat + delta;
  if (s16(nstat) < s16(0)) {
    nstat = 0;
  } else if (stat == EXPERIENCE) {
  } else if (s16(nstat) > s16(STATMAX)) {
    nstat = STATMAX;
  }
  if (ostat == nstat) {
    return false;
  }
  put(g.STATS, stat, nstat);
  omax = get(g.MAXSTATS, stat);
  if (update_max == 0) {
  } else if (stat == EXPERIENCE) {
  } else if (!(nstat == omax)) {
    max = delta + omax;
    if (s16(max) < s16(0)) {
      max = 0;
    } else if (s16(max) > s16(STATMAX)) {
      max = STATMAX;
    }
    put(g.MAXSTATS, stat, max);
  }
  if (!(nstat == omax)) {
    g.NO_REFRESH = stat;
  }
  if (stat == EXPERIENCE) {
    nlvl = await GET_LEVEL$(nstat);
    olvl = await GET_LEVEL$(ostat);
    if ((s16(nlvl) > s16(olvl)) || ((nlvl == 0) && (olvl == MAX_LEVEL))) {
      await UPGRADE_RANK();
      ++newrank;
    }
  }
  if (!(g.SAY_STAT == 0)) {
    if (!(g.HOST == MACINTOSH)) {
      highlight(H_BOLD);
    }
    tell(S(g.TAB), "[Your ", S(get(STAT_NAMES, stat)));
    x = S_BEEP;
    if (nstat == omax) {
      tell(" is back to normal");
    } else {
      tell(" just went ");
      if (s16(delta) < s16(0)) {
        x = S_BOOP;
        tell(wordText(W.DOWN));
      } else {
        tell(wordText(W.UP));
      }
    }
    if (!(newrank == 0)) {
      tell(". You have achieved the rank of ");
      await ANNOUNCE_RANK();
    }
    tell(".]\n");
    highlight(H_NORMAL);
    sound(x);
  }
  if (g.DMODE == 0) {
    await UPPER_SLINE();
  } else if (g.VT220 == 0) {
    await APPLE_STATS();
  } else if (g.IN_DBOX == SHOWING_STATS) {
    if (!(newrank == 0)) {
      await SHOW_RANK();
      await TO_TOP_WINDOW();
      stat = ENDURANCE;
      loop1: for (;;) {
        await apply(g.STAT_ROUTINE, stat, get(g.STATS, stat));
        if (++stat > ARMOR_CLASS) {
          break loop1;
        }
      }
      await TO_BOTTOM_WINDOW();
      return true;
    } else if (stat == EXPERIENCE) {
      return true;
    }
    await SHOW_STAT(stat);
  } else if (g.BMODE == 0) {
  } else if (!(newrank == 0) || (stat == ENDURANCE)) {
    await SHOW_STAT(ENDURANCE);
  }
  if ((nstat == 0) && (stat == ENDURANCE || stat == STRENGTH)) {
    tell(S(g.TAB), "Your last ounce of ", S(get(STAT_NAMES, stat)), " gives out");
    await JIGS_UP();
  }
  return true;
}

async function GET_LEVEL$(val) {
  let lvl = 0;
  for (;;) {
    if (s16(val) < s16(get(THRESHOLDS, lvl))) {
      return lvl;
    } else if (++lvl > MAX_LEVEL) {
      return false;
    }
  }
}

async function UPGRADE_RANK() {
  let tbl = 0, o = 0, n_ = 0;
  tbl = g.STATS;
  for (;;) {
    o = get(tbl, ENDURANCE);
    n_ = div(STATMAX - o, 10);
    if (s16(n_) < s16(1)) {
      n_ = 1;
    }
    n_ = o + n_;
    if (s16(n_) > s16(STATMAX)) {
      n_ = STATMAX;
    } else if (s16(n_) < s16(1)) {
      n_ = 1;
    }
    put(tbl, ENDURANCE, n_);
    if (tbl == g.MAXSTATS) {
      return false;
    }
    tbl = g.MAXSTATS;
  }
}

async function PRINT_TABLE(tbl) {
  let ptr = 1, len = 0;
  len = getb(tbl, 0);
  if (len == 0) {
    return false;
  }
  for (;;) {
    printC(getb(tbl, ptr));
    if (++ptr > len) {
      return false;
    }
  }
}

