async function LIGHT_SOURCE$() {
  let obj = 0, len = 0;
  if (hasFlag(g.HERE, INDOORS)) {
  } else if (!(await PLAIN_ROOM$())) {
    return SUN;
  }
  len = get(LIGHT_SOURCES, 0);
  loop1: for (;;) {
    obj = get(LIGHT_SOURCES, len);
    if (hasFlag(obj, LIGHTED) && (await VISIBLE$(obj))) {
      return obj;
    }
    if (--len < 1) {
      break loop1;
    }
  }
  obj = await FIND_IN$(g.WINNER, LIGHTED);
  if (obj == 0) {
    obj = await FIND_IN$(loc(g.WINNER), LIGHTED);
  }
  return obj;
}

async function NEW_EXIT$(obj, dir, type, room = 0, data = 0) {
  let ptr = 0, x = 0, tbl = 0, bytes = 0;
  tbl = getProp(obj, dir);
  if (tbl == 0) {
    bytes = 4;
    if (arguments.length > 4) {
      bytes = 6;
    }
    ptr = g.STORAGE;
    x = g.STORAGE + bytes;
    if (s16(x) > s16(STORAGE_SPACE)) {
      (await SAY_ERROR("NEW-EXIT?"));
      return false;
    }
    g.STORAGE = x;
    tbl = FREE_STORAGE + ptr;
    putProp(obj, dir, tbl);
  }
  put(tbl, XTYPE, type);
  if (arguments.length > 3) {
    put(tbl, XROOM, room);
  }
  if (arguments.length > 4) {
    put(tbl, XDATA, data);
  }
  return true;
}

