async function NEXT_ENDURANCE$(obj) {
  let x = 0, max = 0, change = 0;
  x = getProp(obj, P.ENDURANCE);
  if (hasFlag(obj, STRICKEN)) {
    clearFlag(obj, STRICKEN);
    return x;
  }
  max = getProp(obj, P.EMAX);
  if (s16(max) > s16(x)) {
    change = div(2 * max, 100);
    if (s16(change) < s16(1)) {
      change = 1;
    }
    x = x + change;
    if (s16(x) > s16(max)) {
      x = max;
    }
    putProp(obj, P.ENDURANCE, x);
  }
  return x;
}

