async function MONSTER_STRIKES$(obj) {
  let damage = 0, str = 0, chance = 0, x = 0;
  await SEE_MONSTER(obj);
  str = getProp(obj, P.STRENGTH);
  if (s16(str) < s16(1)) {
    return false;
  }
  setFlag(obj, STRICKEN);
  chance = 12;
  if (!(g.ATTACK_MODE == PARRYING)) {
    chance = getProp(obj, P.DEXTERITY);
    if (g.ATTACK_MODE == NORMAL_ATTACK) {
      chance = div(chance, 2);
    }
    chance = div(chance * 45, 100);
    chance = chance + MIN_HIT_PROB;
    if (s16(chance) > s16(MAX_HIT_PROB)) {
      chance = MAX_HIT_PROB;
    }
  }
  g.ATTACK_MODE = NORMAL_ATTACK;
  if (prob(chance)) {
    damage = STATMAX - get(g.STATS, ARMOR_CLASS);
    damage = div((damage * str) + 99, 100);
    if (s16(damage) < s16(2)) {
      damage = 1;
    } else {
      damage = random(damage);
    }
    if (!(g.AUTO == 0)) {
      await BMODE_ON();
    }
    return 0 - damage;
  } else {
    return false;
  }
}

async function MOVE_MONSTER$(obj, ud = 0) {
  let l = 0, rlist = 0, rlen = 0, cnt = 0, dir = 0, tbl = 0, dest = 0, x = 0, bright = 0, fear = 0;
  if (hasFlag(obj, SLEEPING)) {
    clearFlag(obj, SLEEPING);
    clearFlag(obj, STRICKEN);
    clearFlag(obj, NEUTRALIZED);
    return false;
  }
  setFlag(obj, SURPRISED);
  await NEXT_ENDURANCE$(obj);
  l = loc(obj);
  fear = loc(SCARE3);
  rlist = getProp(obj, P.HABITAT);
  rlen = getb(rlist, 0);
  rlist = rlist + 1;
  cnt = 1;
  dir = P.NORTH;
  loop1: for (;;) {
    tbl = getProp(l, dir);
    if (tbl == 0) {
    } else if (eq(get(tbl, XTYPE) & 65280, CONNECT, SCONNECT, X_EXIT)) {
      dest = get(tbl, XROOM);
      if ((x = inTable(dest, rlist, rlen, 1)) && (!(obj == GRUE) || !(await IS_LIT$(dest)))) {
        if (!(g.LAST_MONSTER == 0)) {
        } else if (await WEARING_MAGIC$(CLOAK)) {
        } else if ((dest == g.HERE) && !(dest == fear)) {
          cnt = 2;
          put(g.GOOD_DIRS, 2, dir);
          break loop1;
        }
        if (!(dest == fear)) {
          ++cnt;
          put(g.GOOD_DIRS, cnt, dir);
        }
      }
    }
    if (--dir < P.NW) {
      break loop1;
    }
  }
  if (!(ud == 0)) {
    dir = P.UP;
    loop2: for (;;) {
      tbl = getProp(l, dir);
      if (tbl == 0) {
      } else if (eq(get(tbl, XTYPE) & 65280, CONNECT, SCONNECT)) {
        dest = get(tbl, XROOM);
        if (x = inTable(dest, rlist, rlen, 1)) {
          if (!(g.LAST_MONSTER == 0)) {
          } else if (await WEARING_MAGIC$(CLOAK)) {
          } else if (dest == g.HERE) {
            cnt = 2;
            put(g.GOOD_DIRS, 2, dir);
            break loop2;
          }
          ++cnt;
          put(g.GOOD_DIRS, cnt, dir);
        }
      }
      if (dir == P.DOWN) {
        break loop2;
      }
      dir = P.DOWN;
    }
  }
  if (cnt == 1) {
    return false;
  } else if (cnt == 2) {
    dir = get(g.GOOD_DIRS, 2);
    dest = get(getProp(l, dir), XROOM);
  } else {
    x = getProp(obj, P.LAST_LOC);
    put(g.GOOD_DIRS, 0, cnt);
    put(g.GOOD_DIRS, 1, 0);
    loop3: for (;;) {
      dir = await PICK_ONE(g.GOOD_DIRS);
      dest = get(getProp(l, dir), XROOM);
      if (dest == x) {
        continue loop3;
      }
      break loop3;
    }
  }
  if (g.LAST_MONSTER == 0) {
  } else if (dest == g.HERE) {
    return false;
  }
  move(obj, dest);
  putProp(obj, P.LAST_LOC, dest);
  if (!(dest == g.HERE)) {
    return false;
  } else if (!(g.LIT$ == 0)) {
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
  }
  if (!(dir == P.UP || dir == P.DOWN)) {
    dir = dir + 4;
    if (s16(dir) > s16(P.NORTH)) {
      dir = dir - 8;
    }
    g.LAST_MONSTER_DIR = dir;
  }
  await THIS_IS_IT(obj);
  g.LAST_MONSTER = obj;
  clearFlag(obj, SURPRISED);
  if (dir == P.UP) {
    g.LAST_MONSTER_DIR = P.DOWN;
    return W.UP;
  } else if (dir == P.DOWN) {
    g.LAST_MONSTER_DIR = P.UP;
    return W.DOWN;
  }
  return get(DIR_NAMES, 0 - (dir - P.NORTH));
}

async function NEXT_MONSTER(obj) {
  let rlist = 0, len = 0, cnt = 0, x = 0, rm = 0;
  if (obj == 0) {
    return false;
  }
  rlist = getProp(obj, P.HABITAT);
  len = getb(rlist, 0);
  x = len;
  cnt = 1;
  loop1: for (;;) {
    rm = getb(rlist, x);
    if (rm == g.HERE) {
    } else if ((obj == GRUE) && hasFlag(rm, LIGHTED)) {
    } else if (!(hasFlag(rm, TOUCHED))) {
      ++cnt;
      put(g.AUX_TABLE, cnt, rm);
    }
    if (--x < 1) {
      break loop1;
    }
  }
  if (cnt == 1) {
    loop2: for (;;) {
      rm = getb(rlist, random(len));
      if (rm == g.HERE) {
        continue loop2;
      } else if ((obj == GRUE) && hasFlag(rm, LIGHTED)) {
        continue loop2;
      }
      break loop2;
    }
  } else if (cnt == 2) {
    rm = get(g.AUX_TABLE, 2);
  } else {
    put(g.AUX_TABLE, 0, cnt);
    put(g.AUX_TABLE, 1, 0);
    rm = await PICK_ONE(g.AUX_TABLE);
  }
  move(obj, rm);
  setFlag(obj, SURPRISED);
  putProp(obj, P.LAST_LOC, rm);
  await QUEUE(getProp(obj, P.LIFE));
  return false;
}

