async function GLOBAL_CHECK(tbl) {
  let len = 0, rmg = 0, rmgl = 0, cnt = 0, obj = 0, obits = 0, x = 0;
  len = get(tbl, P_MATCHLEN);
  obits = g.P_SLOCBITS;
  rmg = getPropAddr(g.HERE, P.GLOBAL);
  if (!(rmg == 0)) {
    rmgl = div(propSize(rmg), 2) - 1;
    loop1: for (;;) {
      obj = get(rmg, cnt);
      if (x = first(obj)) {
        await SEARCH_LIST(obj, tbl, P_SRCALL);
      }
      if (await THIS_IT$(obj)) {
        await OBJ_FOUND(obj, tbl);
      }
      if (++cnt > rmgl) {
        break loop1;
      }
    }
  }
  rmg = getProp(g.HERE, P.THINGS);
  if (!(rmg == 0)) {
    rmgl = get(rmg, 0);
    cnt = 0;
    loop2: for (;;) {
      if ((g.P_NAM == get(rmg, cnt + 1)) && ((g.P_ADJ == 0) || (g.P_ADJ == get(rmg, cnt + 2)))) {
        g.P_PNAM = g.P_NAM;
        if (!(g.P_ADJ == 0)) {
          g.P_PADJN = g.P_ADJ;
        } else {
          g.P_PADJN = false;
        }
        g.LAST_PSEUDO_LOC = g.HERE;
        clearFlag(PSEUDO_OBJECT, NOARTICLE);
        putProp(PSEUDO_OBJECT, P.ACTION, get(rmg, cnt + 3));
        await OBJ_FOUND(PSEUDO_OBJECT, tbl);
        break loop2;
      }
      cnt = cnt + 3;
      if (!(s16(cnt) < s16(rmgl))) {
        break loop2;
      }
    }
  }
  if (eq(get(tbl, P_MATCHLEN), len)) {
    g.P_SLOCBITS = -1;
    g.P_TABLE = tbl;
    await DO_SL(GLOBAL_OBJECTS, 1, 1);
    return g.P_SLOCBITS = obits;
  } else {
    return false;
  }
}

async function DO_SL(obj, bit1, bit2) {
  if (btst(g.P_SLOCBITS, bit1 + bit2)) {
    return await SEARCH_LIST(obj, g.P_TABLE, P_SRCALL);
  } else {
    if (btst(g.P_SLOCBITS, bit1)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCTOP);
    } else if (btst(g.P_SLOCBITS, bit2)) {
      return await SEARCH_LIST(obj, g.P_TABLE, P_SRCBOT);
    } else {
      return true;
    }
  }
}

async function SEARCH_LIST(obj, tbl, lvl) {
  let x = 0;
  if (obj = first(obj)) {
    loop1: for (;;) {
      if (!(lvl == P_SRCBOT) && (await THIS_IT$(obj))) {
        await OBJ_FOUND(obj, tbl);
      }
      if (!(obj == g.WINNER || obj == LOCAL_GLOBALS || obj == GLOBAL_OBJECTS) && (x = first(obj)) && (await SEE_INSIDE$(obj))) {
        x = P_SRCTOP;
        if (hasFlag(obj, SURFACE)) {
          x = P_SRCALL;
        }
        await SEARCH_LIST(obj, tbl, x);
      }
      if (!(obj = next(obj))) {
        break loop1;
      }
    }
  }
  return false;
}

async function THIS_IT$(obj) {
  let tbl = 0, len = 0;
  if (!(g.P_NAM == 0) && (!(tbl = getPropAddr(obj, P.SYNONYM)) || !(len = div(propSize(tbl), 2)) || !(len = inTable(g.P_NAM, tbl, len)))) {
    return false;
  } else if (!(g.P_ADJ == 0) && (!(tbl = getPropAddr(obj, P.ADJECTIVE)) || !(len = div(propSize(tbl), 2)) || !(len = inTable(g.P_ADJ, tbl, len)))) {
    return false;
  } else if (!(g.P_GWIMBIT == 0) && !(hasFlag(obj, g.P_GWIMBIT))) {
    return false;
  } else {
    return true;
  }
}

async function OBJ_FOUND(obj, tbl) {
  let ptr = 0;
  ptr = get(tbl, P_MATCHLEN);
  ++ptr;
  put(tbl, ptr, obj);
  put(tbl, P_MATCHLEN, ptr);
  return false;
}

async function ITAKE_CHECK(tbl, bits) {
  let ptr = 0, len = 0, obj = 0, l = 0, got_it = 0, took_it = 0;
  ptr = 1;
  len = get(tbl, P_MATCHLEN);
  if (len == 0) {
    return true;
  } else if (btst(bits, SHAVE) || btst(bits, STAKE)) {
    for (;;) {
      obj = get(tbl, ptr);
      if (obj == IT) {
        if (!(await ACCESSIBLE$(g.P_IT_OBJECT))) {
          await MORE_SPECIFIC();
          return false;
        }
        obj = g.P_IT_OBJECT;
      } else if (obj == THEM) {
        if (!(await ACCESSIBLE$(g.P_THEM_OBJECT))) {
          await MORE_SPECIFIC();
          return false;
        }
        obj = g.P_THEM_OBJECT;
      } else if (obj == HER) {
        if (!(await ACCESSIBLE$(g.P_HER_OBJECT))) {
          await MORE_SPECIFIC();
          return false;
        }
        obj = g.P_HER_OBJECT;
      } else if (obj == HIM) {
        if (!(await ACCESSIBLE$(g.P_HIM_OBJECT))) {
          await MORE_SPECIFIC();
          return false;
        }
        obj = g.P_HIM_OBJECT;
      }
      if (!(obj == g.WINNER || obj == HANDS || obj == FEET) && !(obj == ME || obj == YOU || obj == ROOMS) && !(obj == INTDIR || obj == RIGHT || obj == LEFT) && !(obj == MONEY) && !(await HELD$(obj))) {
        g.PRSO = obj;
        l = loc(obj);
        got_it = 0;
        took_it = 0;
        if (l == 0) {
        } else if (hasFlag(obj, TRYTAKE) && !(hasFlag(obj, TAKEABLE))) {
          if (btst(bits, SHAVE) && (loc(l) == g.WINNER)) {
            ++got_it;
          }
        } else if ((g.P_MULT$ == 0) && (loc(l) == g.WINNER) && (await ITAKE(false))) {
          ++got_it;
          ++took_it;
        } else if ((l == g.WINNER) && btst(bits, SHAVE)) {
          ++got_it;
        }
        if ((got_it == 0) && btst(bits, SHAVE)) {
          await WINNER_NOT_HOLDING();
          if ((len == ptr) && !(g.P_MULT$ == 0)) {
            tell("all of those things");
          } else if (obj == NOT_HERE_OBJECT) {
            await THIS_IS_IT(obj);
            await DPRINT(obj);
          } else {
            await THIS_IS_IT(obj);
            if (hasFlag(obj, PLURAL)) {
              tell("any ");
            } else if (!(hasFlag(obj, NOARTICLE))) {
              if (hasFlag(obj, PROPER)) {
                tell(S(g.LTHE));
              } else if (hasFlag(obj, VOWEL)) {
                tell("an ");
              } else {
                tell("a ");
              }
            }
            await DPRINT(obj);
          }
          printS(g.PERIOD);
          return false;
        } else if (!(got_it == 0) && !(took_it == 0) && (g.WINNER == PLAYER)) {
          await TAKING_OBJ_FIRST(obj);
        }
      }
      if (++ptr > len) {
        return true;
      }
    }
  }
  return true;
}

async function HELD$(obj = g.PRSO) {
  let l = 0;
  if (obj == 0) {
    return false;
  } else if (hasFlag(obj, TAKEABLE)) {
  } else if (!(hasFlag(obj, TRYTAKE))) {
    return false;
  }
  l = loc(obj);
  if (l == false || l == ROOMS || l == GLOBAL_OBJECTS) {
    return false;
  } else if (l == g.WINNER) {
    return true;
  }
  return await HELD$(l);
}

