async function IS_LIT$(rm = g.HERE, rmbit = true) {
  let lit = 0, ohere = 0;
  if (!(g.ALWAYS_LIT$ == 0) && (g.WINNER == PLAYER)) {
    return true;
  }
  g.P_GWIMBIT = LIGHTED;
  ohere = g.HERE;
  g.HERE = rm;
  if (!(rmbit == 0) && hasFlag(rm, LIGHTED)) {
    ++lit;
  } else {
    put(g.P_MERGE, P_MATCHLEN, 0);
    g.P_TABLE = g.P_MERGE;
    g.P_SLOCBITS = -1;
    if (ohere == rm) {
      await DO_SL(g.WINNER, 1, 1);
      if (!(g.WINNER == PLAYER) && (loc(PLAYER) == rm)) {
        await DO_SL(PLAYER, 1, 1);
      }
    }
    await DO_SL(rm, 1, 1);
    if (s16(get(g.P_TABLE, P_MATCHLEN)) > s16(0)) {
      ++lit;
    }
  }
  g.HERE = ohere;
  g.P_GWIMBIT = 0;
  return lit;
}

