async function MOVE_ALL(from, to, except = 0) {
  let obj = 0, nxt = 0;
  if (obj = first(from)) {
    for (;;) {
      nxt = next(obj);
      if (!(arguments.length > 2) || !(hasFlag(obj, except))) {
        move(obj, to);
      }
      obj = nxt;
      if (obj == 0) {
        return true;
      }
    }
  }
  return false;
}

