  if (verb == 0) {
  } else if ((g.P_QWORD == 0) && !(naming == 0) && (verb == ACT.NAME)) {
    g.P_QWORD = ptr;
    wrd = W.PPPZ;
  }
  await CHANGE_LEXV(ptr, wrd);
