async function QUOTED_PHRASE$(ptr, verb) {
  let _1st$ = true, len = 0, wrd = 0, bptr = 0;
  await CHANGE_LEXV(ptr, W.$BUZZ);
  len = g.P_LEN - 1;
  ptr = ptr + P_LEXELEN;
  bptr = g.P_LEXV + (ptr * 2);
  for (;;) {
    if (s16(len) < s16(0)) {
      await PCLEAR();
      tell("[You forgot a second quote.]\n");
      return false;
    }
    wrd = get(g.P_LEXV, ptr);
    if (wrd == W.QUOTE) {
      await CHANGE_LEXV(ptr, W.$BUZZ);
      return true;
    } else if (!(_1st$ == 0)) {
      if (!(wrd == 0)) {
        if (verb == ACT.SAY) {
        } else if (verb == ACT.NAME) {
          (await HOLLOW_VOICE("reserved by the Implementors"));
          return false;
        }
      } else if (await QUOTED_WORD$(ptr, verb, true)) {
        _1st$ = false;
      } else {
        tell(S(g.CANT), "see any ");
        len = getb(bptr, 2);
        await WORD_PRINT(len, getb(bptr, 3));
        tell(" here.\n");
        return false;
      }
    } else {
      await CHANGE_LEXV(ptr, W.$BUZZ);
    }
    ptr = ptr + P_LEXELEN;
    len = len - 1;
  }
}

