async function NEXT_APLANE() {
  let dir = 0, tbl = 0, data = 0, new_ = 0, x = 0;
  dir = g.P_WALK_DIR;
  g.P_WALK_DIR = false;
  x = loc(PLAYER);
  if ((dir == P.UP || dir == P.DOWN) || (dir == P.IN || dir == P.OUT)) {
    tell("Such ", D(INTDIR), "s have no meaning here.\n");
    return M_FATAL;
  } else if (x == APLANE) {
  } else if (hasFlag(x, VEHICLE)) {
    if (eq(await PERFORM(V.EXIT, x), M_FATAL)) {
      return M_FATAL;
    }
    tell(S(g.TAB));
  }
  tbl = getProp(g.HERE, dir);
  data = get(tbl, XTYPE);
  if (data == NO_EXIT) {
    tell("The local geometry does not extend in that ", D(INTDIR), S(g.PERIOD));
    return M_FATAL;
  } else if (g.ABOVE == OPLAIN) {
    if (!(g.IMPSAY == 0)) {
      await PERMISSION();
      return M_FATAL;
    }
    await EXIT_IMPS();
  }
  new_ = get(tbl, XDATA);
  if (new_ == OPLAIN) {
    if (hasFlag(SHAPE, LIVING)) {
      if (!(loc(SHAPE) == APLANE)) {
        g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
        move(SHAPE, APLANE);
        g.LAST_MONSTER = SHAPE;
        g.LAST_MONSTER_DIR = false;
        g.P_IT_OBJECT = SHAPE;
        tell("The space before you flexes in on itself, twists sideways and reopens into ");
        await PRINTA(SHAPE);
        tell(", stretched across your path like the skin of a drum.\n");
        return M_FATAL;
      }
      await CTHE_PRINT(SHAPE);
      tell(" stretches itself tighter across your path.\n");
      return M_FATAL;
    } else if (g.IMPSAY == 0) {
      await KERBLAM();
      tell("A bolt of ", wordText(W.LIGHTNING), " blocks your path.\n");
      return M_FATAL;
    }
  }
  if (g.ABOVE == OACCARDI || g.ABOVE == OCITY || g.ABOVE == OMIZNIA) {
    remove(CURTAIN);
  }
  if (loc(SHAPE) == APLANE) {
    remove(SHAPE);
    g.LAST_MONSTER = false;
    g.P_IT_OBJECT = NOT_HERE_OBJECT;
    await CTHE_PRINT(SHAPE);
    tell(" disincorporates as you retreat.\n");
    if (!(g.VERBOSITY == 0)) {
      crlf();
    }
  }
  g.ABOVE = new_;
  await GET_APLANE_THINGS();
  await NEXT_OVER();
  await V_LOOK();
  return true;
}

