async function GET_APLANE_THINGS() {
  if (g.ABOVE == OCITY || g.ABOVE == OMIZNIA || g.ABOVE == OACCARDI) {
    if (!(loc(CURTAIN) == APLANE)) {
      move(CURTAIN, APLANE);
      clearFlag(CURTAIN, NODESC);
    }
    return true;
  } else if ((g.ABOVE == OPLAIN) && !(loc(IMPS) == APLANE)) {
    move(IMPTAB, APLANE);
    move(IMPS, APLANE);
    await QUEUE(I_IMPS.id);
    return true;
  } else {
    return false;
  }
}

async function ANY_TOUCHED$(tbl, excluded = 0) {
  let len = 0, rm = 0, cnt = 0;
  len = getb(tbl, 0);
  cnt = 1;
  loop1: for (;;) {
    rm = getb(tbl, len);
    if (hasFlag(rm, TOUCHED) && (!(arguments.length > 1) || !(hasFlag(rm, excluded)))) {
      ++cnt;
      put(g.AUX_TABLE, cnt, rm);
    }
    if (--len < 1) {
      break loop1;
    }
  }
  if (cnt == 1) {
    return false;
  } else if (cnt == 2) {
    return get(g.AUX_TABLE, 2);
  }
  put(g.AUX_TABLE, 0, cnt);
  put(g.AUX_TABLE, 1, 0);
  return await PICK_ONE(g.AUX_TABLE);
}

async function DOWN_TO$() {
  let rm = 0, x = 0;
  if (g.ABOVE == ORUINS) {
    rm = await ANY_TOUCHED$(RUIN_ROOMS);
    if ((rm == 0) && (await SETUP_RUINS$())) {
      rm = await RANDOM_ROOM$(RUIN_ROOMS);
    }
    return rm;
  } else if (g.ABOVE == OBRIDGE) {
    g.BRIDGE_DIR = 0;
    g.ZTOP = 1;
    g.ZBOT = 2;
    return ON_BRIDGE;
  } else if (g.ABOVE == OFOREST) {
    rm = await ANY_TOUCHED$(FOREST_ROOMS);
    if ((rm == 0) && (await SETUP_FOREST$())) {
      rm = await RANDOM_ROOM$(FOREST_ROOMS);
    }
    return rm;
  } else if (g.ABOVE == OACCARDI) {
    rm = IN_ACCARDI;
    if (hasFlag(AT_GATE, TOUCHED) && prob(50)) {
      rm = AT_GATE;
    }
    return rm;
  } else if (g.ABOVE == OCITY) {
    rm = IN_GURTH;
    if (hasFlag(AT_MAGICK, TOUCHED)) {
      rm = AT_MAGICK;
    }
    return rm;
  } else if (g.ABOVE == OSHORE) {
    rm = await ANY_TOUCHED$(SHORE_ROOMS);
    if (rm == 0) {
      rm = AT_LEDGE;
    }
    return rm;
  } else if (g.ABOVE == OXROADS) {
    return XROADS;
  } else if (g.ABOVE == OPLAIN) {
    return false;
  } else if (g.ABOVE == OGRUBBO) {
    return HILLTOP;
  } else if (g.ABOVE == OCAVES) {
    return IN_GARDEN;
  } else if (g.ABOVE == OMOOR) {
    rm = await ANY_TOUCHED$(MOOR_ROOMS);
    if ((rm == 0) && (await SETUP_MOOR$())) {
      rm = await RANDOM_ROOM$(MOOR_ROOMS);
    }
    return rm;
  } else if (g.ABOVE == OJUNGLE) {
    rm = await ANY_TOUCHED$(JUNGLE_ROOMS);
    if ((rm == 0) && (await SETUP_JUNGLE$())) {
      rm = await RANDOM_ROOM$(JUNGLE_ROOMS);
    }
    return rm;
  } else if (g.ABOVE == OMIZNIA) {
    rm = await ANY_TOUCHED$(MIZNIA_ROOMS);
    if (rm == 0) {
      rm = IN_PORT;
    }
    return rm;
  } else if (g.ABOVE == OTHRIFF) {
    rm = IN_THRIFF;
    if (hasFlag(IN_THRIFF, MUNGED)) {
      rm = IN_PASTURE;
    }
    return rm;
  } else {
    return false;
  }
}

async function RANDOM_ROOM$(tbl) {
  let ohere = 0, rm = 0, x = 0;
  rm = getb(tbl, random(getb(tbl, 0)));
  if (!(hasFlag(rm, TOUCHED))) {
    ohere = g.HERE;
    g.HERE = rm;
    x = await apply(getProp(rm, P.ACTION), M_ENTERING);
    g.HERE = ohere;
    setFlag(rm, TOUCHED);
  }
  return rm;
}

async function PRE_TAKE() {
  let l = 0, ll = 0, who = 0, x = 0, x2 = 0;
  l = loc(g.PRSO);
  if (!(l == 0)) {
    ll = loc(l);
  }
  if ((g.LIT$ == 0) && !(g.WINNER == l || g.WINNER == ll)) {
    await TOO_DARK();
    return true;
  } else if (l == GLOBAL_OBJECTS) {
    await IMPOSSIBLE();
    return true;
  } else if (l == g.WINNER) {
    await THIS_IS_IT(g.PRSO);
    tell(S(g.ALREADY));
    if (hasFlag(g.PRSO, WORN)) {
      tell(wordText(W.WEAR));
    } else {
      tell(wordText(W.HOLD));
    }
    tell("ing ");
    await THE_PRINT();
    tell(S(g.PERIOD));
    return true;
  } else if (!(l == false || l == BROG) && hasFlag(l, CONTAINER) && hasFlag(l, TRANSPARENT) && !(hasFlag(l, OPENED))) {
    await CANT_REACH_INTO(l);
    return true;
  } else if (!(ll == false || ll == BROG) && hasFlag(ll, CONTAINER) && hasFlag(ll, TRANSPARENT) && !(hasFlag(ll, OPENED))) {
    await CANT_REACH_INTO(ll);
    return true;
  } else if (!(g.PRSI == 0)) {
    if (g.PRSO == g.PRSI) {
      x = get(g.P_NAMW, 0);
      x2 = get(g.P_ADJW, 0);
      if ((x == get(g.P_NAMW, 1)) || (x2 == get(g.P_ADJW, 1))) {
        await IMPOSSIBLE();
        return true;
      }
    } else if (g.PRSI == ME) {
      if (g.WINNER == PLAYER) {
        await NOBODY_TO_ASK();
        return true;
      } else if (!(l == g.WINNER)) {
        await CTHE_PRINT(g.WINNER);
        tell(" doesn't have ");
        await THE_PRINT();
        tell(S(g.PERIOD));
        return true;
      } else {
        return false;
      }
    } else if (!(l == g.PRSI)) {
      if ((l == ON_MCASE || l == ON_WCASE || l == ON_BCASE) && (g.PRSI == MCASE || g.PRSI == WCASE || g.PRSI == BCASE)) {
        return false;
      }
      await CTHE_PRINT();
      await ISNT_ARENT();
      await ON_IN(g.PRSI);
      tell(S(g.PERIOD));
      return true;
    }
    return false;
  } else if (g.PRSO == loc(g.WINNER)) {
    if (g.PRSO == BUSH || g.PRSO == POOL) {
      return false;
    }
    tell("Difficult. You're");
    await ON_IN();
    tell(S(g.PERIOD));
    return true;
  } else {
    return false;
  }
}

