async function ITAKE(vb = true) {
  let cnt = 0, obj = 0, l = 0, x = 0, max = 0;
  if ((g.PRSO == 0) || !(l = loc(g.PRSO))) {
    await CANT_SEE_ANY();
    return false;
  }
  await THIS_IS_IT(g.PRSO);
  if (!(hasFlag(g.PRSO, TAKEABLE))) {
    if (!(vb == 0)) {
      await IMPOSSIBLE();
    }
    return false;
  } else if (hasFlag(l, CONTAINER) && hasFlag(l, OPENABLE) && !(hasFlag(l, OPENED)) && !(l == loc(g.WINNER))) {
    if (!(vb == 0)) {
      (await YOUD_HAVE_TO("open", l));
    }
    return false;
  }
  if ((g.WINNER == UNICORN) && (x = first(g.WINNER))) {
    move(x, loc(g.WINNER));
    tell("[putting down ");
    await THE_PRINT(x);
    tell(" first", S(g.BRACKET));
  } else if (g.WINNER == PLAYER) {
    if (loc(ONION) == PLAYER) {
      if (!(vb == 0)) {
        (await YOUD_HAVE_TO("put down", ONION));
      }
      return false;
    }
    x = await WEIGHT(g.PRSO);
    max = LOAD_ALLOWED + div(get(g.STATS, STRENGTH), 10);
    if (!(loc(l) == g.WINNER) && (s16(x + (await WEIGHT(g.WINNER))) > s16(max))) {
      if (!(vb == 0)) {
        if (x = first(g.WINNER)) {
          tell("Your load is ");
        } else {
          await CTHE_PRINT();
          await IS_ARE();
        }
        tell("too heavy.\n");
      }
      return false;
    }
    if (obj = first(g.WINNER)) {
      loop1: for (;;) {
        if (hasFlag(obj, NODESC)) {
        } else if (hasFlag(obj, WORN)) {
        } else if (hasFlag(obj, TAKEABLE)) {
          ++cnt;
        }
        if (!(obj = next(obj))) {
          break loop1;
        }
      }
    }
    max = FUMBLE_NUMBER + div(get(g.STATS, DEXTERITY), 10);
    if (s16(cnt) > s16(max)) {
      if (!(vb == 0)) {
        tell("Your hands are full.\n");
      }
      return false;
    }
  }
  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
  setFlag(g.PRSO, TOUCHED);
  clearFlag(g.PRSO, NODESC);
  clearFlag(g.PRSO, NOALL);
  move(g.PRSO, g.WINNER);
  return l;
}

async function WEIGHT(thing) {
  let wt = 0, obj = 0;
  if (obj = first(thing)) {
    loop1: for (;;) {
      if ((thing == g.WINNER) && hasFlag(obj, WORN)) {
        ++wt;
      } else {
        wt = wt + (await WEIGHT(obj));
      }
      if (!(obj = next(obj))) {
        break loop1;
      }
    }
  }
  return wt + getProp(thing, P.SIZE);
}

