async function PRINT_INVENTORY() {
  let holds = 0, worns = 0, any = 0, b = 0, obj = 0, nxt = 0;
  if (!(obj = first(g.WINNER))) {
    await NUTHIN();
    return true;
  }
  g.INV_PRINTING$ = true;
  loop1: for (;;) {
    nxt = next(obj);
    if (hasFlag(obj, NODESC) || !(hasFlag(obj, TAKEABLE))) {
      move(obj, DUMMY_OBJECT);
    } else if (hasFlag(obj, CLOTHING) && hasFlag(obj, WORN)) {
      ++worns;
      move(obj, WEARING);
    } else if ((obj == GOBLET) && (loc(BFLY) == obj) && hasFlag(BFLY, LIVING)) {
      ++b;
      setFlag(BFLY, NODESC);
    }
    if ((await SEE_INSIDE$(obj)) && (await SEE_ANYTHING_IN$(obj))) {
      ++holds;
      move(obj, HOLDING);
    }
    obj = nxt;
    if (obj == 0) {
      break loop1;
    }
  }
  if (obj = first(g.WINNER)) {
    loop2: for (;;) {
      nxt = next(obj);
      if (hasFlag(obj, WIELDED)) {
        remove(obj);
        move(obj, g.WINNER);
      }
      obj = nxt;
      if (obj == 0) {
        break loop2;
      }
    }
    ++any;
    tell("You're carrying ");
    await CONTENTS(g.WINNER);
    printS(g.PERIOD);
  }
  if (!(holds == 0)) {
    if (!(any == 0)) {
      tell(S(g.TAB), "You're also ");
    } else {
      tell("You're ");
    }
    ++any;
    tell("carrying ");
    await CONTENTS(HOLDING);
    if (obj = first(HOLDING)) {
      loop3: for (;;) {
        tell(". ");
        if (obj == GURDY) {
          tell("Within");
        } else if (hasFlag(obj, CONTAINER)) {
          tell("Inside");
        } else {
          tell("Upon");
        }
        tell(C(SP));
        await THE_PRINT(obj);
        tell(" you see ");
        await CONTENTS(obj);
        if (!(obj = next(obj))) {
          break loop3;
        }
      }
    }
    tell(S(g.PERIOD));
    await MOVE_ALL(HOLDING, g.WINNER);
  }
  if (!(worns == 0)) {
    if (!(any == 0)) {
      tell(S(g.TAB));
    }
    ++any;
    tell("You're wearing ");
    await CONTENTS(WEARING);
    if (obj = first(WEARING)) {
      loop4: for (;;) {
        if ((await SEE_INSIDE$(obj)) && (await SEE_ANYTHING_IN$(obj))) {
          tell(". ");
          if (hasFlag(obj, CONTAINER)) {
            tell("Inside");
          } else {
            tell("Upon");
          }
          tell(C(SP));
          await THE_PRINT(obj);
          tell(" you see ");
          await CONTENTS(obj);
        }
        if (!(obj = next(obj))) {
          break loop4;
        }
      }
    }
    tell(S(g.PERIOD));
    await MOVE_ALL(WEARING, g.WINNER);
  }
  await MOVE_ALL(DUMMY_OBJECT, g.WINNER);
  if (any == 0) {
    await NUTHIN();
  } else if (!(g.LOOT == 0)) {
    tell(S(g.TAB));
    await SAY_CASH();
  }
  if (!(b == 0)) {
    clearFlag(BFLY, NODESC);
  }
  g.INV_PRINTING$ = false;
  return true;
}

