async function EMPTY_PRSO(dest) {
  let any = 0, obj = 0, nxt = 0, x = 0, icap = 0, iload = 0, osize = 0;
  if (!(dest == 0)) {
    x = loc(dest);
    if ((x == 0) || (g.PRSO == dest)) {
      await IMPOSSIBLE();
      return true;
    } else if ((x == g.PRSO) || (loc(x) == g.PRSO)) {
      (await YOUD_HAVE_TO("remove", dest));
      return true;
    }
  } else {
    dest = g.WINNER;
  }
  if (!(await SEE_ANYTHING_IN$())) {
    tell("There's nothing");
    await ON_IN();
    tell(S(g.PERIOD));
    return true;
  }
  g.P_MULT$ = true;
  if (!(dest == g.WINNER || dest == loc(g.WINNER))) {
    iload = await WEIGHT(dest);
    iload = iload - getProp(dest, P.SIZE);
    icap = getProp(dest, P.CAPACITY);
  }
  if (obj = first(g.PRSO)) {
    loop1: for (;;) {
      nxt = next(obj);
      if (!(hasFlag(obj, TAKEABLE))) {
      } else if (!(hasFlag(obj, NODESC))) {
        ++any;
        osize = getProp(obj, P.SIZE);
        if (!(hasFlag(obj, NOARTICLE))) {
          tell(S(g.XTHE));
        }
        await DPRINT(obj);
        tell(": ");
        if (dest == g.WINNER) {
          x = await PERFORM(V.TAKE, obj, g.PRSO);
          if (x == M_FATAL) {
            break loop1;
          }
        } else if (dest == loc(g.WINNER)) {
          if (hasFlag(obj, PLURAL)) {
            tell("They ");
          } else {
            tell("It ");
          }
          await FALLS(obj);
        } else if (s16(osize) > s16(icap)) {
          await CTHE_PRINT(obj);
          await IS_ARE(obj);
          tell("too big to fit in ");
          await THE_PRINT(dest);
          tell(S(g.PERIOD));
        } else if (s16(iload + osize) > s16(icap)) {
          await NO_ROOM_IN(dest);
        } else {
          clearFlag(obj, WIELDED);
          move(obj, dest);
          tell("Done.\n");
        }
      }
      obj = nxt;
      if (obj == 0) {
        break loop1;
      }
    }
  }
  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
  g.P_MULT$ = false;
  if (any == 0) {
    tell(S(g.NOTHING), "you can take.\n");
  }
  return true;
}

