async function V_PUT() {
  let ol = 0, icap = 0, iload = 0, osize = 0;
  ol = loc(g.PRSO);
  if ((ol == 0) || (!(g.PRSI == 0) && !(hasFlag(g.PRSI, SURFACE)) && !(hasFlag(g.PRSI, CONTAINER)))) {
    await IMPOSSIBLE();
    return true;
  } else if (!(hasFlag(g.PRSI, OPENED)) && !(hasFlag(g.PRSI, SURFACE))) {
    await THIS_IS_IT(g.PRSI);
    await CTHEI_PRINT();
    await ISNT_ARENT(g.PRSI);
    tell(" open.\n");
    return true;
  } else if (!(ol == g.WINNER)) {
    tell("Maybe you should take ");
    await THE_PRINT();
    await OUT_OF_LOC(ol);
    tell(S(g.SFIRST));
    return true;
  }
  iload = await WEIGHT(g.PRSI);
  iload = iload - getProp(g.PRSI, P.SIZE);
  icap = getProp(g.PRSI, P.CAPACITY);
  osize = getProp(g.PRSO, P.SIZE);
  if (s16(osize) > s16(icap)) {
    await CTHE_PRINT();
    await IS_ARE();
    tell("too big to fit");
    await ON_IN(g.PRSI);
    tell(S(g.PERIOD));
    return true;
  } else if (s16(iload + osize) > s16(icap)) {
    await NO_ROOM_IN(g.PRSI);
    return true;
  }
  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
  clearFlag(g.PRSO, WIELDED);
  move(g.PRSO, g.PRSI);
  setFlag(g.PRSO, TOUCHED);
  if (!(g.P_MULT$ == 0)) {
    tell("Done.\n");
    return true;
  }
  tell("You put ");
  await THE_PRINT();
  await ON_IN(g.PRSI);
  tell(S(g.PERIOD));
  return true;
}

