async function V_TAKE_OFF() {
  let x = 0;
  if (g.PRSO == ROOMS) {
    x = loc(g.WINNER);
    if ((g.P_PRSA_WORD == W.GET) && !(x == g.HERE) && hasFlag(x, VEHICLE)) {
      await PERFORM(V.EXIT, x);
      return true;
    }
    await V_WALK_AROUND();
    return true;
  } else if (g.PRSO == HANDS || g.PRSO == FEET) {
    await IMPOSSIBLE();
    return true;
  } else if (hasFlag(g.PRSO, PLACE)) {
    await NOT_IN();
    return true;
  } else if (hasFlag(g.PRSO, TAKEABLE)) {
    x = loc(g.PRSO);
    if (x == 0) {
      await REFERRING();
      return true;
    } else if ((x == g.WINNER) && hasFlag(g.PRSO, CLOTHING)) {
      if (hasFlag(g.PRSO, WORN)) {
        if (await HOTFOOT$()) {
          return true;
        }
        await TAKEOFF();
        x = getProp(g.PRSO, P.EFFECT);
        if (!(x == 0)) {
          await UPDATE_STAT(0 - x, ARMOR_CLASS);
        }
        return true;
      }
      printS("You're not wearing ");
      await THE_PRINT();
      tell(S(g.PERIOD));
      return true;
    } else if (!(hasFlag(x, SURFACE))) {
      await CTHE_PRINT();
      tell(" isn't \"on\" anything.\n");
      return true;
    }
    await PERFORM(V.TAKE, g.PRSO);
    return true;
  } else if (hasFlag(g.PRSO, VEHICLE)) {
    await PERFORM(V.EXIT, g.PRSO);
    return true;
  }
  await IMPOSSIBLE();
  return true;
}

