async function V_NAME(obj = g.PRSO) {
  let tbl = 0, word = 0, base = 0, len = 0, ptr = 0, char = 0, complex = 0, bad = 0, any = 0, x = 0;
  await PCLEAR();
  tbl = getProp(obj, P.NAME_TABLE);
  if (!(hasFlag(obj, NAMEABLE)) || (tbl == 0)) {
    tell("Alas; ");
    await THE_PRINT(obj);
    if (hasFlag(g.PRSO, PERSON)) {
      tell(" already ha");
      if (hasFlag(g.PRSO, PLURAL)) {
        tell("ve");
      } else {
        tell("s");
      }
      tell(" a Name.\n");
      return true;
    }
    tell(" cannot be Named.\n");
    return true;
  } else if (hasFlag(obj, NAMED)) {
    tell("You've already assigned a Name to ");
    await THE_PRINT(obj);
    tell(". To alter that Name, you must first Unmake ");
    await PRONOUN(obj, true);
    tell(", a dangerous procedure requiring years of magical training. Someday, perhaps...\n");
    return true;
  }
  copyTable(tbl, 0, 13);
  base = g.P_LEXV + (g.P_QWORD * 2);
  len = getb(base, 2);
  putb(g.AUX_TABLE, 0, len);
  base = g.P_INBUF + getb(base, 3);
  copyTable(base, g.AUX_TABLE + 1, len);
  putb(g.AUX_TABLE, len + 1, 0);
  ptr = len;
  bad = 0;
  any = 0;
  loop1: for (;;) {
    char = getb(g.AUX_TABLE, ptr);
    if ((s16(char) > s16(NaN)) && (s16(char) < s16(NaN))) {
      ++any;
    } else {
      ++bad;
      break loop1;
    }
    if (--ptr < 1) {
      break loop1;
    }
  }
  if ((any == 0) || !(bad == 0)) {
    (await HOLLOW_VOICE("too complex"));
    return true;
  } else if (s16(len) > s16(11)) {
    (await HOLLOW_VOICE("too long"));
    return true;
  }
  ptr = 1;
  loop2: for (;;) {
    char = getb(g.AUX_TABLE, ptr);
    if (ptr == 1) {
      char = char - 32;
    }
    putb(tbl, ptr, char);
    if (++ptr > len) {
      break loop2;
    }
  }
  putb(tbl, 0, len);
  putb(tbl, len + 1, 0);
  word = await ADD_VOCAB(g.AUX_TABLE, obj);
  await ADD_CAP$(word);
  setFlag(obj, NAMED);
  setFlag(obj, NOARTICLE);
  setFlag(obj, PROPER);
  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
  tell("You invoke the Spell of Naming, and the ");
  if ((obj == BFLY) && hasFlag(BFLY, MUNGED)) {
    printS("caterpillar");
  } else if ((obj == PHASE) && !(g.HERE == APLANE)) {
    tell(wordText(W.OUTLINE));
  } else {
    printD(obj);
  }
  tell(" basks in the glow of a new-forged synonym. Henceforth, you may refer to ");
  await PRONOUN(obj, true);
  tell(" as \"");
  await PRINT_TABLE(tbl);
  tell(S(g.PERQ));
  return true;
}

async function ADD_VOCAB(tbl, obj) {
  let wrd = 0, syns = 0, sibs = 0, elen = 0, cnt = 0, base = 0, len = 0;
  syns = getPropAddr(obj, P.SYNONYM);
  wrd = get(syns, 0);
  sibs = getb(VOCAB2, 0);
  elen = getb(VOCAB2 + (sibs + 1), 0);
  cnt = get(VOCAB2 + (sibs + 2), 0);
  base = VOCAB2 + (sibs + 4);
  if (!(cnt == 0)) {
    base = base + (elen * (0 - cnt));
  }
  encodeWord(tbl, getb(tbl, 0), 1, base);
  tbl = wrd + 6;
  len = elen - 6;
  copyTable(tbl, base + 6, len);
  --cnt;
  put(VOCAB2 + (sibs + 2), 0, cnt);
  put(syns, 1, base);
  return base;
}

