async function BUY_X_WITH_Y(x = g.PRSO, y = g.PRSI) {
  let case_ = 0, val = 0, offer = 0, change = 0;
  case_ = getProp(g.HERE, P.THIS_CASE);
  if (!(await VISIBLE$(x))) {
    tell("\"I don't have any for sale,\" admits ");
    await THE_PRINT(OWOMAN);
    tell(S(g.PERIOD));
    return true;
  } else if (!(loc(x) == case_)) {
    tell("\"Only the items in ");
    await THE_PRINT(case_);
    tell(" are for sale.\"\n");
    return true;
  }
  val = getProp(x, P.VALUE);
  if (s16(val) < s16(1)) {
    await NO_WORTH(x);
    return true;
  } else if (y == false || y == MONEY || y == INTNUM) {
    offer = g.P_NUMBER;
    if (g.LOOT == 0) {
      printS("You're broke.\n");
      return true;
    } else if ((y == 0) || (g.P_NUMBER == (-1))) {
      offer = g.LOOT;
    } else if (await NOT_ENOUGH_LOOT$(offer)) {
      return true;
    }
    if (s16(offer) < s16(val)) {
      tell(S(g.CTHELADY), " shakes her head firmly. \"My price is ");
      await SAY_LOOT(val);
      tell(", dear.\"\n");
      return true;
    }
    putProp(x, P.VALUE, div(val, 2));
    if (!(g.P_NUMBER == (-1)) && (s16(offer) > s16(val))) {
      g.LOOT = g.LOOT - g.P_NUMBER;
      printS("\"You are too kind");
    } else {
      g.LOOT = offer - val;
      tell("\"Done");
    }
    tell(",\" says ");
    await THE_PRINT(OWOMAN);
    tell(", taking your zorkmid");
    if (!(val == 1)) {
      tell("s");
    }
    await SOLD(x);
    return true;
  } else if (await NO_DEAL$(y)) {
    return true;
  } else if (loc(y) == GLOBAL_OBJECTS) {
    tell("\"Don't be silly.\"\n");
    return true;
  }
  offer = getProp(y, P.VALUE);
  if (offer == 0) {
    await NO_WORTH(y);
    return true;
  } else if (s16(offer) < s16(val)) {
    await WORTHLESS(y);
    tell(" only worth ");
    await SAY_LOOT(offer);
    tell(". This ");
    await DPRINT(x);
    tell(" is valued at ");
    await SAY_LOOT(val);
    tell("!\"\n");
    return true;
  }
  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
  move(y, case_);
  setFlag(y, USED);
  putProp(y, P.VALUE, offer + offer);
  putProp(x, P.VALUE, div(val, 2));
  if (s16(offer) > s16(val)) {
    printS("\"You are too kind");
  } else {
    tell("\"Done");
  }
  tell(",\" says ");
  await THE_PRINT(OWOMAN);
  tell(", taking ");
  await SAY_YOUR(y);
  if (s16(offer) > s16(val)) {
    change = offer - val;
    g.LOOT = g.LOOT + change;
    await SOLD(x, change);
    printS(" and handing you ");
    await SAY_LOOT(change);
    tell(" in change.\n");
    return true;
  }
  await SOLD(x);
  return true;
}

async function SOLD(obj, change = 0) {
  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
  await THIS_IS_IT(obj);
  setFlag(obj, USED);
  if (!(change == 0)) {
    tell(", ");
  } else {
    tell(S(g.AND));
  }
  if (await ITAKE(false)) {
    move(obj, PLAYER);
    tell("handing you ");
    await THE_PRINT(obj);
  } else {
    move(obj, getProp(getProp(g.HERE, P.THIS_CASE), P.DNUM));
    tell("setting ");
    await THE_PRINT(obj);
    tell(S(g.SON));
    await THE_PRINT(MCASE);
  }
  if (change == 0) {
    printS(g.PERIOD);
  }
  return true;
}

