async function TRADE_FOR_LOOT(obj) {
  let val = 0, case_ = 0;
  if (!(loc(obj) == PLAYER)) {
    await TAKE_FIRST(obj, loc(obj));
    return true;
  }
  if (await NO_DEAL$(obj)) {
    return true;
  }
  val = getProp(obj, P.VALUE);
  case_ = getProp(g.HERE, P.THIS_CASE);
  tell(S(g.CTHELADY), " examines ");
  await THE_PRINT(obj);
  if (val == 0) {
    tell(" and hands it back to you with a shrug. \"Worthless.\"\n");
    return true;
  }
  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
  g.LOOT = val + g.LOOT;
  tell(" critically. \"Okay,\" she agrees, ");
  if (obj == TRUFFLE) {
    await VANISH(obj);
    tell("popping ");
    await THE_PRINT(obj);
    tell(" in her mouth");
  } else {
    putProp(obj, P.VALUE, val + val);
    move(obj, case_);
    tell("stashing it away in ");
    await THE_PRINT(case_);
  }
  printS(" and handing you ");
  await SAY_LOOT(val);
  tell(" in return.\n");
  return true;
}

