async function V_SAVE() {
  let x = 0, stat = 0;
  if (await CANT_SAVE$()) {
    return true;
  }
  tell("You mumble the Spell of Saving.\n");
  await PCLEAR();
  g.OLD_HERE = false;
  putb(g.OOPS_INBUF, 1, 0);
  stat = ENDURANCE;
  g.CHECKSUM = 0;
  loop1: for (;;) {
    g.CHECKSUM = g.CHECKSUM + get(g.STATS, stat);
    if (++stat > EXPERIENCE) {
      break loop1;
    }
  }
  stat = ENDURANCE;
  loop2: for (;;) {
    g.CHECKSUM = g.CHECKSUM + get(g.MAXSTATS, stat);
    if (++stat > EXPERIENCE) {
      break loop2;
    }
  }
  g.CHECKSUM = 0 - g.CHECKSUM;
  x = await save();
  if ((x == 2) || btst(get(0, 8), 4)) {
    await INITVARS();
    await V_REFRESH();
  }
  if (x == 0) {
    (await FAILED("SAVE"));
    return M_FATAL;
  } else if (x == 1) {
    (await COMPLETED("SAVE"));
    return M_FATAL;
  }
  (await COMPLETED("RESTORE"));
  crlf();
  await V_LOOK();
  stat = ENDURANCE;
  x = 0;
  loop3: for (;;) {
    x = x + get(g.STATS, stat);
    if (++stat > EXPERIENCE) {
      break loop3;
    }
  }
  stat = ENDURANCE;
  loop4: for (;;) {
    x = x + get(g.MAXSTATS, stat);
    if (++stat > EXPERIENCE) {
      break loop4;
    }
  }
  if (!(eq(0 - g.CHECKSUM, x))) {
    await CHEATER();
  }
  return M_FATAL;
}

