  tell(", ");
  await THE_PRINT(VAPOR);
  tell(" grabs you by the ankles and lifts you high into the air!\n");
  if (!(g.VERBOSITY == 0)) {
    crlf();
  }
  await GOTO(rm);
  x = get(g.STATS, ENDURANCE);
  if (s16(x) > s16(5)) {
    x = -5;
  } else {
    x = 0 - (x - 1);
  }
  await UPDATE_STAT(x);
