async function MOVE_SUCKERS(obj, nxt = 0) {
  let damage = 0, l = 0, pl = 0, dir = 0, tbl = 0, dest = 0, x = 0;
  let $1, $2, $3;
  l = loc(obj);
  if (l == g.HERE) {
    tell(S(g.TAB));
    if (s16(getProp(obj, P.ENDURANCE)) < s16(1)) {
      tell("Squealing with fear, ");
      await THE_PRINT(obj);
      tell(" retreats down the passageway.\n");
      if (!(nxt == 0)) {
        await NEXT_MONSTER(nxt);
        await NEXT_SUCKER(nxt);
      }
      await KILL_MONSTER(obj);
      return true;
    } else if (hasFlag(obj, SURPRISED)) {
      await SEE_MONSTER(obj);
      if (g.LIT$ == 0) {
        await DARK_MOVES();
        return true;
      }
      await CTHE_PRINT(obj);
      tell(" glances up as you appear.\n");
      return true;
    } else if (prob(20)) {
      putProp(obj, P.ENDURANCE, getProp(obj, P.EMAX));
      g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
      if (!(g.LIT$ == 0)) {
        await BLINK(obj);
        tell(" turns into ");
      }
      await NEXT_SUCKER(obj);
      if (!(g.LIT$ == 0)) {
        await PRINTA(obj);
        tell("!\n");
        return true;
      }
      tell(S(g.YOU_HEAR), "a curious sound in the darkness.\n");
      return true;
    }
    x = get(g.STATS, LUCK);
    if (s16(x) > s16(9)) {
      damage = div(10 * x, 100);
    } else if (s16(x) > s16(1)) {
      damage = 1;
    }
    await NEXT_ENDURANCE$(obj);
    x = getProp(g.HERE, P.MIRROR_OBJ);
    if (!(x == false || x == NO_MIRROR)) {
      if (!(g.LIT$ == 0)) {
        await CTHE_PRINT(obj);
        tell(S(get(SUCKER_SMASHES, g.THIS_SUCKER)), S(g.PTAB));
        (await ITALICIZE("Pop"));
        tell("!\n");
      } else {
        tell(S(g.YOU_HEAR), "a flabby ");
        (await ITALICIZE("pop"));
        tell(" in the darkness.\n");
      }
      await DESTROY_MIRROR(x);
      if (await NOLUCK$()) {
        await UPDATE_STAT(0 - damage, LUCK, true);
      }
      return true;
    } else if (g.LIT$ == 0) {
    } else if (prob(67)) {
      await CTHE_PRINT(obj);
      $1 = await PICK_NEXT(get(SUCKER_HITS, g.THIS_SUCKER));
      tell(S($1));
      tell(S(g.PERIOD));
      if (await NOLUCK$()) {
        await UPDATE_STAT(0 - damage, LUCK, true);
      }
      return true;
    }
    if (!(g.LIT$ == 0)) {
      await CTHE_PRINT(obj);
      $2 = await PICK_NEXT(get(SUCKER_MISSES, g.THIS_SUCKER));
      tell(S($2));
      tell(S(g.PERIOD));
      return true;
    }
    tell("Something ");
    $3 = await PICK_NEXT(SUCKER_STALKS);
    tell(S($3));
    tell(" you in the darkness.\n");
    return true;
  }
  dir = await MOVE_MONSTER$(obj);
  if (!(dir == 0)) {
    tell(S(g.TAB));
    if (g.LIT$ == 0) {
      tell(S(g.YOU_HEAR), wordText(W.SOMETHING), " stalk into the passage.\n");
      return true;
    } else if (hasFlag(obj, SEEN)) {
      tell(S(g.XTHE));
    } else {
      setFlag(obj, SEEN);
      tell(S(g.XA));
    }
    await DPRINT(obj);
    tell(" stalks in from the ", wordText(dir), " passage.\n");
    return true;
  }
  x = getProp(loc(obj), P.MIRROR_OBJ);
  if (x == false || x == NO_MIRROR) {
    return false;
  }
  tell(S(g.TAB), S(g.YOU_HEAR), "a distant patter of stalking feet, then a flabby ");
  (await ITALICIZE("pop"));
  printS(g.PERIOD);
  await DESTROY_MIRROR(x);
  return true;
}

async function NEXT_SUCKER(obj) {
  let x = 0;
  loop1: for (;;) {
    x = await PICK_ONE(SUCKER_TYPES);
    if (x == g.THIS_SUCKER) {
      continue loop1;
    }
    break loop1;
  }
  g.THIS_SUCKER = x;
  x = getPropAddr(obj, P.SYNONYM);
  put(x, 0, get(SUCKER_SYNS_A, g.THIS_SUCKER));
  put(x, 1, get(SUCKER_SYNS_B, g.THIS_SUCKER));
  x = getPropAddr(obj, P.ADJECTIVE);
  put(x, 0, get(SUCKER_ADJS, g.THIS_SUCKER));
  return false;
}

