async function I_GONDOLA() {
  let riding = 0;
  if (loc(g.WINNER) == GONDOLA) {
    ++riding;
  }
  if (++g.GON > 14) {
    g.GON = 0;
    await REPLACE_GLOBAL$(AT_DOCK, DGONDOLA, NULL);
    move(GONDOLA, AT_DOCK);
    setFlag(GONDOLA, OPENED);
    if (!(riding == 0)) {
      g.HERE = AT_DOCK;
    } else if (g.HERE == AT_DOCK) {
      g.P_IT_OBJECT = GONDOLA;
    } else {
      return false;
    }
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
    tell(S(g.TAB));
    await CTHE_PRINT(GONDOLA);
    tell(" glides to a halt at ");
    await THE_PRINT(DOCK);
    tell(S(g.PTAB), "\"All off,\" calls ");
    await THE_PRINT(CONDUCTOR);
    tell(" as the hatch swings open. ");
    printS("\"Thank you for riding the Miznia Jungle Skyway");
    tell(". Please exit the Skycar in an orderly manner.\"\n");
    return true;
  } else if (g.GON == 1) {
    if (!(g.HERE == AT_DOCK)) {
      return false;
    }
    tell(S(g.TAB), "The last few ", D(PASSENGERS), " are shuffling out of ");
    await THE_PRINT(GONDOLA);
    if (!(riding == 0)) {
      tell(". \"All off, please,\" repeats ");
      await THE_PRINT(CONDUCTOR);
      tell(", meaning you");
    }
    tell(S(g.PERIOD));
    return true;
  } else if (g.GON == 2) {
    if (!(g.HERE == AT_DOCK)) {
      return false;
    }
    tell(S(g.TAB));
    if (!(riding == 0)) {
      move(PLAYER, AT_DOCK);
      setFlag(GONDOLA, NODESC);
      g.P_WALK_DIR = false;
      printS("\"Thank you for riding the Miznia Jungle Skyway");
      tell(",\" growls ");
      await THE_PRINT(CONDUCTOR);
      tell(", pushing you out of ");
      await THE_PRINT(GONDOLA);
      await RELOOK();
    }
    tell("Eager ", D(PASSENGERS), " surge into the emptied ", D(GONDOLA), ". \"All aboard, please,\" announces ");
    await THE_PRINT(CONDUCTOR);
    tell(" unnecessarily.\n");
    return true;
  } else if (g.GON == 3) {
    clearFlag(GONDOLA, OPENED);
    if (!(riding == 0)) {
    } else if (!(g.HERE == AT_DOCK)) {
      return false;
    }
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
    tell(S(g.TAB), "\"Stay clear of the door, please,\" calls ");
    await THE_PRINT(CONDUCTOR);
    tell(" as the last few ", D(PASSENGERS), " squeeze into ");
    await THE_PRINT(GONDOLA);
    tell(S(g.PERIOD));
    return true;
  } else if (g.GON == 4) {
    move(GONDOLA, OVER_JUNGLE);
    await REPLACE_GLOBAL$(AT_DOCK, NULL, DGONDOLA);
    if (!(riding == 0)) {
      g.P_WALK_DIR = false;
      g.OLD_HERE = false;
      g.HERE = OVER_JUNGLE;
    } else if (g.HERE == AT_DOCK) {
      g.P_IT_OBJECT = DGONDOLA;
    } else {
      return false;
    }
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
    tell(S(g.TAB));
    await CTHE_PRINT(GONDOLA);
    tell(" slides away from the dock and glides west, high over ");
    await THE_PRINT(JUNGLE);
    tell(S(g.PTAB), "\"Welcome to the Miznia Jungle Skyway.\" drawls ");
    await THE_PRINT(CONDUCTOR);
    tell(", his voice heavy with boredom.\n");
    return true;
  } else if (g.GON == 5) {
    await REPLACE_GLOBAL$(AT_DOCK, DGONDOLA, NULL);
    await REPLACE_GLOBAL$(NW_SUPPORT, NULL, DGONDOLA);
    await REPLACE_GLOBAL$(NW_UNDER, NULL, DGONDOLA);
    await REPLACE_GLOBAL$(OVER_JUNGLE, DOCK, SUPPORT);
    putProp(NW_UNDER, P.OVERHEAD, DGONDOLA);
    if (g.HERE == AT_DOCK) {
      await GONDOLA_GONE(W.WEST);
      return true;
    } else if (g.HERE == NW_SUPPORT || g.HERE == NW_UNDER) {
      await VIEWGLIDE(NW_UNDER, W.EAST);
      return true;
    } else if (riding == 0) {
      return false;
    }
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
    g.P_IT_OBJECT = SUPPORT;
    tell(S(g.TAB));
    await CTHE_PRINT(GONDOLA);
    tell(" glides over ");
    await THE_PRINT(JUNGLE);
    tell(", towards a tall ", D(SUPPORT), S(g.PTAB), "\"The jungles of Miznia are the spawning grounds of the deadly ", D(WORM), ",\" drones ");
    await THE_PRINT(CONDUCTOR);
    tell(". \"Often mistaken for a mossy boulder, the ", D(WORM), "'s fangs extend up to 32 inches during an attack.\"\n  \"Oooh,\" murmurs the crowd.\n");
    return true;
  } else if (g.GON == 6) {
    move(GONDOLA, NW_SUPPORT);
    if (g.HERE == NW_SUPPORT) {
      await GLIDING();
    } else if (riding == 0) {
      return false;
    } else {
      await GLIDE_PAST(NW_SUPPORT);
    }
    tell(S(g.TAB), "\"The tower to your right is one of several erected to elevate the Skyway above the treetops,\" explains ");
    await THE_PRINT(CONDUCTOR);
    tell(". \"Before the Skyway opened in 882 GUE, an average of twenty Miznia Jungle Train passengers died of wormbite each year.\"\n  The crowd giggles nervously.\n");
    return true;
  } else if (g.GON == 7) {
    move(GONDOLA, OVER_JUNGLE);
    if (!(riding == 0)) {
      g.HERE = OVER_JUNGLE;
    } else if (g.HERE == NW_SUPPORT) {
      g.P_IT_OBJECT = DGONDOLA;
    } else {
      return false;
    }
    await TURNS(W.SOUTH);
    if (riding == 0) {
      return true;
    }
    tell(S(g.TAB), "\"The jungle is a rich source of exciting stories,\" continues ");
    await THE_PRINT(CONDUCTOR);
    tell(", stifling a yawn. \"The most famous is the Legend of the Crocodile's Tear.\"\n");
    return true;
  } else if (g.GON == 8) {
    await REPLACE_GLOBAL$(NW_SUPPORT, DGONDOLA, NULL);
    await REPLACE_GLOBAL$(NW_UNDER, DGONDOLA, NULL);
    putProp(NW_UNDER, P.OVERHEAD, SUPPORT);
    await REPLACE_GLOBAL$(SW_SUPPORT, NULL, DGONDOLA);
    await REPLACE_GLOBAL$(SW_UNDER, NULL, DGONDOLA);
    putProp(SW_UNDER, P.OVERHEAD, DGONDOLA);
    if (g.HERE == NW_SUPPORT || g.HERE == NW_UNDER) {
      g.P_IT_OBJECT = NOT_HERE_OBJECT;
      g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
      tell(S(g.TAB));
      await CTHE_PRINT(GONDOLA);
      tell(" glides southward, and is soon out of sight.\n");
      return true;
    } else if (g.HERE == SW_SUPPORT || g.HERE == SW_UNDER) {
      await VIEWGLIDE(SW_UNDER, W.NORTH);
      return true;
    } else if (riding == 0) {
      return false;
    }
    await JUNGLE_GLIDE();
    tell(S(g.TAB), "\"The Crocodile's Tear is a sapphire of extraordinary size and clarity. It was discovered by a slave working the granola mines of Antharia, who died bringing it to the surface.\"\n");
    tell(S(g.TAB), "Another ", D(SUPPORT), " is approaching.\n");
    return true;
  } else if (g.GON == 9) {
    move(GONDOLA, SW_SUPPORT);
    if (g.HERE == SW_SUPPORT) {
      await GLIDING();
    } else if (riding == 0) {
      return false;
    } else {
      await GLIDE_PAST(SW_SUPPORT);
    }
    tell(S(g.TAB), "\"After passing through many hands, including those of Thaddium Fzort\" (\"Bless you,\" mutters a passenger), \"the jewel came into the possession of the evil sorceress Y'Syska, whose collection of gems and minerals is still without peer.\"\n");
    return true;
  } else if (g.GON == 10) {
    move(GONDOLA, OVER_JUNGLE);
    if (!(riding == 0)) {
      g.HERE = OVER_JUNGLE;
    } else if (g.HERE == SW_SUPPORT) {
      g.P_IT_OBJECT = DGONDOLA;
    } else {
      return false;
    }
    await TURNS(W.EAST);
    if (riding == 0) {
      return true;
    }
    tell(S(g.TAB), "\"Flash photography is prohibited,\" growls ");
    await THE_PRINT(CONDUCTOR);
    tell(" as a passenger snaps a picture of the hazy landscape.\n");
    return true;
  } else if (g.GON == 11) {
    await REPLACE_GLOBAL$(SW_SUPPORT, DGONDOLA, NULL);
    await REPLACE_GLOBAL$(SW_UNDER, DGONDOLA, NULL);
    putProp(SW_UNDER, P.OVERHEAD, SUPPORT);
    await REPLACE_GLOBAL$(SE_SUPPORT, NULL, DGONDOLA);
    await REPLACE_GLOBAL$(SE_UNDER, NULL, DGONDOLA);
    putProp(SE_UNDER, P.OVERHEAD, DGONDOLA);
    if (g.HERE == SW_SUPPORT || g.HERE == SW_UNDER) {
      await GONDOLA_GONE(W.EAST);
      return true;
    } else if (g.HERE == SE_SUPPORT || g.HERE == SE_UNDER) {
      await VIEWGLIDE(SE_UNDER, W.WEST);
      return true;
    } else if (riding == 0) {
      return false;
    }
    await JUNGLE_GLIDE();
    tell(S(g.TAB), "\"To protect the Crocodile's Tear from thieves, Y'Syska concealed it somewhere in the jungle below,\" concludes ");
    await THE_PRINT(CONDUCTOR);
    tell(" lamely. \"There it remains to this very day, guarded by bloodworms and whatever traps the sorceress laid to confound the unwary.\"\n");
    tell(S(g.TAB), "Another ", D(SUPPORT), " looms to the east.\n");
    return true;
  } else if (g.GON == 12) {
    move(GONDOLA, SE_SUPPORT);
    if (g.HERE == SE_SUPPORT) {
      await GLIDING();
    } else if (riding == 0) {
      return false;
    } else {
      await GLIDE_PAST(SE_SUPPORT);
    }
    tell(S(g.TAB), "\"Thirsty?\" asks ");
    await THE_PRINT(CONDUCTOR);
    tell(". \"Stop by ");
    printS("the Skyway Adventure Emporium for a ");
    tell("tall, frosty Granola Float.\" He smacks his lips dispiritedly. \"Mmm, so good.\"\n");
    return true;
  } else if (g.GON == 13) {
    move(GONDOLA, OVER_JUNGLE);
    if (!(riding == 0)) {
      g.HERE = OVER_JUNGLE;
    } else if (!(g.HERE == SE_SUPPORT)) {
      return false;
    }
    await TURNS(W.NORTH);
    if (riding == 0) {
      return true;
    }
    tell(S(g.TAB), "\"Bloodworms are not the only inhabitants of the Miznia jungle,\" remarks ");
    await THE_PRINT(CONDUCTOR);
    tell(", pausing to stretch. \"Survivors have reported a wide variety of birds, reptiles and other unclassifiable dangers.\"\n");
    return true;
  } else if (g.GON == 14) {
    await REPLACE_GLOBAL$(SE_SUPPORT, DGONDOLA, NULL);
    await REPLACE_GLOBAL$(OVER_JUNGLE, SUPPORT, DOCK);
    await REPLACE_GLOBAL$(SE_UNDER, DGONDOLA, NULL);
    putProp(SW_UNDER, P.OVERHEAD, SUPPORT);
    await REPLACE_GLOBAL$(AT_DOCK, NULL, DGONDOLA);
    if (g.HERE == SE_SUPPORT || g.HERE == SE_UNDER) {
      await GONDOLA_GONE(W.NORTH);
      return true;
    } else if (g.HERE == AT_DOCK) {
      g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
      tell(S(g.TAB));
      await PRINTCA(GONDOLA);
      tell(S(g.SIS));
      printS("approaching from the south.\n");
      return true;
    } else if (riding == 0) {
      return false;
    }
    await JUNGLE_GLIDE();
    tell(S(g.TAB), "\"Be sure to visit ");
    printS("the Skyway Adventure Emporium for a ");
    tell("thrilling selection of one-of-a-kind gift ideas,\" urges ");
    await THE_PRINT(CONDUCTOR);
    tell(" as ");
    await THE_PRINT(DOCK);
    tell(" appears to the north.\n");
    return true;
  } else {
    return false;
  }
}

