async function I_MIRRORS() {
  let v_ = 0, hear = 0, l = 0, obj = 0, cnt = 0, time = 0, len = 0;
  hear = await GRUE_ROOM$();
  len = get(MIRROR_LIST, 0);
  cnt = 7;
  loop1: for (;;) {
    obj = get(MIRROR_LIST, len);
    l = loc(obj);
    if (!(l == 0)) {
      time = getProp(obj, P.SIZE);
      if (--time < 1) {
        --cnt;
        if (l == g.HERE) {
          ++v_;
          tell(S(g.TAB));
          await SAY_MIRROR_POPS(obj);
        } else if (!(hear == 0)) {
          ++v_;
          tell(S(g.TAB), "A distant ");
          (await ITALICIZE("pop"));
          tell(" echoes down the passageway.\n");
        }
        await DESTROY_MIRROR(obj);
      } else {
        putProp(obj, P.SIZE, time);
        if ((l == g.HERE) && (time == 2 || time == 10 || time == 18)) {
          ++v_;
          tell(S(g.TAB));
          g.P_IT_OBJECT = obj;
          await CTHE_PRINT(obj);
          if (time == 2) {
            tell(" is flexing dangerously now");
            printS(". It probably won't last much longer.\n");
          } else if (time == 10) {
            tell(" shimmers uncertainly for a moment.\n");
          } else {
            tell(" billows slightly, then stabilizes.\n");
          }
        }
      }
    } else {
      --cnt;
    }
    if (--len < 1) {
      break loop1;
    }
  }
  if (cnt == 0) {
    await DEQUEUE(I_MIRRORS.id);
  }
  return v_;
}

