async function FIND_CHAR$() {
  let len = 0, obj = 0;
  len = get(CHARLIST, 0);
  loop1: for (;;) {
    obj = get(CHARLIST, len);
    if (await VISIBLE$(obj)) {
      return obj;
    } else if (--len < 1) {
      break loop1;
    }
  }
  return await FIND_IN$(g.HERE, MONSTER);
}

