async function NEXT_BFLY_ROOM$(l) {
  let dir = 0, cnt = 0, tbl = 0, type = 0, x = 0, rm = 0;
  if (!(loc(l) == ROOMS)) {
    return false;
  }
  cnt = 1;
  dir = I_NORTH;
  loop1: for (;;) {
    tbl = getProp(l, getb(PDIR_LIST, dir));
    if (!(tbl == 0)) {
      x = get(tbl, XTYPE);
      type = x & 65280;
      if ((type == CONNECT || type == SCONNECT || type == X_EXIT) || ((type == DCONNECT) && hasFlag(get(tbl, XDATA), OPENED)) || ((type == FCONNECT) && (x & 127))) {
        rm = get(tbl, XROOM);
        if (rm == l || rm == ON_BRIDGE || rm == IN_FROON) {
        } else if (rm == APLANE || rm == IN_SPLENDOR || rm == loc(ARCH)) {
        } else if (!(await PLAIN_ROOM$(rm)) && !(hasFlag(BFLY, IDENTIFIED))) {
        } else if (hasFlag(rm, INDOORS) && !(hasFlag(l, INDOORS))) {
        } else if ((rm == g.HERE) && !(await WEARING_MAGIC$(CLOAK))) {
          cnt = 2;
          put(g.GOOD_DIRS, 2, dir);
          break loop1;
        } else {
          ++cnt;
          put(g.GOOD_DIRS, cnt, dir);
        }
      }
    }
    if (++dir > I_NW) {
      break loop1;
    }
  }
  if (cnt == 1) {
    return false;
  } else if (cnt == 2) {
    dir = get(g.GOOD_DIRS, 2);
  } else {
    put(g.GOOD_DIRS, 0, cnt);
    put(g.GOOD_DIRS, 1, 0);
    dir = await PICK_ONE(g.GOOD_DIRS);
  }
  rm = get(getProp(l, getb(PDIR_LIST, dir)), XROOM);
  if (l == g.HERE) {
    move(BFLY, rm);
    await BFLY_FLIES(dir);
    return true;
  } else if (rm == g.HERE) {
    await BFLY_ARRIVES(dir);
    return true;
  }
  return false;
}

