async function I_THRIFF_WIN() {
  if (!(await VISIBLE$(CLERIC))) {
    return false;
  } else if (hasFlag(CLERIC, SEEN)) {
    clearFlag(CLERIC, SEEN);
    return false;
  }
  ++g.CLERIC_SCRIPT;
  tell(S(g.TAB));
  if (g.CLERIC_SCRIPT == 1) {
    tell("\"Congratulations, honored ");
    await SAY_SORC();
    tell(",\" booms ");
    await THE_PRINT(CLERIC);
    tell(" over the crowd's cheers. \"Truly, thou art the Savior foretold in our eldest legends. Would that Orkan were here to witness this day.\"\n");
    return true;
  } else if (g.CLERIC_SCRIPT == 2) {
    tell("\"What reward wouldst thou claim of us?\" asks ");
    await THE_PRINT(CLERIC);
    tell(", carefully holding ");
    printS("the reliquary behind his back. \"");
    tell("Ask for anything, and it shall be yours!\"\n");
    return true;
  } else if (g.CLERIC_SCRIPT == 3) {
    tell("\"Anything we possess is yours for the asking,\" repeats ");
    await THE_PRINT(CLERIC);
    tell(S(g.PERIOD));
    return true;
  } else if (g.CLERIC_SCRIPT == 4) {
    await CTHE_PRINT(CLERIC);
    tell(" adjusts ");
    printS("the reliquary behind his back. \"");
    tell("Perchance we have nothing to tempt such a mighty ");
    await SAY_SORC();
    tell(",\" he remarks hopefully.\n");
    return true;
  }
  await EXIT_CLERIC();
  await CTHE_PRINT(CONGREG);
  tell(" is beginning to wander away", S(g.PTAB), "\"Your reticence betrays your humility, honored one,\" says the Cardinal, bowing his head. \"No doubt you have forsworn earthly gifts in lieu of some greater reward in the afterlife. In that case, farewell!\"\n  Clutching ");
  await THE_PRINT(RELIQUARY);
  tell(", ");
  await THE_PRINT(CLERIC);
  printS(" disappears into the ");
  tell("crowd. In moments, the place is deserted.\n");
  return true;
}

