async function NOLUCK$() {
  let cnt = 0, len = 0, obj = 0;
  len = get(LUCKY_OBJECTS, 0);
  for (;;) {
    obj = get(LUCKY_OBJECTS, len);
    if ((loc(obj) == PLAYER) && !(hasFlag(obj, NEUTRALIZED))) {
      cnt = getProp(obj, P.DNUM);
      if (--cnt < 1) {
        await VANISH(obj);
        tell(S(g.TAB));
        (await ITALICIZE("Poof"));
        tell("! ");
        await CTHE_PRINT(obj);
        tell(" is consumed in a silent flash of green.\n");
        return false;
      }
      putProp(obj, P.DNUM, cnt);
      tell(S(g.TAB), S(g.CYOUR));
      await DPRINT(obj);
      tell(" flickers green");
      if (cnt == 1) {
        tell(" again, less brightly than before");
      }
      printS(g.PERIOD);
      return false;
    }
    if (--len < 1) {
      return true;
    }
  }
}

