async function I_LAVA() {
  if (--g.LAVA_TIMER < 1) {
    if (g.HERE == FOREST_EDGE || g.HERE == ON_TRAIL || g.HERE == ON_PEAK || g.HERE == IN_CABIN) {
      await CASCADE();
      return true;
    }
    remove(PLUME);
    g.LAVA_TIMER = 0;
    await DEQUEUE(I_LAVA.id);
    move(MAGMA_GLOW, IN_THRIFF);
    g.MAGMA_TIMER = 4;
    await QUEUE(I_MAGMA.id);
    await EMPTY_ROOM(FOREST_EDGE);
    putProp(FOREST_EDGE, P.SDESC, 0);
    if (!(g.HERE == IN_THRIFF)) {
      return false;
    }
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
    tell(S(g.TAB), "A violent tremor wracks the earth and sends you sprawling. You bravely cover your eyes to await the tide of magma that will sweep you and Thriff into oblivion...\n\n\n\n\n\n\nThe silence gets the better of your curiosity.\n");
    return true;
  } else if (g.LAVA_TIMER == 1) {
    if (g.HERE == ON_TRAIL || g.HERE == ON_PEAK || g.HERE == IN_CABIN) {
      await CASCADE();
      return true;
    }
    remove(MAILBOX);
    putProp(ON_TRAIL, P.SOUTH, 0);
    putProp(ON_TRAIL, P.IN, 0);
    await REPLACE_GLOBAL$(ON_TRAIL, CABIN, NULL);
    if (loc(WIGHT) == ON_TRAIL) {
      remove(WIGHT);
      await DEQUEUE(I_WIGHT.id);
    }
    await EMPTY_ROOM(ON_TRAIL);
    if (!(g.HERE == FOREST_EDGE || g.HERE == IN_THRIFF)) {
      return false;
    }
    tell(S(g.TAB));
    await CTHE_PRINT(GROUND);
    tell(" trembles with seismic distress");
    if (g.HERE == IN_THRIFF) {
      tell(S(g.PERIOD));
      return true;
    }
    tell(" as a deadly torrent of lava sweeps down the western slope, only seconds away!\n");
    return true;
  } else if (g.LAVA_TIMER == 2) {
    if (g.HERE == ON_PEAK) {
      await CASCADE();
      return true;
    }
    await EMPTY_ROOM(ON_PEAK);
    if (!(g.HERE == ON_TRAIL || g.HERE == FOREST_EDGE || g.HERE == IN_THRIFF || g.HERE == IN_CABIN)) {
      return false;
    }
    tell(S(g.TAB), "Powerful shock waves rock the mountainside");
    if (g.HERE == IN_CABIN) {
      tell(", and the entire cabin shudders.\n");
      return true;
    } else if (g.HERE == IN_THRIFF || g.HERE == FOREST_EDGE) {
      tell(S(g.PERIOD));
      return true;
    }
    tell(" as a red-hot wall of liquid rock roars down the trail, only seconds behind you!\n");
    return true;
  } else {
    return false;
  }
}

async function CASCADE(str = 0) {
  if (arguments.length > 0) {
    tell("As you ", S(str), " the lava, a cascade of it ");
  } else {
    tell(S(g.TAB), "A cascade of lava ");
  }
  if (g.HERE == IN_CABIN) {
    tell("buries ");
    await THE_PRINT(CABIN);
  } else {
    if (!(g.HERE == ON_PEAK)) {
      tell("roars down the mountainside and ");
    }
    tell("knocks you off your feet, burying you");
  }
  tell(" instantly under tons of molten rock");
  if (await WEARING_MAGIC$(RING)) {
    tell("! Your magic ring miraculously shields you from the volcanic heat, but not from the inconvenience of having nothing to breathe");
  }
  await JIGS_UP();
  return true;
}

async function EMPTY_ROOM(rm) {
  let obj = 0, nxt = 0;
  if (obj = first(rm)) {
    loop1: for (;;) {
      nxt = next(obj);
      if (hasFlag(obj, TAKEABLE)) {
        remove(obj);
      }
      obj = nxt;
      if (obj == 0) {
        break loop1;
      }
    }
  }
  await REPLACE_GLOBAL$(rm, SNOW, LAVA);
  await REPLACE_GLOBAL$(rm, GLYPH, NULL);
  return false;
}

