async function I_XTREES() {
  let x = 0, c_ = 0;
  let $1, $2;
  if (await GLOBAL_IN$(FOREST_EDGE, GLYPH)) {
    if (!(g.HERE == FOREST_EDGE)) {
      return false;
    } else if (hasFlag(XTREES, SEEN)) {
      clearFlag(XTREES, SEEN);
      return false;
    } else if (prob(50)) {
      return false;
    }
    await SAY_XTREES();
    if (prob(50)) {
      x = await PICK_NEXT(CAROLS);
      $1 = await PICK_NEXT(HOW_SINGS);
      tell(S($1));
      tell(S(x), S(g.PERQ));
      return true;
    }
    $2 = await PICK_NEXT(XTREE_DOINGS);
    tell(S($2));
    tell(S(g.PERIOD));
    return true;
  } else if (!(g.MAGMA_TIMER == 0)) {
    return false;
  } else if ((g.HERE == FOREST_EDGE || g.HERE == IN_THRIFF) && hasFlag(BFLY, MUNGED) && hasFlag(BFLY, LIVING) && ((loc(BFLY) == PLAYER) || (loc(BFLY) == g.HERE))) {
    await SAY_XTREES();
    tell(" shuffle nervously at the edge of the ");
    if (await GLOBAL_IN$(SNOW, g.HERE)) {
      tell(wordText(W.CLEARING));
    } else {
      tell(wordText(W.LAVA));
    }
    tell(". They");
    printS(" seem unwilling to approach you.\n");
    return true;
  } else if (!(hasFlag(FOREST_EDGE, MUNGED))) {
    if (g.HERE == FOREST_EDGE) {
      await XTREES_EAT_YOU();
      return true;
    }
    setFlag(FOREST_EDGE, MUNGED);
    await NEW_EXIT$(ON_TRAIL, P.EAST, FCONNECT, XTREES_BLOCK.id);
    await NEW_EXIT$(ON_TRAIL, P.DOWN, FCONNECT, XTREES_BLOCK.id);
    await NEW_EXIT$(IN_THRIFF, P.SOUTH, FCONNECT, XTREES_BLOCK.id);
    await NEW_EXIT$(IN_THRIFF, P.UP, FCONNECT, XTREES_BLOCK.id);
    await REPLACE_GLOBAL$(ON_TRAIL, NULL, XTREES);
    await REPLACE_GLOBAL$(IN_THRIFF, NULL, XTREES);
    if (g.HERE == IN_THRIFF || g.HERE == IN_CHAPEL || g.HERE == ON_TRAIL) {
      await XTREES_APPEAR();
      return true;
    }
    return false;
  } else if (!(hasFlag(IN_THRIFF, MUNGED))) {
    if (g.HERE == IN_THRIFF || g.HERE == IN_CHAPEL) {
      await XTREES_EAT_YOU();
      return true;
    }
    setFlag(IN_THRIFF, MUNGED);
    await NEW_EXIT$(IN_PASTURE, P.SE, FCONNECT, XTREES_BLOCK.id);
    await NEW_EXIT$(AT_FALLS, P.SW, FCONNECT, XTREES_BLOCK.id);
    await REPLACE_GLOBAL$(IN_PASTURE, NULL, XTREES);
    await REPLACE_GLOBAL$(AT_FALLS, NULL, XTREES);
    if (g.HERE == IN_PASTURE || g.HERE == AT_FALLS) {
      await XTREES_APPEAR();
      return true;
    }
    return false;
  } else {
    return false;
  }
}

