async function I_HEAL() {
  let stat = 0, max = 0, old = 0;
  tell(S(g.TAB), "Your body is flooded with an indescribable sense of well-being.\n");
  loop1: for (;;) {
    old = get(g.STATS, stat);
    max = get(g.MAXSTATS, stat);
    if (s16(max) > s16(old)) {
      await UPDATE_STAT(max - old, stat);
    } else if (max == old) {
      await UPDATE_STAT(5, stat, true);
    }
    if (++stat > STRENGTH) {
      break loop1;
    }
  }
  await BMODE_OFF();
  return true;
}

async function I_MIGHT() {
  let max = 0, old = 0;
  tell(S(g.TAB), "You feel a surge of tension in your arms and shoulders.\n");
  old = get(g.STATS, STRENGTH);
  max = get(g.MAXSTATS, STRENGTH);
  if (s16(max) > s16(old)) {
    await UPDATE_STAT(max - old, STRENGTH);
  } else if (max == old) {
    await UPDATE_STAT(16, STRENGTH, true);
  }
  return true;
}

async function I_FORGET() {
  let any = 0, obj = 0, len = 0;
  clearFlag(GLYPH, SEEN);
  if (obj = first(ROOMS)) {
    loop1: for (;;) {
      clearFlag(obj, VIEWED);
      if (!(obj = next(obj))) {
        break loop1;
      }
    }
  }
  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
  g.P_WALK_DIR = false;
  g.OLD_HERE = false;
  len = get(MAGIC_ITEMS, 0);
  loop2: for (;;) {
    obj = get(MAGIC_ITEMS, len);
    if (hasFlag(obj, IDENTIFIED)) {
      ++any;
      clearFlag(obj, IDENTIFIED);
      clearFlag(obj, PROPER);
    }
    if (--len < 1) {
      break loop2;
    }
  }
  tell(S(g.TAB), "An uneasy feeling creeps into your soul.\n");
  return true;
}

