async function DO_GLANCE(who, obj) {
  setFlag(who, SEEN);
  await CTHE_PRINT(who);
  if (await VISIBLE$(obj)) {
    tell(S(g.GLANCES_AT));
    await THE_PRINT(obj);
  } else {
    printS(" gives you a puzzled frown");
  }
  printS(", but says nothing.\n");
  return true;
}

async function COOK_F(context = false) {
  let x = 0;
  if (context == M_OBJDESC) {
    tell("A skinny old cook is bustling around the kitchen.");
    return true;
  } else if (context == M_WINNER) {
    if (isVerb(V.TELL_ABOUT, V.SSHOW) && (g.PRSO == ME)) {
      await ASK_COOK_ABOUT(g.PRSI);
      return M_FATAL;
    } else if (isVerb(V.EXAMINE, V.WHAT, V.WHO, V.WHERE) || (isVerb(V.SHOW) && (g.PRSI == ME))) {
      await ASK_COOK_ABOUT(g.PRSO);
      return M_FATAL;
    } else if (isVerb(V.GIVE, V.GET_FOR) && (g.PRSI == ME)) {
      await ASK_COOK_FOR(g.PRSO);
      return M_FATAL;
    } else if (isVerb(V.SGIVE, V.SGET_FOR) && (g.PRSO == ME)) {
      await ASK_COOK_FOR(g.PRSI);
      return M_FATAL;
    }
    await CTHE_PRINT(COOK);
    tell(" scowls. \"Don't bother me now, I'm busy!\"\n");
    return M_FATAL;
  } else if (!(context == 0)) {
    return false;
  } else if (!(g.NOW_PRSI$ == 0)) {
    if (hasFlag(g.PRSI, NODESC)) {
      await CANT_FROM_HERE();
      return true;
    } else if (isVerb(V.BUY_FROM)) {
      await ASK_COOK_FOR(g.PRSO);
      return true;
    } else if (isVerb(V.GIVE, V.GET_FOR)) {
      await GIVE_TO_COOK(g.PRSO);
      return true;
    } else if (isVerb(V.SHOW)) {
      await SHOW_TO_COOK(g.PRSO);
      return true;
    }
    return false;
  } else if (hasFlag(g.PRSO, NODESC)) {
    if (x = inTable(g.PRSA, TALKVERBS, NTVERBS)) {
      await PCLEAR();
      tell("He");
      printS(" doesn't seem to hear you.\n");
      return M_FATAL;
    }
    await CANT_FROM_HERE();
    return true;
  } else if (isVerb(V.ASK_FOR)) {
    await ASK_COOK_FOR(g.PRSI);
    return true;
  } else if (isVerb(V.ASK_ABOUT)) {
    await ASK_COOK_ABOUT(g.PRSI);
    return true;
  } else if (isVerb(V.TELL_ABOUT)) {
    await SHOW_TO_COOK(g.PRSI);
    return true;
  } else {
    return false;
  }
}

async function ASK_COOK_ABOUT(obj) {
  let tbl = 0, len = 0, x = 0;
  await SEE_CHARACTER(COOK);
  setFlag(COOK, SEEN);
  if (obj == BOTTLE) {
    if (hasFlag(ONION, SEEN)) {
      tell("\"Got it put away, nice and safe. Thanks again.\"\n");
      return true;
    } else if (hasFlag(BOTTLE, IDENTIFIED)) {
      tell("\"This here onion's yours if you ");
      if (await VISIBLE$(obj)) {
        tell("hand it over.\"\n");
        return true;
      }
      tell("get it for me.\"\n");
      return true;
    } else if (hasFlag(ONION, TOUCHED)) {
      clearFlag(COOK, SEEN);
      tell("\"Ahem.\"\n");
      await I_ONION_OFFER();
      return true;
    }
    await DO_GLANCE(COOK, CELLAR_DOOR);
    return true;
  } else if (obj == COOK) {
    tell("\"Grote Clutchcake's the name.\"\n");
    return true;
  } else if (obj == CELLAR || obj == CELLAR_DOOR) {
    tell("\"Used t'be a wine cellar. Can't go down no more; too dangerous.\"\n");
    return true;
  } else if (!(await VISIBLE$(obj))) {
    await PERPLEXED(COOK);
    tell("Don't know");
    await WHO_WHAT(obj);
    tell("you're talkin' 'bout.\"\n");
    return true;
  } else if (obj == ONION) {
    await COOK_MENTIONS_ONION();
    return true;
  }
  await CTHE_PRINT(COOK);
  tell(" shrugs impatiently. \"Can't say anythin' 'bout ");
  await PRONOUN(obj);
  tell(" you wouldn't know already.\"\n");
  return true;
}

async function ASK_COOK_FOR(obj) {
  let x = 0, l = 0;
  await SEE_CHARACTER(COOK);
  l = loc(obj);
  setFlag(COOK, SEEN);
  if (!(await VISIBLE$(obj))) {
  } else if (obj == ONION) {
    if (hasFlag(obj, SEEN)) {
      tell("\"It's yours. Roll it outa here.\"\n");
      return true;
    } else if (hasFlag(BOTTLE, IDENTIFIED)) {
      tell("\"Yours for ");
      await THE_PRINT(BOTTLE);
      if (!(hasFlag(BOTTLE, TOUCHED))) {
        tell(" downstairs");
      }
      tell(S(g.PERQ));
      return true;
    }
    await COOK_MENTIONS_ONION();
    return true;
  }
  await AINT_GOT(COOK, obj);
  return true;
}

async function COOK_MENTIONS_ONION() {
  if (!(hasFlag(ONION, TOUCHED))) {
    setFlag(ONION, TOUCHED);
    setFlag(COOK, SEEN);
    await DEQUEUE(I_COOK.id);
    await QUEUE(I_ONION_OFFER.id);
    await CTHE_PRINT(COOK);
    tell(" gives ");
    await THE_PRINT(ONION);
    tell(" an affectionate kick. ");
  }
  tell("\"Nice, eh? Won second place at the Borphee County Fair.\"\n");
  return true;
}

async function STOP_ONION_OFFER() {
  setFlag(BOTTLE, IDENTIFIED);
  await DEQUEUE(I_ONION_OFFER.id);
  if (!(await QUEUED$(I_COOK.id))) {
    await QUEUE(I_COOK.id);
  }
  setFlag(COOK, SEEN);
  return false;
}

async function GIVE_TO_COOK(obj) {
  await SEE_CHARACTER(COOK);
  setFlag(COOK, SEEN);
  if (await GIVING_LOOT$(obj, COOK)) {
    return true;
  }
  await CTHE_PRINT(COOK);
  if (obj == BOTTLE) {
    await VANISH(obj);
    setFlag(ONION, SEEN);
    tell("'s eyes grow large as he takes ");
    await THE_PRINT(obj);
    tell(". \"Been after this thing for years,\" he cries, turning it over and over in his hands before stowing it quickly out of sight. ");
    if (!(hasFlag(BOTTLE, IDENTIFIED))) {
      tell("\"I owe you a big favor, ");
      await BOY_GIRL();
      tell(". A ");
      (await ITALICIZE("very"));
      tell(" big favor. Big as this here onion.\" ");
    }
    await STOP_ONION_OFFER();
    tell("Your eyes follow his to ");
    await THE_PRINT(ONION);
    tell(" near the exit. \"All yours,\" he says, patting it affectionately.\n");
    return true;
  }
  tell(" refuses ");
  await THE_PRINT(obj);
  tell(" with a shake of his head. \"No, thanks.\"\n");
  return true;
}

async function COOK_SEES_BOTTLE() {
  await STOP_ONION_OFFER();
  setFlag(BOTTLE, MUNGED);
  tell("\"The bottle!\" gasps ");
  await THE_PRINT(COOK);
  tell(" when he sees it");
  if (loc(BOTTLE) == PLAYER) {
    tell(" in your hands");
  }
  printS(". \"You got it!\"\n");
  return true;
}

async function SHOW_TO_COOK(obj) {
  await SEE_CHARACTER(COOK);
  setFlag(COOK, SEEN);
  if (obj == BOTTLE) {
    if (!(hasFlag(obj, IDENTIFIED))) {
      await COOK_SEES_BOTTLE();
      return true;
    }
    await STOP_ONION_OFFER();
    tell("\"That's the one!\" he gasps");
    printS(". \"You got it!\"\n");
    return true;
  }
  tell("\"How interesting,\" yawns ");
  await THE_PRINT(COOK);
  if (await VISIBLE$(obj)) {
    tell(", glancing at ");
    await THE_PRINT(obj);
  }
  printS(g.PERIOD);
  return true;
}

async function BANDITS_F(context = false) {
  let x = 0;
  if (!(context == 0)) {
    return false;
  } else if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.POINT_AT, V.TOUCH_TO, V.FIRE_AT)) {
      tell("There are too many of them here.\n");
      return true;
    } else if (isVerb(V.THROW, V.THROW_OVER)) {
      await SUICIDE();
      return true;
    } else if (isVerb(V.GIVE, V.SHOW, V.GET_FOR, V.FEED)) {
      await HEEDLESS();
      return true;
    }
    return false;
  } else if (x = inTable(g.PRSA, TALKVERBS, NTVERBS)) {
    await HEEDLESS();
    return M_FATAL;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
    (await NOSEY("starin' at"));
    return true;
  } else if (isVerb(V.LISTEN)) {
    (await NOSEY("listenin' to"));
    return true;
  } else if (x = inTable(g.PRSA, HURTVERBS, NHVERBS)) {
    await SUICIDE();
    return true;
  } else {
    return false;
  }
}

async function NOSEY(str) {
  setFlag(g.PRSO, SEEN);
  tell("\"Who're you ", S(str), "?\" demands a very large bandit. You wisely decide to turn your attention elsewhere.\n");
  return true;
}

async function SUICIDE() {
  tell("Suicide. Monsters are one thing; an armed ", D(BANDITS), " is quite another.\n");
  return true;
}

async function HEEDLESS() {
  await PCLEAR();
  tell("The bandits glare at your interruption. \"Scram.\"\n");
  return true;
}

async function OWOMAN_F(context = false) {
  let x = 0;
  let $1;
  if (context == M_OBJDESC) {
    await PRINTCA(OWOMAN);
    tell(S(g.SIS));
    $1 = await PICK_NEXT(OWOMAN_EYES);
    tell(S($1));
    tell(C(PER));
    return true;
  } else if (context == M_WINNER) {
    if (isVerb(V.TELL_ABOUT, V.SSHOW) && (g.PRSO == ME)) {
      await ASK_OWOMAN_ABOUT(g.PRSI);
      return M_FATAL;
    } else if (isVerb(V.EXAMINE, V.REQUEST, V.WHAT, V.WHO, V.WHERE) || (isVerb(V.SHOW) && (g.PRSI == ME))) {
      await ASK_OWOMAN_ABOUT(g.PRSO);
      return M_FATAL;
    } else if (isVerb(V.GIVE, V.GET_FOR) && (g.PRSI == ME)) {
      await ASK_OWOMAN_FOR(g.PRSO);
      return M_FATAL;
    } else if (isVerb(V.SGIVE, V.SGET_FOR) && (g.PRSO == ME)) {
      await ASK_OWOMAN_FOR(g.PRSI);
      return M_FATAL;
    } else if (isVerb(V.SELL_TO) && (g.PRSI == ME)) {
      await BUY_X_WITH_Y(g.PRSO, MONEY);
      return true;
    } else if (isVerb(V.SSELL_TO) && (g.PRSO == ME)) {
      await BUY_X_WITH_Y(g.PRSI, MONEY);
      return true;
    } else if (isVerb(V.HELLO, V.GOODBYE) && (g.PRSO == ROOMS || g.PRSO == OWOMAN)) {
      await GREET_OWOMAN();
      return M_FATAL;
    }
    tell("\"I'm not used to being ordered about,\" observes ");
    await THE_PRINT(OWOMAN);
    tell(" coldly.\n");
    return M_FATAL;
  } else if (!(context == 0)) {
    return false;
  } else if (await NOUN_USED$(W.Y_GAEL)) {
    if (!(hasFlag(OWOMAN, MUNGED))) {
      setFlag(OWOMAN, MUNGED);
      tell(S(g.CTHELADY));
      printS(" raises an eyebrow");
      tell(" as you speak her Name.\n");
      return M_FATAL;
    }
  }
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.THROW, V.THROW_OVER)) {
      await HARMLESS(g.PRSI);
      return true;
    } else if (isVerb(V.GIVE, V.GET_FOR)) {
      await GIVE_TO_OWOMAN(g.PRSO);
      return true;
    } else if (isVerb(V.SHOW)) {
      await ASK_OWOMAN_ABOUT(g.PRSO);
      return true;
    } else if (isVerb(V.SELL_TO)) {
      await TRADE_FOR_LOOT(g.PRSO);
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE)) {
    x = getProp(g.PRSO, P.LAST_LOC);
    if (await VISIBLE$(x)) {
    } else if (!(x == 0)) {
      tell("That's odd. She looks just like the woman you met in ");
      await THE_PRINT(x);
      tell(S(g.PERIOD));
      return true;
    }
    await CTHE_PRINT();
    tell(" regards you with equal interest.\n");
    return true;
  } else if (isVerb(V.ASK_FOR)) {
    await ASK_OWOMAN_FOR(g.PRSI);
    return true;
  } else if (isVerb(V.ASK_ABOUT)) {
    await ASK_OWOMAN_ABOUT(g.PRSI);
    return true;
  } else if (isVerb(V.TELL_ABOUT)) {
    if (loc(g.PRSI) == PLAYER) {
      await GIVE_TO_OWOMAN(g.PRSI);
      return true;
    }
    await ASK_OWOMAN_ABOUT(g.PRSI);
    return true;
  } else if (isVerb(V.HELLO, V.WAVE_AT, V.GOODBYE)) {
    await GREET_OWOMAN();
    return true;
  } else if (x = inTable(g.PRSA, HURTVERBS, NHVERBS)) {
    await HARMLESS();
    return true;
  } else {
    return false;
  }
}

async function GREET_OWOMAN() {
  setFlag(OWOMAN, SEEN);
  tell(S(g.CTHELADY), " nods graciously.\n");
  return true;
}

async function ASK_OWOMAN_ABOUT(obj) {
  let tbl = 0, len = 0, x = 0;
  await SEE_CHARACTER(OWOMAN);
  if (obj == MONEY || obj == INTNUM) {
    tell("\"My favorite subject.\"\n");
    return true;
  } else if (await WHAT_TALK$(OWOMAN, obj)) {
    return true;
  } else if (obj == KEY1 || obj == KEY2 || obj == KEY3) {
    tell("\"How tawdry.\"\n");
    return true;
  } else if (obj == PARASOL) {
    tell(S(g.CTHELADY));
    printS(" raises an eyebrow");
    printS(", but says nothing.\n");
    return true;
  } else if ((obj == BOUTIQUE || obj == WEAPON_SHOP || obj == MSHOPPE) || (obj == BCASE || obj == MCASE || obj == WCASE)) {
    tell("\"Best selection in the Southlands.\"\n");
    return true;
  } else if (obj == CURTAIN || obj == OWOMAN || obj == ME) {
    tell(S(g.CTHELADY), " smiles wryly");
    printS(", but says nothing.\n");
    return true;
  } else if ((g.HERE == IN_BOUTIQUE) && (await BOUTIQUE_KNOWLEDGE$(obj))) {
    return true;
  } else if ((g.HERE == IN_WEAPON) && (await WEAPON_KNOWLEDGE$(obj))) {
    return true;
  } else if ((g.HERE == IN_MAGICK) && (await MAGICK_KNOWLEDGE$(obj))) {
    return true;
  }
  len = get(OWOMAN_TABLE, 0);
  loop1: for (;;) {
    tbl = get(OWOMAN_TABLE, len);
    x = get(tbl, 0);
    if (x == obj) {
      tell("\"", S(get(tbl, 1)));
      await REVEAL_VALUE(x, getProp(g.HERE, P.THIS_CASE));
      return true;
    } else if (--len < 1) {
      break loop1;
    }
  }
  if (!(g.HERE == IN_MAGICK) && (x = get(MAGIC_ITEMS, 0)) && (x = inTable(obj, MAGIC_ITEMS + 2, x))) {
    (await ASK_IN(obj, "Magick Shoppe in Gurth City"));
    return true;
  }
  if (!(g.HERE == IN_WEAPON) && (x = get(WEAPON_ITEMS, 0)) && (x = inTable(obj, WEAPON_ITEMS + 2, x))) {
    (await ASK_IN(obj, "weapon shop in Accardi"));
    return true;
  }
  if (!(g.HERE == IN_BOUTIQUE) && (x = get(ARMOR_ITEMS, 0)) && (x = inTable(obj, ARMOR_ITEMS + 2, x))) {
    (await ASK_IN(obj, "boutique in Mizniaport"));
    return true;
  }
  tell("\"I'm afraid I can't tell you very much about ");
  await PRONOUN(obj);
  tell(",\" apologizes ");
  await THE_PRINT(OWOMAN);
  tell(S(g.PERIOD));
  return true;
}

async function ASK_IN(obj, str) {
  tell(S(g.CTHELADY), S(g.GLANCES_AT));
  await THE_PRINT(obj);
  tell(". \"Can't tell you much about this here,\" she mutters. \"Bet the ", S(str), " would know something, though.\"\n");
  return true;
}

async function BOUTIQUE_KNOWLEDGE$(obj) {
  if (obj == PACK) {
    tell("\"Perfect for those long adventures");
  } else if (obj == CLOAK) {
    tell("\"A fine example of elvish tailoring. 'Tis said a potent virtue is woven into the cloth");
  } else if (obj == TUNIC) {
    tell("\"Oh, that. Last week's fashion, I'm afraid");
  } else if (obj == SCALE) {
    tell("\"Good basic protection. Not too bulky, not too expensive");
  } else if (obj == CHAIN) {
    tell("\"An effective design, if not particularly comfortable");
  } else if (obj == PLATE) {
    tell("\"The last word in protection,\" states ");
    await THE_PRINT(OWOMAN);
    tell(" flatly. \"That stuff'll turn aside anything short of a grue's fangs");
  } else if (obj == HELM || obj == SCABBARD) {
    await SECRET_VIRTUE(obj);
    return true;
  } else {
    return false;
  }
  await REVEAL_VALUE(obj, BCASE);
  return true;
}

async function WEAPON_KNOWLEDGE$(obj) {
  if (obj == ARROW) {
    tell("\"A primitive design; high drag coefficient");
  } else if (obj == DAGGER) {
    tell("\"Suitable for cleaning fish, I suppose");
  } else if (obj == SWORD) {
    tell("\"Of ancient elvish workmanship, if I'm not mistaken");
  } else if (obj == SHILL) {
    tell("\"Many an orc's skull bears the mark of this ", D(SHILL));
  } else if (obj == AXE) {
    tell("\"A real skull-cleaver, that one");
  } else if (obj == PHASE || obj == SCABBARD || obj == HELM) {
    await SECRET_VIRTUE(obj);
    return true;
  } else {
    return false;
  }
  await REVEAL_VALUE(obj, WCASE);
  return true;
}

async function MAGICK_KNOWLEDGE$(obj) {
  let val = 0, act_ = 0, fx = 0;
  g.IDING = obj;
  act_ = getProp(obj, P.ACTION);
  fx = getProp(obj, P.EFFECT);
  if (act_ == SLEEP_WAND_F.id) {
    await DO_ID();
    tell("Aim this at a creature and watch it stagger");
  } else if (act_ == BLAST_WAND_F.id) {
    await DO_ID();
    tell("Instant death, with few exceptions");
  } else if (act_ == TELE_WAND_F.id) {
    await DO_ID();
    tell("Teleports trouble out of your way");
  } else if (act_ == IO_WAND_F.id) {
    await DO_ID();
    tell("Makes things turn inside-out");
  } else if (act_ == LEV_WAND_F.id) {
    await DO_ID();
    tell("Floats 'most anything that isn't nailed down");
  } else if (act_ == DISPEL_WAND_F.id) {
    tell(S(g.CTHELADY), " scowls. ");
    await DO_ID();
    tell("Neutralizes the effects of Magick");
  } else if (act_ == HEALING_POTION_F.id) {
    await DO_ID();
    tell("Just the thing in the heat of battle");
  } else if (act_ == FORGET_POTION_F.id) {
    await DO_ID();
    tell("Hmm,\" mutters ");
    await THE_PRINT(OWOMAN);
    tell(". \"Tried one of those once; can't recall what it does. Oh, well");
  } else if (act_ == DEATH_POTION_F.id) {
    await DO_ID();
    tell("Don't understand why they mix these things");
  } else if ((act_ == MIGHT_POTION_F.id) || (obj == ROOT)) {
    await DO_ID();
    tell("That'll put hair on your chest");
    if (hasFlag(PLAYER, FEMALE)) {
      tell(".\" ", S(g.CTHELADY), " blushes. \"Well, you know what I mean");
    }
  } else if (act_ == IQ_POTION_F.id) {
    await DO_ID();
    tell("Four years faster than GUE Tech, and a lot cheaper");
  } else if (fx == DO_PARTAY.id) {
    await DO_ID();
    tell("Big fun at parties");
  } else if (fx == DO_FILFRE.id) {
    await DO_ID();
    tell("Essential reading");
  } else if (fx == DO_GOTO.id) {
    await DO_ID();
    tell("Just the thing for emergencies");
  } else if (fx == DO_BLESS_ARMOR.id) {
    await DO_ID();
    tell("Bestows a rich blessing upon your armor");
  } else if (fx == DO_BLESS_WEAPON.id) {
    await DO_ID();
    tell("Adds a touch of enchantment to any weapon");
  } else if (fx == DO_RENEWAL.id) {
    await DO_ID();
    tell("How refreshing");
  } else if (fx == DO_GATE.id) {
    await DO_ID();
    tell("Not as robust as Dimension Door, but serviceable");
  } else if (obj == CAKE) {
    tell(S(g.CTHELADY), " grimaces. \"Bleah. My aunt used to make those. Good for your brain, but not much else");
  } else if (obj == CLOAK) {
    await DO_ID();
    tell("Elvish, if the weave speaks true");
  } else if (obj == RING) {
    tell(S(g.CTHELADY), " smirks. ");
    await DO_ID();
    tell("Same as the Coal-Walkers of Egreth use");
  } else if (obj == HELM) {
    await DO_ID();
    setFlag(obj, PROPER);
    tell("A potent relic of the past 'Tis said the wearer commands the wisdom of kings, and can see the unseeable.\" She shudders visibly. \"Some things are better left unseen");
  } else if (obj == GOBLET) {
    if (g.GOBLET_WORD == 0) {
      await SETUP_GOBLET();
    }
    tell(S(g.CTHELADY), " turns pale, and lowers her voice to a barely audible whisper. \"The ");
    await PRINT_TABLE(getProp(obj, P.NAME_TABLE));
    tell(",\" she hisses");
    if (!(hasFlag(obj, NEUTRALIZED))) {
      tell(", and thunder rumbles outside");
    }
    tell(". \"Beware! for its Name incurs the wrath of the Implementors");
  } else if (obj == UHEMI || obj == LHEMI) {
    tell("\"Hmm,\" mutters ");
    await THE_PRINT(OWOMAN);
    tell(". \"Some great potential lies within");
  } else if (obj == STONE) {
    if (!(hasFlag(STONE, NAMED))) {
      await SETUP_STONE();
    }
    tell("\"Ah! The ");
    await PRINT_TABLE(getProp(obj, P.NAME_TABLE));
    tell("! Visions of things yet to be lie within its depths, for those with enough wit to see them");
  } else if (obj == RFOOT || obj == CLOVER || obj == SHOE) {
    tell("\"A charm to ward off ill luck");
  } else if (obj == SCABBARD) {
    setFlag(obj, IDENTIFIED);
    tell(S(g.CTHELADY), "'s voice lowers to a respectful whisper. \"Behold ");
    await THE_PRINT(obj);
    tell(", Blade of Entharion,\" she says. \"Though the Blade is long lost, the scabbard retains much virtue; for ");
    if (hasFlag(PLAYER, FEMALE)) {
      tell("s");
    }
    tell("he who wears it is blessed with wondrous powers of recuperation");
  } else if (obj == VIAL) {
    tell("\"Holy water,\" explains ");
    await THE_PRINT(OWOMAN);
    tell(" after a brief glance. \"Standard issue against vampires, wraiths, anything dead that moves");
  } else if (obj == GLASS) {
    tell("\"A relic of ancient Pheebor,\" explains ");
    await THE_PRINT(OWOMAN);
    tell(". \"Its purpose is lost in Time. Perhaps it is part of some greater Magick");
  } else if (obj == ROSE) {
    tell("\"A compass rose! Just the thing for an ill wind");
  } else if (obj == GURDY) {
    tell("\"A versatile instrument. Dangerous in the wrong hands");
  } else if (obj == WHISTLE) {
    await DO_ID();
    tell("Wrought by a platypus, like most nowadays");
  } else if (obj == PHASE) {
    tell("\"Little more than a curiosity, at least on this Plane of existence");
  } else if (obj == CHEST) {
    tell(S(g.CTHELADY), " studies ");
    await THE_PRINT(obj);
    tell(" closely. \"Careful with this,\" she warns. \"The plaque on the lid is well worth reading");
  } else if (obj == AMULET) {
    tell("\"A useful bit of Magick, this. ");
    if (g.AMULET_STARS == 0) {
      tell("Too bad it's all used up");
    } else {
      tell("Still got some life in it, too");
    }
  } else if (obj == SPENSE || obj == SPENSE2) {
    tell("\"Spenseweed, of course. A wholesome treat");
  } else if (obj == BURIN) {
    tell("\"Diamond-tipped, I see. Top of the line");
  } else if (obj == JAR || obj == CIRCLET) {
    tell("\"A vain bit of Magick; yet not without its uses");
  } else {
    return false;
  }
  if (hasFlag(obj, NEUTRALIZED)) {
    printS(". Unfortunately, ");
    tell("its Magick");
    printS(" appears to have been neutralized");
  }
  await REVEAL_VALUE(obj, MCASE);
  return true;
}

