async function ASK_MAYOR_ABOUT(obj) {
  let tbl = 0, len = 0, x = 0;
  await SEE_CHARACTER(MAYOR);
  if (!(await VISIBLE$(obj))) {
    await PERPLEXED(MAYOR);
    tell("I'm uncertain as to");
    await WHO_WHAT(obj);
    tell("you are referring.\"\n");
    return true;
  }
  len = get(MAYOR_TABLE, 0);
  loop1: for (;;) {
    tbl = get(MAYOR_TABLE, len);
    x = get(tbl, 0);
    if (eq(get(tbl, 0), obj)) {
      printC(34);
      tell(S(get(tbl, 1)), S(g.PERQ));
      return true;
    } else if (--len < 1) {
      break loop1;
    }
  }
  await CTHE_PRINT(MAYOR);
  tell(" looks at ");
  await THE_PRINT(GROUND);
  tell(" sheepishly");
  await ALAS();
  tell("I possess but little knowledge of ");
  await PRONOUN(obj);
  tell(S(g.PERQ));
  return true;
}

