async function ASK_CLERIC_ABOUT(obj) {
  let tbl = 0, len = 0, x = 0;
  if (await WHAT_TALK$(CLERIC, obj)) {
    return true;
  }
  len = get(CLERIC_TABLE, 0);
  loop1: for (;;) {
    tbl = get(CLERIC_TABLE, len);
    x = get(tbl, 0);
    if (eq(get(tbl, 0), obj)) {
      printC(34);
      tell(S(get(tbl, 1)), S(g.PERQ));
      return true;
    } else if (--len < 1) {
      break loop1;
    }
  }
  await CTHE_PRINT(CLERIC);
  tell(" shrugs. \"I claim little knowledge of ");
  await PRONOUN(obj);
  tell(S(g.PERQ));
  return true;
}

