async function FOREST_EDGE_F(context = false) {
  let bhere = 0;
  if (context == M_LOOK) {
    if (await GLOBAL_IN$(FOREST_EDGE, LAVA)) {
      tell("An avalanche of lava has consumed the upward trail, ending here in a ");
      if (!(g.MAGMA_TIMER == 0)) {
        await GLOW_COLOR();
        tell(wordText(W.POOL));
      } else {
        tell("dark, steaming crust");
      }
      tell(". Many of the surrounding ");
      await SAY_TREES();
      tell(" are damaged; the survivors linger near the blackened edge of the clearing.\n");
    } else {
      tell("The upward trail bends sharply west here, winding out of sight between the ");
      await SAY_TREES();
      tell(S(g.PERIOD));
    }
    await MENTION_GLYPH$();
    return true;
  } else if (context == M_ENTERING) {
    if (hasFlag(XTREES, SEEN)) {
      g.P_THEM_OBJECT = XTREES;
    }
    if (await GLOBAL_IN$(FOREST_EDGE, GLYPH)) {
      g.P_IT_OBJECT = GLYPH;
    }
    return false;
  } else if (context == M_EXIT) {
    if (!(hasFlag(XTREES, TOUCHED))) {
      await SEE_XTREES();
      return M_FATAL;
    }
    if (g.P_WALK_DIR == P.UP) {
      g.P_WALK_DIR = P.WEST;
    }
    if (g.P_WALK_DIR == P.DOWN) {
      g.P_WALK_DIR = P.NORTH;
    }
    if (g.P_WALK_DIR == P.NORTH) {
      if (!(g.LAVA_TIMER == 0)) {
        tell("Volcanic heat singes your eyebrows as you race down the mountainside.\n");
        return true;
      }
      tell("You stride down into the village");
      await BYE_BFLY();
      return true;
    } else if (!(g.P_WALK_DIR == P.WEST)) {
      return false;
    } else if (!(g.LAVA_TIMER == 0)) {
      (await CASCADE("approach"));
      return M_FATAL;
    }
    await CTHE_PRINT(XTREES);
    tell(" shuffle ");
    if (!(g.MAGMA_TIMER == 0)) {
      tell("impotently at the lava's edge");
    } else if ((loc(BFLY) == PLAYER) && hasFlag(BFLY, MUNGED) && hasFlag(BFLY, LIVING)) {
      tell("nervously out of your way");
    } else {
      setFlag(XTREES, SEEN);
      tell("across the upward trail, blocking it completely.\n");
      return M_FATAL;
    }
    tell(" as you ascend the slope");
    await BYE_BFLY();
    return true;
  } else {
    return false;
  }
}

