async function AT_GATE_F(context = false) {
  if (context == M_LOOK) {
    tell("Before you stands the headquarters of The Accardi Chapter of the Guild of Enchanters, better known as \"The Circle.\" Its legendary membership and mighty deeds need no introduction.\n");
    return true;
  } else if (context == M_ENTERED) {
    if (loc(GRINDER) == AT_GATE) {
      await SEE_GRINDER();
      tell(S(g.TAB), "\"Welcome back,\" coos ");
      await THE_PRINT(GRINDER);
      tell(" with an evil grin.\n");
      return true;
    }
    return false;
  } else if (context == M_EXIT) {
    if (g.P_WALK_DIR == 0) {
      return false;
    } else if (loc(GRINDER) == AT_GATE) {
      if (g.P_WALK_DIR == P.WEST) {
        await DEQUEUE(I_GRINDER.id);
        tell("\"Coward!\" taunts ");
        await THE_PRINT(GRINDER);
        tell(" as you duck out of range.\n");
        return true;
      }
      await CTHE_PRINT(GRINDER);
      tell(" steps into your path, laughing.\n");
      return M_FATAL;
    } else if (g.P_WALK_DIR == P.NORTH || g.P_WALK_DIR == P.IN) {
      if (!(hasFlag(NYMPH, LIVING))) {
        tell("You step unchallenged through the open gate.\n");
        return true;
      } else if (hasFlag(GRINDER, NODESC)) {
        clearFlag(GRINDER, NODESC);
        g.GRTIMER = 4;
        await QUEUE(I_GRINDER_APPEARS.id);
      }
      if (hasFlag(GUILD_HALL, TOUCHED)) {
        await CTHE_PRINT(NYMPH);
        tell(" promptly reappears. \"They're not back yet. Go away");
      } else {
        tell("A tiny ", D(NYMPH), " appears, floating in the air beside your ");
        await NYMPH_SAYS();
        tell(" come in");
      }
      setFlag(GUILD_HALL, TOUCHED);
      printS(". Bye!\"\n  She disappears with a wink.\n");
      return M_FATAL;
    } else if (g.P_WALK_DIR == P.WEST) {
      if (hasFlag(GRINDER, NODESC) || !(g.GRTIMER == 0)) {
        tell("A");
        if (g.GRTIMER == 1 || g.GRTIMER == 2) {
          tell("nother");
        }
        printS(" noise makes you hesitate.\n");
        if (hasFlag(GRINDER, NODESC)) {
          clearFlag(GRINDER, NODESC);
          g.GRTIMER = 3;
          await QUEUE(I_GRINDER_APPEARS.id);
        }
        await I_GRINDER_APPEARS();
        return M_FATAL;
      }
    }
    return false;
  } else {
    return false;
  }
}

