async function SAY_EXIT() {
  let tbl = 0, dir = 0, xdir = 0;
  xdir = random(8) - 1;
  dir = xdir;
  for (;;) {
    if (++dir > I_NW) {
      dir = I_NORTH;
    }
    tbl = getProp(g.HERE, getb(PDIR_LIST, dir));
    if (tbl == 0) {
    } else if (eq(get(tbl, XTYPE) & 65280, CONNECT)) {
      tell(wordText(get(DIR_NAMES, dir)));
      return false;
    }
  }
}

