async function MENTION_BEAM$() {
  let dir = 0, tbl = 0;
  if (eq(getProp(g.HERE, P.MIRROR_OBJ), NO_MIRROR)) {
    dir = getProp(g.HERE, P.BEAM_DIR);
    if (dir == NO_MIRROR) {
      return false;
    }
    printS("  A beam of sunlight ");
    tell("shines in from the ", wordText(get(DIR_NAMES, dir)));
    dir = dir + 4;
    if (s16(dir) > s16(I_NW)) {
      dir = dir - 8;
    }
    tbl = getProp(g.HERE, getb(PDIR_LIST, dir));
    if (tbl == 0) {
    } else if (eq(get(tbl, XTYPE) & 65280, CONNECT)) {
      tell(", and disappears to the ", wordText(get(DIR_NAMES, dir)));
    }
    tell(S(g.PERIOD));
    return true;
  }
  return false;
}

