async function ON_BRIDGE_F(context = false) {
  let x = 0;
  let $1;
  if (context == M_LOOK) {
    tell("The entire bridge jerks and sways as you struggle to keep your footing on the slippery ropes. ");
    $1 = await PICK_NEXT(BRIDGE_TYPES);
    tell(S($1));
    tell(S(g.PERIOD));
    return true;
  } else if (context == M_ENTERING) {
    if ((g.ZTOP == 1) && (g.ZBOT == 2) && hasFlag(PARASOL, NODESC) && !(hasFlag(PARASOL, TOUCHED))) {
      clearFlag(PARASOL, NODESC);
      move(PARASOL, ON_BRIDGE);
    }
    return false;
  } else if (context == M_EXIT) {
    if (!(g.P_WALK_DIR == P.NORTH || g.P_WALK_DIR == P.SOUTH)) {
      return false;
    } else if (loc(PARASOL) == ON_BRIDGE) {
      remove(PARASOL);
      setFlag(PARASOL, NODESC);
    }
    if (((g.BRIDGE_DIR == 0) || ((g.P_WALK_DIR == P.NORTH) && (g.BRIDGE_DIR == "North")) || ((g.P_WALK_DIR == P.SOUTH) && (g.BRIDGE_DIR == "South")))) {
      if (g.ZBOT == HIGHEST_ZBOT || g.ZBOT == (-1)) {
        g.ZBOT = -1;
      } else {
        g.ZTOP = g.ZTOP + g.ZBOT;
        g.ZBOT = g.ZBOT + g.ZBOT;
      }
    } else if (g.ZBOT == HIGHEST_ZBOT || g.ZBOT == (-1)) {
      g.BRIDGE_DIR = 0;
      g.ZBOT = 2;
      g.ZTOP = 1;
    } else {
      g.ZBOT = g.ZBOT + g.ZBOT;
      g.ZTOP = g.ZBOT - g.ZTOP;
    }
    (g.BRIDGE_DIR = "North");
    if (g.P_WALK_DIR == P.SOUTH) {
      (g.BRIDGE_DIR = "South");
    }
    return false;
  } else {
    return false;
  }
}

