async function HANDLE_ARCH_ROOMS$(context) {
  let x = 0, obj = 0, nxt = 0;
  if (context == M_EXIT) {
    if (g.HERE == getb(ARCH_ROOMS, PRESENT)) {
      return false;
    } else if (obj = first(g.HERE)) {
      for (;;) {
        nxt = next(obj);
        if (hasFlag(obj, TAKEABLE)) {
          remove(obj);
        }
        obj = nxt;
        if (obj == 0) {
          return false;
        }
      }
    }
    return false;
  } else if (!(context == M_BEG)) {
    return false;
  } else if (g.ATIME == PRESENT) {
    return false;
  } else if (x = inTable(g.PRSA, TALKVERBS, NTVERBS)) {
    tell("Your voice has the faint, wistful quality of words ");
    if (s16(g.ATIME) < s16(PRESENT)) {
      tell("yet to be spoken");
    } else {
      tell("spoken long ago");
    }
    x = await QCONTEXT_GOOD$();
    if (!(x == 0)) {
      tell("; ");
      await THE_PRINT(x);
      tell(" seems not to hear");
    }
    printS(g.PERIOD);
    return M_FATAL;
  } else {
    return false;
  }
}

