async function TIMESHIFT() {
  let x = 0;
  if (!(hasFlag(ARCH, SEEN)) || ((g.P_WALK_DIR == P.NORTH) && (g.ATIME == MAX_ATIME)) || ((g.P_WALK_DIR == P.SOUTH) && (g.ATIME == 0))) {
    tell("The weight of centuries restricts your motion.\n");
    return false;
  }
  x = await apply(getProp(g.HERE, P.ACTION), M_EXIT);
  if (!(x == 0)) {
    if (x == M_FATAL) {
      return false;
    } else if (!(g.VERBOSITY == 0)) {
      crlf();
    }
  }
  if (g.P_WALK_DIR == P.NORTH) {
    ++g.ATIME;
  } else {
    --g.ATIME;
  }
  g.HERE = getb(ARCH_ROOMS, g.ATIME);
  move(ARCH, g.HERE);
  g.OLD_HERE = false;
  g.ARCHTIMER = 0;
  await apply(getProp(g.HERE, P.ACTION), M_ENTERING);
  if (hasFlag(LIGHTSHOW, TOUCHED)) {
    tell("You slide ");
  } else {
    tell("The merest effort of will is enough to slide you ");
  }
  if (g.P_WALK_DIR == P.NORTH) {
    tell(wordText(W.FOR));
  } else {
    tell(wordText(W.BACK));
  }
  tell("ward through ");
  await THE_PRINT(LIGHTSHOW);
  if (!(hasFlag(LIGHTSHOW, TOUCHED))) {
    setFlag(LIGHTSHOW, TOUCHED);
    tell(", guided by the Magick of the arch");
  }
  await RELOOK();
  if (!(g.GLASS_TOP == 0)) {
    await I_GLASS();
  }
  return false;
}

