async function SETUP_JUNGLE$() {
  let rm = 0, rm2 = 0, rm3 = 0, len = 0;
  await SCRAMBLE(JUNGLE_ROOMS);
  rm = await NW_ROOM$();
  await NEW_EXIT$(rm, P.NW, 641, NW_UNDER);
  await NEW_EXIT$(NW_UNDER, P.SE, 641, rm);
  rm = await SE_ROOM$();
  await NEW_EXIT$(rm, P.SE, 641, SE_UNDER);
  await NEW_EXIT$(SE_UNDER, P.NW, 641, rm);
  rm = await SW_ROOM$();
  await NEW_EXIT$(rm, P.SW, 641, SW_UNDER);
  await NEW_EXIT$(SW_UNDER, P.NE, 641, rm);
  rm = await S_ROOM$();
  await NEW_EXIT$(rm, P.SOUTH, 645, AT_FALLS);
  await NEW_EXIT$(AT_FALLS, P.NORTH, 645, rm);
  len = getb(JUNGLE_ROOMS, 0);
  loop1: for (;;) {
    rm = getb(JUNGLE_ROOMS, random(len));
    if (rm == JUN0) {
      continue loop1;
    }
    break loop1;
  }
  move(TUSK, rm);
  loop2: for (;;) {
    rm2 = getb(JUNGLE_ROOMS, random(len));
    if (rm2 == rm || rm2 == JUN0) {
      continue loop2;
    }
    break loop2;
  }
  await NEXT_WAND$(DESCRIBE_JUNGLE_WAND.id, rm2);
  loop3: for (;;) {
    rm3 = getb(JUNGLE_ROOMS, random(len));
    if (rm3 == rm2 || rm3 == rm || rm3 == JUN0) {
      continue loop3;
    }
    break loop3;
  }
  await NEXT_SCROLL$(DESCRIBE_JUNGLE_SCROLL.id, rm3);
  await QUEUE(I_CROC.id);
  return true;
}

