async function SCRAMBLE(rtbl, mask = 0) {
  let home = 0, len = 0, rm = 0, nxt = 0, x = 0;
  copyTable(DEFAULT_BORDERS, BORDERS, 50);
  if (arguments.length > 1) {
    len = 24;
    loop1: for (;;) {
      put(BORDERS, len, get(BORDERS, len) & mask);
      if (--len < 0) {
        break loop1;
      }
    }
    putb(BORDERS, 0, 49);
  }
  len = getb(rtbl, 0);
  home = getb(rtbl, 1);
  x = len;
  loop2: for (;;) {
    put(MAZE_ROOMS, x, getb(rtbl, x));
    if (--x < 2) {
      break loop2;
    }
  }
  put(MAZE_ROOMS, 1, 0);
  put(MAZE_ROOMS, 0, len);
  ++len;
  put(g.AUX_TABLE, 0, len);
  put(g.AUX_TABLE, 1, 3);
  put(g.AUX_TABLE, 2, home);
  loop3: for (;;) {
    put(g.AUX_TABLE, len, await PICK_ONE(MAZE_ROOMS));
    if (--len < 3) {
      break loop3;
    }
  }
  copyTable(MAZE_ROOMS, 0, 51);
  clearFlag(home, TOUCHED);
  putProp(home, P.DNUM, 25);
  putb(MAZE_ROOMS, 25, home);
  for (;;) {
    g.LAST_CONNECTION = -1;
    await CLEAR_MAPBITS(rtbl);
    rm = home;
    setFlag(home, MAPPED);
    loop5: for (;;) {
      nxt = await NEXT_ROOM$(rm);
      if (nxt == 0) {
        home = await NEW_HOME$(home);
        break loop5;
      } else if (eq(get(g.AUX_TABLE, 1), 2)) {
        await CLEAR_MAPBITS(rtbl);
        return false;
      } else if (nxt == home) {
        continue loop5;
      } else if (hasFlag(nxt, MAPPED)) {
        home = nxt;
        break loop5;
      }
      setFlag(nxt, MAPPED);
      rm = nxt;
    }
  }
}

async function CLEAR_MAPBITS(tbl) {
  let len = 0;
  len = getb(tbl, 0);
  for (;;) {
    clearFlag(getb(tbl, len), MAPPED);
    if (--len < 1) {
      return false;
    }
  }
}

async function NEW_HOME$(rm) {
  let dir = 0, cnt = 0, tbl = 0;
  cnt = 1;
  dir = P.NW;
  loop1: for (;;) {
    tbl = getProp(rm, dir);
    if (!(tbl == 0)) {
      ++cnt;
      put(g.GOOD_DIRS, cnt, get(tbl, XROOM));
    }
    if (++dir > P.NORTH) {
      break loop1;
    }
  }
  if (cnt == 1) {
    return false;
  } else if (cnt == 2) {
    return get(g.GOOD_DIRS, 2);
  }
  put(g.GOOD_DIRS, 0, cnt);
  put(g.GOOD_DIRS, 1, 0);
  return await PICK_ONE(g.GOOD_DIRS);
}

async function NEXT_ROOM$(rm) {
  let dir = 0, diag = 0, path_len = 0, cnt = 0, bits = 0, rnum = 0, nrm = 0, nrnum = 0, x = 0, len = 0, tbl = 0;
  rnum = getProp(rm, P.DNUM);
  if (rnum == 0) {
    return false;
  }
  bits = getb(BORDERS, rnum);
  cnt = 1;
  loop1: for (;;) {
    if (btst(bits, getb(DBIT_LIST, dir))) {
      x = rnum + get(DIR_HACKS, dir);
      if (getb(MAZE_ROOMS, x)) {
        ++cnt;
        put(g.GOOD_DIRS, cnt, dir);
      }
    }
    if (++dir > 7) {
      break loop1;
    }
  }
  if (cnt == 1) {
    dir = 0;
    loop2: for (;;) {
      if (btst(bits, getb(DBIT_LIST, dir))) {
        if (!(getProp(rm, getb(PDIR_LIST, dir)))) {
          ++cnt;
          put(g.GOOD_DIRS, cnt, dir);
        }
      }
      if (++dir > 7) {
        break loop2;
      }
    }
    if (cnt == 1) {
      return false;
    } else if (cnt == 2) {
      dir = get(g.GOOD_DIRS, 2);
    } else {
      put(g.GOOD_DIRS, 0, cnt);
      put(g.GOOD_DIRS, 1, 0);
      loop3: for (;;) {
        dir = await PICK_ONE(g.GOOD_DIRS);
        if (!(dir == g.LAST_CONNECTION)) {
          break loop3;
        }
      }
    }
  } else if (cnt == 2) {
    dir = get(g.GOOD_DIRS, 2);
  } else {
    put(g.GOOD_DIRS, 0, cnt);
    put(g.GOOD_DIRS, 1, 0);
    loop4: for (;;) {
      dir = await PICK_ONE(g.GOOD_DIRS);
      if (!(dir == g.LAST_CONNECTION)) {
        break loop4;
      }
    }
  }
  g.LAST_CONNECTION = dir;
  nrnum = rnum + get(DIR_HACKS, dir);
  if (btst(dir, 1)) {
    ++diag;
    await KILL_DIAGONAL(rnum, dir);
  }
  path_len = g.SCRAMBLE_LENGTH;
  loop5: for (;;) {
    x = await CAN_EXTEND$(nrnum, dir);
    if (x == 0) {
      break loop5;
    } else if (prob(67)) {
      break loop5;
    } else if (!(diag == 0)) {
      await KILL_DIAGONAL(nrnum, dir);
    }
    await EXTEND(nrnum, dir);
    path_len = path_len + 2;
    nrnum = x;
  }
  nrm = getb(MAZE_ROOMS, nrnum);
  if (nrm == 0) {
    nrm = await PICK_NEXT(g.AUX_TABLE);
    putProp(nrm, P.DNUM, nrnum);
    putb(MAZE_ROOMS, nrnum, nrm);
  }
  len = CONNECT + path_len;
  await NEW_EXIT$(rm, getb(PDIR_LIST, dir), len, nrm);
  putb(BORDERS, rnum, bits & getb(XDBIT_LIST, dir));
  dir = dir + 4;
  if (s16(dir) > s16(7)) {
    dir = dir - 8;
  }
  await NEW_EXIT$(nrm, getb(PDIR_LIST, dir), len, rm);
  bits = getb(BORDERS, nrnum);
  putb(BORDERS, nrnum, bits & getb(XDBIT_LIST, dir));
  return nrm;
}

async function CAN_EXTEND$(rnum, dir) {
  let cnt = 0, xdir = 0, x = 0, bits = 0;
  xdir = dir + 4;
  if (s16(xdir) > s16(7)) {
    xdir = xdir - 8;
  }
  loop1: for (;;) {
    if (cnt == xdir) {
    } else if (!(btst(bits, getb(DBIT_LIST, cnt)))) {
      return false;
    }
    if (++cnt > 7) {
      break loop1;
    }
  }
  return rnum + get(DIR_HACKS, dir);
}

async function EXTEND(rnum, dir) {
  let cnt = 0, xrnum = 0, xdir = 0, bits = 0, list = 0;
  putb(BORDERS, rnum, 0);
  list = XDBIT_LIST + 4;
  xdir = dir + 4;
  if (s16(xdir) > s16(7)) {
    xdir = xdir - 8;
  }
  for (;;) {
    if (!(cnt == dir || cnt == xdir)) {
      xrnum = rnum + get(DIR_HACKS, cnt);
      bits = getb(BORDERS, xrnum);
      putb(BORDERS, xrnum, bits & getb(list, cnt));
    }
    if (++cnt > 7) {
      return false;
    }
  }
}

async function KILL_DIAGONAL(rnum, dir) {
  let cnt = 0, bits = 0, xdir = 0, xrnum = 0, xbits = 0;
  bits = getb(BORDERS, rnum);
  dir = div(dir, 2);
  for (;;) {
    xrnum = rnum + get(DIR_HACKS, getb(QDIRS + cnt, dir));
    xdir = getb(ZDIRS + (cnt + cnt), dir);
    xbits = getb(XDBIT_LIST, xdir);
    putb(BORDERS, xrnum, getb(BORDERS, xrnum) & xbits);
    if (++cnt > 1) {
      return false;
    }
  }
}

async function N_ROOM$() {
  let row = 0, offset = 0, rm = 0;
  row = 4;
  loop1: for (;;) {
    rm = getb(MAZE_ROOMS, row);
    if (!(rm == 0)) {
      return rm;
    }
    offset = 1;
    loop2: for (;;) {
      rm = getb(MAZE_ROOMS, row + offset);
      if (!(rm == 0)) {
        return rm;
      }
      rm = getb(MAZE_ROOMS, row - offset);
      if (!(rm == 0)) {
        return rm;
      } else if (++offset > 3) {
        break loop2;
      }
    }
    row = row + 7;
    if (s16(row) > s16(46)) {
      break loop1;
    }
  }
  return false;
}

