async function CELLAR_DOOR_F() {
  let x = 0;
  if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON, V.LOOK_BEHIND) && hasFlag(g.PRSO, MUNGED)) {
    await ITS_MUNGED(W.DOOR);
    return true;
  } else if (isVerb(V.CLOSE)) {
    if (hasFlag(g.PRSO, MUNGED)) {
      await ITS_MUNGED(W.DOOR);
      return true;
    } else if (!(hasFlag(g.PRSO, OPENED))) {
      return false;
    }
    await ICLOSE();
    tell("You pull ");
    await THE_PRINT();
    tell(" shut.\n");
    if (g.HERE == AT_BOTTOM) {
      clearFlag(g.HERE, LIGHTED);
      await SAY_IF_HERE_LIT();
    }
    return true;
  } else if (isVerb(V.OPEN, V.OPEN_WITH)) {
    if (hasFlag(g.PRSO, MUNGED)) {
      await ITS_MUNGED(W.DOOR);
      return true;
    } else if (hasFlag(g.PRSO, OPENED)) {
      return false;
    } else if ((g.HERE == AT_BOTTOM) && !(hasFlag(g.PRSO, LOCKED))) {
      await LOCK_CELLAR_DOOR();
      return true;
    } else if (g.PRSI == 0) {
      return false;
    } else if (isVerb(V.OPEN_WITH)) {
      await CRASH_CELLAR_DOOR(g.PRSI);
      return true;
    }
    return false;
  } else if ((x = inTable(g.PRSA, E_VERBS, ENTER_VERBS)) || (x = inTable(g.PRSA, X_VERBS, EXIT_VERBS))) {
    if (g.HERE == AT_BOTTOM) {
      await DO_WALK(P.UP);
      return true;
    }
    await DO_WALK(P.DOWN);
    return true;
  } else if (isVerb(V.KICK, V.HIT, V.MUNG, V.LOOSEN, V.PUSH, V.SHAKE, V.CUT, V.KNOCK)) {
    if (hasFlag(g.PRSO, MUNGED)) {
      (await ITS_ALREADY("in ruins"));
      return true;
    } else if (hasFlag(g.PRSO, OPENED)) {
      (await ITS_ALREADY("open"));
      return true;
    } else if (isVerb(V.KNOCK)) {
      if (g.HERE == AT_BOTTOM) {
        tell(S(g.YOU_HEAR), "a muffled \"Har!\"\n");
        return true;
      }
      tell("\"Nobody down there,\" snickers ");
      await THE_PRINT(COOK);
      tell(S(g.PERIOD));
      return true;
    }
    x = g.PRSI;
    if (isVerb(V.KICK)) {
      x = FEET;
    }
    await CRASH_CELLAR_DOOR(x);
    return true;
  } else {
    return false;
  }
}

