async function CRASH_CELLAR_DOOR(obj = HANDS) {
  let tbl = 0;
  (await ITALICIZE("Wham"));
  tell("! Your ");
  if (obj == false || obj == HANDS || obj == ME) {
    tell(wordText(W.FIST));
  } else if (obj == FEET) {
    tell(wordText(W.FOOT));
  } else {
    await DPRINT(obj);
  }
  tell(" deals ");
  await THE_PRINT(CELLAR_DOOR);
  tell(" a mighty blow");
  if (s16(get(g.STATS, STRENGTH)) < s16(50)) {
    await NOTE_NOISE();
    return true;
  }
  setFlag(CELLAR_DOOR, OPENED);
  clearFlag(CELLAR_DOOR, LOCKED);
  setFlag(CELLAR_DOOR, MUNGED);
  setFlag(AT_BOTTOM, LIGHTED);
  tbl = getPropAddr(CELLAR_DOOR, P.SYNONYM);
  put(tbl, 2, W.HOLE);
  put(tbl, 3, W.OPENING);
  tbl = getProp(AT_BOTTOM, P.UP);
  put(tbl, XTYPE, 513);
  put(tbl, XROOM, IN_KITCHEN);
  tbl = getProp(IN_KITCHEN, P.DOWN);
  put(tbl, XTYPE, 513);
  put(tbl, XROOM, AT_BOTTOM);
  tbl = getProp(IN_KITCHEN, P.IN);
  put(tbl, XTYPE, 513);
  put(tbl, XROOM, AT_BOTTOM);
  tell(", shattering it and much of ");
  await THE_PRINT(KITCHEN);
  tell(" wall into splinters");
  await RELOOK();
  tell(S(g.TAB), "\"Yow,\" murmurs ");
  if (g.HERE == AT_BOTTOM) {
    tell("an admiring voice upstairs.\n");
    return true;
  }
  setFlag(COOK, SEEN);
  await THE_PRINT(COOK);
  tell(", gawking at you admiringly.\n");
  return true;
}

