async function HANDLE_STAIRS$(top) {
  let x = 0;
  if (!(g.HERE == top)) {
    top = false;
  }
  if (!(g.NOW_PRSI$ == 0)) {
    if (await MIGHT_TRIP$()) {
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
    await CTHE_PRINT();
    tell(" leads ");
    if (!(top == 0)) {
      tell("down");
    } else {
      tell("up");
    }
    tell("ward.\n");
    return true;
  } else if (isVerb(V.LOOK_UP)) {
    if (!(top == 0)) {
      await ALREADY_AT_TOP();
      return true;
    }
    await CANT_SEE_MUCH();
    return true;
  } else if (isVerb(V.LOOK_DOWN)) {
    if (!(top == 0)) {
      await CANT_SEE_MUCH();
      return true;
    }
    await ALREADY_AT_BOTTOM();
    return true;
  } else if (isVerb(V.FOLLOW, V.USE)) {
    if (!(top == 0)) {
      await DO_WALK(P.DOWN);
      return true;
    }
    await DO_WALK(P.UP);
    return true;
  } else if (x = inTable(g.PRSA, E_VERBS, CLIMB_ON_VERBS)) {
    if (!(top == 0)) {
      await ALREADY_AT_TOP();
      return true;
    }
    await DO_WALK(P.UP);
    return true;
  } else if (x = inTable(g.PRSA, X_VERBS, CLIMB_DOWN_VERBS)) {
    if (!(top == 0)) {
      await DO_WALK(P.DOWN);
      return true;
    }
    await ALREADY_AT_BOTTOM();
    return true;
  } else {
    return false;
  }
}

