  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
  await REPLACE_ADJ$(LANTERN, W.ZZZP, W.BROKEN);
  if (hasFlag(LANTERN, LIGHTED)) {
    await LANTERN_OUT();
  }
  return true;
