async function SAY_AMULET_WORD() {
  if (g.AMULET_STARS == 0) {
  } else if (hasFlag(AMULET, NEUTRALIZED)) {
  } else if (await NO_MAGIC_HERE$(AMULET)) {
    return true;
  } else if (await VISIBLE$(AMULET)) {
    if (!(g.AMULET_TIMER == 0)) {
      await STAR_FADES(true);
      await STOP_AMULET();
      if (await WEARING_MAGIC$(AMULET)) {
        await NORMAL_STRENGTH();
      }
      return true;
    } else if (s16(g.AMULET_STARS) > s16(1)) {
      printS("One of the stars");
    } else {
      printS("The star");
    }
    printS(" on the amulet ");
    tell("begins to glow.\n");
    putProp(AMULET, P.VALUE, getProp(AMULET, P.VALUE) - 3);
    if (await WEARING_MAGIC$(AMULET)) {
      await MEGA_STRENGTH();
    }
    await LIGHT_ROOM_WITH(AMULET);
    g.AMULET_TIMER = 3;
    await QUEUE(I_AMULET.id);
    return true;
  }
  await NOTHING_HAPPENS(false);
  return true;
}

async function MEGA_STRENGTH() {
  let s_ = 0;
  s_ = get(g.STATS, STRENGTH);
  if (s16(s_) < s16(2)) {
    s_ = 9;
  } else {
    s_ = 9 * s_;
  }
  tell(S(g.TAB), "A pulse of energy surges through your muscles!\n");
  await UPDATE_STAT(s_, STRENGTH);
  return true;
}

async function NORMAL_STRENGTH() {
  let s_ = 0, max = 0;
  tell(S(g.TAB), "The tension in your muscles subsides.\n");
  s_ = get(g.STATS, STRENGTH);
  max = get(g.MAXSTATS, STRENGTH);
  if (s16(s_) > s16(max)) {
    await UPDATE_STAT(0 - (s_ - max), STRENGTH);
  }
  return true;
}

async function STOP_AMULET() {
  await DEQUEUE(I_AMULET.id);
  g.AMULET_TIMER = 0;
  clearFlag(AMULET, LIGHTED);
  if (--g.AMULET_STARS < 1) {
    g.AMULET_STARS = 0;
    await REPLACE_SYN$(AMULET, W.STAR, W.ZZZP);
    await REPLACE_SYN$(AMULET, W.STARS, W.ZZZP);
    await REPLACE_ADJ$(AMULET, W.SILVER, W.ZZZP);
  }
  if (await VISIBLE$(AMULET)) {
    await SAY_IF_HERE_LIT();
  }
  return false;
}

