async function GONDOLA_F(context = false) {
  let obj = 0, x = 0;
  if (!(context == 0)) {
    obj = g.PRSO;
    if (!(g.NOW_PRSI$ == 0)) {
      obj = g.PRSI;
    }
    if (context == M_BEG) {
      return await CANT_REACH_WHILE_IN$(obj, GONDOLA);
    } else if (context == M_CONT) {
      if (loc(PLAYER) == GONDOLA) {
        return false;
      } else if (obj == 0) {
        return false;
      } else if (x = inTable(g.PRSA, TOUCHVERBS, NTOUCHES)) {
        (await YOUD_HAVE_TO("board", GONDOLA));
        return true;
      }
      return false;
    }
    return false;
  } else if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if ((x = inTable(g.PRSA, E_VERBS, ENTER_VERBS)) && !(loc(PLAYER) == g.PRSO)) {
    if ((g.HERE == AT_DOCK) && (g.GON == 0 || g.GON == 1 || g.GON == 14)) {
      tell("\"Wait yer turn, ");
      if (hasFlag(PLAYER, FEMALE)) {
        tell(wordText(W.LADY));
      } else {
        tell("buddy");
      }
      tell(",\" growls a passenger in front of you.\n");
      return true;
    }
    g.OLD_HERE = false;
    g.P_WALK_DIR = false;
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
    move(g.WINNER, g.PRSO);
    clearFlag(g.PRSO, NODESC);
    if (g.HERE == AT_DOCK) {
      tell("You shove your way ");
    } else {
      printS("Children tug their parents' sleeves and point as you clamber ");
    }
    tell("into ");
    await THE_PRINT();
    await RELOOK();
    return true;
  } else if ((x = inTable(g.PRSA, X_VERBS, EXIT_VERBS)) && (loc(PLAYER) == g.PRSO)) {
    setFlag(g.PRSO, NODESC);
    if (g.HERE == OVER_JUNGLE) {
      await JUNGLE_JUMP();
      return true;
    }
    g.OLD_HERE = false;
    g.P_WALK_DIR = false;
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
    move(g.WINNER, g.HERE);
    if (g.HERE == AT_DOCK) {
      printS("You push your way ");
      tell("out of ");
      await THE_PRINT();
      await RELOOK();
      return true;
    }
    printS("Children tug their parents' sleeves and point as you clamber ");
    printS("over the gondola's edge");
    await RELOOK();
    tell(S(g.TAB), "\"Passengers will please remain seated,\" drones ");
    await THE_PRINT(CONDUCTOR);
    tell(S(g.PERIOD));
    return true;
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE)) {
    tell("A decal on the side says, \"");
    (await FROBOZZ("Gondola"));
    tell(S(g.PERQ));
    return true;
  } else {
    return false;
  }
}

