async function ZBRIDGE_F() {
  let x = 0;
  if (!(g.NOW_PRSI$ == 0)) {
    if ((x = inTable(g.PRSA, PUTVERBS, NUMPUTS)) || isVerb(V.HANG_ON)) {
      await VANISH();
      await CTHE_PRINT();
      if (g.PRSO == PARASOL || g.PRSO == LANTERN) {
        tell(" dangles uncertainly for a moment,");
      }
      tell(" falls off the slippery ropes and plummets into the roaring water.\n");
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
    tell("The long, narrow ");
    await DPRINT(g.PRSO);
    tell(" leads ");
    if (g.HERE == ON_BRIDGE || g.HERE == SFORD) {
      tell(wordText(W.NORTH));
      if (g.HERE == ON_BRIDGE) {
        tell(S(g.AND), wordText(W.SOUTH));
      }
    } else {
      tell(wordText(W.SOUTH));
    }
    tell(" across the roaring water.\n");
    return true;
  } else if (isVerb(V.ENTER, V.STAND_ON, V.WALK_TO)) {
    if (g.HERE == ON_BRIDGE) {
      await ALREADY_ON();
      return true;
    } else if (g.HERE == SFORD) {
      await DO_WALK(P.NORTH);
      return true;
    }
    await DO_WALK(P.SOUTH);
    return true;
  } else if (x = inTable(g.PRSA, E_VERBS, CLIMB_ON_VERBS)) {
    x = P.NORTH;
    if (g.HERE == SFORD) {
    } else if (((g.HERE == ON_BRIDGE) && eq(getProp(g.HERE, P.DNUM), "North"))) {
    } else {
      x = P.SOUTH;
    }
    await DO_WALK(x);
    return true;
  } else if ((await JUMPING_OFF$()) || isVerb(V.STAND_UNDER)) {
    await DO_WALK(P.DOWN);
    return true;
  } else if (x = inTable(g.PRSA, X_VERBS, EXIT_VERBS)) {
    if (!(g.HERE == ON_BRIDGE)) {
      await NOT_ON();
      return true;
    }
    await V_WALK_AROUND();
    return true;
  } else {
    return false;
  }
}

async function SWALL_F() {
  let x = 0;
  if ((await NOUN_USED$(W.OPENING, W.HOLE)) && !(hasFlag(SWALL, OPENED))) {
    await NONE_HERE(W.OPENING);
    return M_FATAL;
  } else if (!(hasFlag(SWALL, SEEN)) && (await NOUN_USED$(W.DOOR, W.DOORWAY))) {
    await NONE_HERE(W.DOOR);
    return M_FATAL;
  } else if (await NOUN_USED$(W.OUTLINE)) {
    if (hasFlag(SWALL, OPENED)) {
      tell(S(g.XTHE), wordText(W.OUTLINE), " is now an ", wordText(W.OPENING), S(g.PERIOD));
      return M_FATAL;
    } else if (!(hasFlag(SWALL, SEEN))) {
      await NONE_HERE(W.OUTLINE);
      return M_FATAL;
    }
  }
  if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.SAY, V.YELL) && !(g.WALL_WORD == 0) && ((await NOUN_USED$(g.WALL_WORD)) || (await ADJ_USED$(g.WALL_WORD)))) {
    await SAY_WALL_WORD();
    return true;
  } else if (isVerb(V.EXAMINE, V.SEARCH, V.LOOK_ON, V.LOOK_INSIDE, V.LOOK_BEHIND, V.LOOK_UNDER)) {
    if (hasFlag(g.PRSO, SEEN)) {
      await SEE_DOORLIKE(g.PRSO);
      if (g.HERE == SE_CAVE) {
        tell(wordText(W.SOUTHEAST), C(SP));
      }
      tell(wordText(W.WALL), S(g.PERIOD));
      return true;
    }
    await SEAMLESS_WALL();
    return true;
  } else if (isVerb(V.ENTER, V.WALK_TO, V.THROUGH, V.WALK_AROUND, V.FOLLOW)) {
    x = P.SW;
    if (g.HERE == NE_CAVE) {
      x = P.NE;
    }
    await DO_WALK(x);
    return true;
  } else if (isVerb(V.OPEN, V.PUSH, V.MOVE)) {
    if (hasFlag(g.PRSO, OPENED)) {
      (await ITS_ALREADY("open"));
      return true;
    } else if (!(hasFlag(SWALL, SEEN))) {
      await SHOVE_STRAIN();
      return true;
    }
    await OPEN_SWALL();
    await WALLPUSH();
    return true;
  } else if (isVerb(V.CLOSE, V.PULL)) {
    if (!(hasFlag(g.PRSO, OPENED))) {
      if (!(hasFlag(SWALL, SEEN))) {
        await NONE_HERE(W.OPENING);
        return true;
      }
      (await ITS_ALREADY("closed"));
      return true;
    }
    await CLOSE_SWALL();
    await WALLCLOSE();
    return true;
  } else {
    return false;
  }
}

async function WALLCLOSE() {
  tell("You slowly pull the secret door shut.\n");
  return true;
}

async function WALLPUSH() {
  tell("You push against the outline on the wall with all your might, and an opening appears.\n");
  return true;
}

