async function UNICORNS_FLEE(str = 0) {
  await PCLEAR();
  await DEQUEUE(I_MARE_SEES.id);
  await QUEUE(I_ARREST.id, 2);
  remove(HERD);
  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
  tell("One of the mares glances up ");
  if (arguments.length > 0) {
    tell(S(str));
  } else {
    tell("as you draw closer");
  }
  tell(". Her nostrils flare with surprise, and a high-pitched voice in your head cries, \"");
  if (hasFlag(HERD, SEEN)) {
    tell("Another i");
  } else {
    tell("I");
  }
  tell("ntruder!\"\n  The herd springs to full alert. Mothers nudge their frightened colts out of sight, then gallop away between the trees. Within moments, the glade is completely deserted.\n");
  return true;
}

