async function SOFT_PHASE_F() {
  let x = 0;
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.TOUCH_TO)) {
      if (g.PRSO == HANDS) {
        await FEEL_PHASE();
        return true;
      }
      await PASS_THRU(g.PRSO, g.PRSI);
      return true;
    } else if (isVerb(V.HIT, V.MUNG, V.CUT)) {
      await PHASE_WHOOSH();
      return true;
    }
    return false;
  } else if (x = inTable(g.PRSA, SEEVERBS, NSVERBS)) {
    if (hasFlag(g.PRSO, NODESC)) {
      tell("You still can't see ");
      await THE_PRINT();
      tell(S(g.PERIOD));
      return true;
    }
    setFlag(PHASE, NODESC);
    setFlag(PHASE, SEEN);
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
    await CTHE_PRINT();
    tell(" disappears the moment you set eyes on it.\n");
    return true;
  } else if (isVerb(V.TOUCH_TO)) {
    if (g.PRSI == false || g.PRSI == HANDS) {
      await FEEL_PHASE();
      return true;
    }
    await PASS_THRU(g.PRSO, g.PRSI);
    return true;
  } else if (isVerb(V.TOUCH, V.HIT, V.SQUEEZE)) {
    if (g.PRSI == false || g.PRSI == HANDS) {
      await FEEL_PHASE();
      return true;
    }
    await PASS_THRU(g.PRSI, g.PRSO);
    return true;
  } else {
    return false;
  }
}

