async function DO_TELE(obj, w_) {
  let s_ = 0, l = 0, len = 0, rm = 0;
  if (await DONT_HAVE_WAND$(obj, w_)) {
    return true;
  } else if (await NOT_LIVING$(obj, w_)) {
    return true;
  } else if (await OUT_OF_GAS$(w_)) {
    return true;
  }
  s_ = await WAND_STRENGTH$(w_);
  l = loc(obj);
  tell("A ray of hard blue ");
  await EXPLODES(w_);
  if ((obj == ME || obj == HANDS || obj == FEET) || (obj == GRINDER) || (l == PLAYER) || (loc(l) == PLAYER)) {
    if (obj == GRINDER) {
      await QUICKER();
      tell(" and uses the lid to reflect the ray back into your face");
    }
    len = getb(TELEROOMS, 0);
    loop1: for (;;) {
      rm = getb(TELEROOMS, random(len));
      if (rm == g.HERE) {
        continue loop1;
      }
      break loop1;
    }
    tell("! You're engulfed");
    printS(" in a dizzy maelstrom of sound and motion");
    tell("...\n");
    g.P_WALK_DIR = false;
    g.OLD_HERE = false;
    await SAFE_VEHICLE_EXIT();
    await CARRIAGE_RETURNS();
    await GOTO(rm);
    tell(S(g.TAB), S(g.XTHE), wordText(W.LANDSCAPE), " stops reeling");
  } else if (hasFlag(obj, MONSTER)) {
    if (!(obj == DUST || obj == WIGHT)) {
      setFlag(obj, SLEEPING);
      setFlag(obj, NEUTRALIZED);
      await TELEPORT_MONSTER(obj);
    }
    tell(", engulfing ");
    await THE_PRINT(obj);
    printS(" in a dizzy maelstrom of sound and motion");
    tell(S(g.PERIOD));
    if (obj == DUST) {
      if (!(hasFlag(obj, TOUCHED))) {
        await START_DUST();
      }
      clearFlag(obj, SEEN);
      await UPDATE_STAT(0 - getProp(w_, P.STRENGTH), STRENGTH);
      return true;
    }
    tell(S(g.TAB));
    (await ITALICIZE("Poof"));
    tell(". ");
    await CTHE_PRINT(obj);
    if (obj == WIGHT) {
      printS(" disappears in a spectral flash");
      tell(", rematerializing ten feet beyond the edge of the cliff. It");
      printS(" gives you a puzzled frown");
      tell(", looks down, looks back up at you, waves goodbye and plummets out of sight");
    } else {
      tell(" is nowhere to be seen");
    }
  } else {
    printS(", barely missing its wide-eyed target");
  }
  printS(g.PERIOD);
  await UPDATE_STAT(0 - getProp(w_, P.STRENGTH), STRENGTH);
  if (obj == WIGHT) {
    await KILL_MONSTER(WIGHT);
  }
  await STARTLE(obj, w_);
  return true;
}

