async function DO_SLEEP(obj, w_) {
  let s_ = 0, len = 0;
  if (await DONT_HAVE_WAND$(obj, w_)) {
    return true;
  } else if (await NOT_LIVING$(obj, w_)) {
    return true;
  } else if (await OUT_OF_GAS$(w_)) {
    return true;
  }
  s_ = await WAND_STRENGTH$(w_);
  tell("A beam of soothing amber radiance ");
  if (obj == ME) {
    g.ATTACK_MODE = THRUSTING;
    tell("forces you to stifle a yawn.\n");
    await UPDATE_STAT(s_, STRENGTH);
    return true;
  }
  tell("envelops ");
  await THE_PRINT(obj);
  tell(" as you train ");
  await THE_PRINT(w_);
  tell(" upon ");
  await PRONOUN(obj, true);
  len = get(NO_SLEEPS, 0);
  if (obj == DACT) {
    if (!(g.DACT_SLEEP == 0)) {
      if (!(g.DACT_SLEEP == 3)) {
        ++g.DACT_SLEEP;
      }
      tell(", and he snuggles deeper into his nap.\n");
      await UPDATE_STAT(s_, STRENGTH);
      return true;
    }
    tell(S(g.PTAB));
    await CTHE_PRINT(obj);
    await DACT_TO_SLEEP();
  } else if (obj == DORN) {
    tell(". Two or three of its 69 eyes flutter drowsily.\n");
  } else if (obj == OWOMAN) {
    tell(S(g.PTAB), "\"Stop it!\" she laughs, brushing aside the beam with a wave. \"That tickles.\"\n");
  } else if (obj == CORBIES) {
    tell(". A few seem to hesitate in their flight; but they recover quickly.\n");
  } else if (obj == PUPP) {
    tell(S(g.PTAB));
    await CTHE_PRINT(obj);
    tell(" promptly mimics your action, using its third finger to represent your ");
    await DPRINT(w_);
    tell(S(g.PERIOD));
  } else if ((len = inTable(obj, NO_SLEEPS + 2, len)) || ((obj == WORM) && !(hasFlag(obj, MONSTER)))) {
    tell(". But ");
    await THE_PRINT(obj);
    tell(" appears to be completely unaffected.\n");
  } else if ((obj == GRINDER) || !(hasFlag(obj, MONSTER))) {
    tell("; but aside from a brief fit of yawning, ");
    await THE_PRINT(obj);
    tell(" seems unaffected.\n");
  } else if (hasFlag(obj, SLEEPING)) {
    tell(". Nothing further seems to happen.\n");
  } else {
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
    await REPLACE_ADJ$(obj, W.AWAKE, W.STUNNED);
    setFlag(obj, SLEEPING);
    setFlag(obj, NEUTRALIZED);
    tell(S(g.PERIOD));
  }
  await UPDATE_STAT(s_, STRENGTH);
  return true;
}

async function DACT_TO_SLEEP(g_ = 0) {
  tell(" closes his eyes, swaying his skinny head back and forth with drowsy reminiscences");
  if (!(g_ == 0)) {
    tell(". Soon his snore drowns out the fading song");
  }
  if (g.HERE == IN_SKY) {
    tell(S(g.PTAB), "You tumble into a nose dive as ");
    await THE_PRINT(DACT);
    tell("'s wings go limp. Desperate screams of terror do not wake him in time to avoid a crash");
    await JIGS_UP();
    return false;
  }
  tell(S(g.PERIOD));
  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
  await REPLACE_ADJ$(DACT, W.AWAKE, W.SLEEPING);
  setFlag(DACT, SLEEPING);
  g.DACT_SLEEP = 4;
  return false;
}

