async function DO_IO(obj, w_) {
  let s_ = 0, nxt = 0, x = 0;
  if (await DONT_HAVE_WAND$(obj, w_)) {
    return true;
  } else if (await OUT_OF_GAS$(w_)) {
    return true;
  }
  s_ = await WAND_STRENGTH$(w_);
  (await ITALICIZE("Blit"));
  tell("! A zone of negative geometry forms in the space around ");
  if (obj == ME || obj == HANDS || obj == FEET) {
    g.ATTACK_MODE = THRUSTING;
    tell("your body");
  } else {
    await THE_PRINT(obj);
    tell(", effectively turning ");
    await PRONOUN(obj, true);
    tell(" inside out");
  }
  tell(". This disconcerting effect lasts only for a moment");
  if (obj == ME || obj == HANDS || obj == FEET) {
  } else if ((obj == IDOL_ROOM) && (g.HERE == INNARDS)) {
    g.P_WALK_DIR = false;
    g.OLD_HERE = false;
    g.HERE = loc(MAW);
    clearFlag(g.HERE, TOUCHED);
    move(PLAYER, g.HERE);
    await MOVE_ALL(INNARDS, g.HERE, NODESC);
  } else if (obj == OWOMAN) {
    tell(S(g.PTAB), "\"Very funny,\" she remarks, regaining her composure");
  } else if (obj == BOTTLE) {
    tell("; very little of ");
    await THE_PRINT(obj);
    tell("'s contents escapes.\n");
  } else if ((obj == MAMA) && (nxt = first(obj))) {
    obj = nxt;
    loop1: for (;;) {
      nxt = next(obj);
      clearFlag(obj, NODESC);
      move(obj, loc(MAMA));
      obj = nxt;
      if (obj == 0) {
        break loop1;
      }
    }
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
    tell("; but long enough for the undigested contents of ");
    await THE_PRINT(MAMA);
    tell("'s stomach to fall ");
    obj = GROUND;
    if (!(loc(MAMA) == g.HERE)) {
      tell("on");
      obj = loc(MAMA);
    }
    tell("to ");
    await THE_PRINT(obj);
  } else if (hasFlag(obj, LIVING)) {
    tell(", and leaves ");
    await THE_PRINT(obj);
    tell(" looking ");
    if (hasFlag(obj, MONSTER) && !(hasFlag(obj, SLEEPING))) {
      g.ATTACK_MODE = THRUSTING;
      tell("madder than ever");
    } else {
      tell("rather upset");
    }
  } else if (hasFlag(obj, CONTAINER) && (obj = first(obj))) {
    x = 0;
    loop2: for (;;) {
      if (hasFlag(obj, NODESC)) {
      } else if (hasFlag(obj, TAKEABLE)) {
        ++x;
      }
      if (!(obj = next(obj))) {
        break loop2;
      }
    }
    if (!(x == 0)) {
      tell("; but you catch a glimpse of some");
      if (x == 1) {
        tell(wordText(W.THING));
      } else {
        tell(" things");
      }
      tell(" inside");
    }
  }
  tell(S(g.PERIOD));
  await UPDATE_STAT(s_, STRENGTH);
  return true;
}

