async function DO_BLAST(obj, w_) {
  let b = 0, s_ = 0, l = 0;
  if (await DONT_HAVE_WAND$(obj, w_)) {
    return true;
  } else if (await NOT_LIVING$(obj, w_)) {
    return true;
  } else if (await OUT_OF_GAS$(w_)) {
    return true;
  }
  s_ = await WAND_STRENGTH$(w_);
  l = loc(obj);
  await KERBLAM();
  tell("A searing bolt of ");
  await EXPLODES(w_);
  if ((obj == ME || obj == HANDS || obj == FEET) || (l == PLAYER) || (loc(l) == PLAYER)) {
    tell(", instantly consuming ");
    if (obj == ME) {
      tell("you in flames");
    } else {
      await THE_PRINT(obj);
      tell(" in flames, and you with it");
    }
    await JIGS_UP();
    return true;
  } else if (obj == GRINDER) {
    await QUICKER();
    tell(", whirls the crank and sucks the deadly plasma under the lid.\n");
  } else if (obj == DUST) {
    if (!(hasFlag(obj, TOUCHED))) {
      await START_DUST();
    }
    loop1: for (;;) {
      await MORE_BUNNIES();
      if (++b > 2) {
        break loop1;
      }
    }
    tell(", scattering dust bunnies all over the room.\n");
  } else if (hasFlag(obj, MONSTER)) {
    putProp(obj, P.ENDURANCE, 0);
    putProp(obj, P.STRENGTH, 0);
    tell(", striking ");
    await THE_PRINT(obj);
    tell(" squarely in the face!\n");
  } else {
    tell(", barely missing ");
    if ((obj == WORM) && !(hasFlag(obj, MONSTER))) {
      await THE_PRINT(obj);
    } else {
      tell("its wide-eyed target");
    }
    printS(g.PERIOD);
  }
  await UPDATE_STAT(s_, STRENGTH);
  await STARTLE(obj, w_);
  return true;
}

