async function WAND_STRENGTH$(obj) {
  let s_ = 0, x = 0;
  s_ = getProp(obj, P.STRENGTH);
  x = get(g.STATS, ENDURANCE) - 1;
  if (s16(s_) < s16(1)) {
    s_ = 1;
  } else if (s16(s_) > s16(x)) {
    s_ = x;
  }
  return 0 - s_;
}

async function OUT_OF_GAS$(w_) {
  let gas = 0;
  let $1;
  setFlag(w_, USED);
  gas = getProp(w_, P.ENDURANCE);
  if ((gas == 0) || hasFlag(w_, NEUTRALIZED)) {
    await CTHE_PRINT(w_);
    $1 = await PICK_NEXT(EMPTY_WANDS);
    tell(S($1));
    tell(". Its virtue");
    if (gas == 0) {
      tell(" seems to be exhausted.\n");
      return true;
    }
    printS(" appears to have been neutralized");
    tell(S(g.PERIOD));
    return true;
  }
  putProp(w_, P.ENDURANCE, gas - 1);
  return false;
}

