async function CURTAIN_F(context = false) {
  let x = 0;
  if (!(context == 0)) {
    if (context == M_OBJDESC) {
      tell("A closed curtain hangs suspended in midair.");
      return true;
    }
    return false;
  } else if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.CLOSE)) {
    (await ITS_ALREADY("closed"));
    return true;
  } else if (isVerb(V.LOOK_BEHIND, V.LOOK_UNDER) || (x = inTable(g.PRSA, E_VERBS, ENTER_VERBS)) || (x = inTable(g.PRSA, TOUCHVERBS, NTOUCHES))) {
    if (!(g.HERE == APLANE)) {
      await ENTER_CURTAIN();
      return true;
    }
    if (await HELD$(PHASE)) {
      await MUNG_PHASE();
    }
    await AS_YOU_APPROACH();
    tell("your eyes momentarily lose their focus.\n");
    if (!(g.VERBOSITY == 0)) {
      crlf();
    }
    x = IN_MAGICK;
    if (g.ABOVE == OACCARDI) {
      clearFlag(WEAPON_DOOR, OPENED);
      x = IN_WEAPON;
    } else if (g.ABOVE == OMIZNIA) {
      clearFlag(BOUTIQUE_DOOR, OPENED);
      x = IN_BOUTIQUE;
    }
    await GOTO(x);
    tell(S(g.TAB), S(g.CTHELADY), " glances up as you appear. \"");
    x = random(100);
    if (s16(x) < s16(33)) {
      tell("Hello");
    } else if (s16(x) < s16(67)) {
      tell("Welcome");
    } else {
      tell("Greetings");
    }
    tell(",\" she says, ");
    if (g.ABOVE == OCITY) {
      tell("glaring at the");
      await OPEN_CLOSED(MAGICK_DOOR);
      tell(". \"Gotta fix that bell.\"\n");
      return true;
    }
    tell("frowning at the closed door.\n");
    return true;
  } else {
    return false;
  }
}

