async function NOTE_MIRROR(obj, wrd) {
  tell(" is suspended in midair");
  if (!(loc(QUEEN) == g.HERE)) {
    tell(", facing ", wordText(wrd));
    await BEAM_DETAILS(obj);
  }
  return false;
}

async function BEAM_DETAILS(obj) {
  let dir = 0, sdir = 0, x1 = 0, x2 = 0, x3 = 0;
  if (!(eq(getProp(g.HERE, P.MIRROR_OBJ), obj))) {
    return false;
  }
  sdir = getProp(g.HERE, P.BEAM_DIR);
  if (sdir == NO_MIRROR) {
    return false;
  }
  dir = getProp(obj, P.MIRROR_DIR);
  tell(". Sunlight from the ", wordText(get(DIR_NAMES, sdir)), " exit is ");
  if (sdir == dir) {
    tell("shining directly onto the mirror's face");
    return true;
  }
  x1 = sdir + 1;
  if (s16(x1) > s16(I_NW)) {
    x1 = I_NORTH;
  }
  if (dir == x1) {
    if (++x1 > I_NW) {
      x1 = I_NORTH;
    }
    await REFLECT_TO(x1);
    return true;
  }
  x1 = sdir - 1;
  if (s16(x1) < s16(I_NORTH)) {
    x1 = I_NW;
  }
  if (dir == x1) {
    if (--x1 < I_NORTH) {
      x1 = I_NW;
    }
    await REFLECT_TO(x1);
    return true;
  }
  x1 = sdir - 2;
  if (s16(x1) < s16(I_NORTH)) {
    x1 = x1 + 8;
  }
  x2 = sdir + 2;
  if (s16(x2) > s16(I_NW)) {
    x2 = x2 - 8;
  }
  if (dir == x1 || dir == x2) {
    tell("glinting on the mirror's edge");
    return true;
  }
  x1 = sdir + 4;
  if (s16(x1) > s16(I_NW)) {
    x1 = x1 - 8;
  }
  x2 = sdir + 3;
  if (s16(x2) > s16(I_NW)) {
    x2 = x2 - 8;
  }
  x3 = sdir - 3;
  if (s16(x3) < s16(I_NORTH)) {
    x3 = x3 + 8;
  }
  if (dir == x1 || dir == x2 || dir == x3) {
    tell("illuminating the back of the mirror");
  }
  return true;
}

async function REFLECT_TO(dir) {
  tell("reflected ", wordText(get(DIR_NAMES, dir)));
  dir = getProp(g.HERE, getb(PDIR_LIST, dir));
  if (dir == 0) {
  } else if (eq(get(dir, XTYPE) & 65280, CONNECT)) {
    return false;
  }
  tell(", onto the wall");
  return true;
}

async function HANDLE_MIRRORS$(obj, context) {
  let dir = 0, wrd = 0, x = 0;
  dir = getProp(obj, P.MIRROR_DIR);
  wrd = get(DIR_NAMES, dir);
  if (context == M_OBJDESC) {
    await PRINTCA(obj);
    await NOTE_MIRROR(obj, wrd);
    tell(C(PER));
    return true;
  } else if (!(context == 0)) {
    return false;
  } else if (await NOUN_USED$(W.BUBBLES)) {
    tell("There's only one ", wordText(W.BUBBLE), " here.\n");
    return M_FATAL;
  } else if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (x = inTable(g.PRSA, TALKVERBS, NTVERBS)) {
    await MIRROR_REFLECTS();
    return M_FATAL;
  } else if (isVerb(V.EXAMINE)) {
    await CTHE_PRINT();
    await NOTE_MIRROR(obj, wrd);
    tell(S(g.PERIOD));
    return true;
  } else if (isVerb(V.POINT_AT, V.PUSH_TO)) {
    if (g.LIT$ == 0) {
      await TOO_DARK();
      return true;
    } else if (g.PRSI == URGRUE) {
      x = getProp(g.PRSI, P.DNUM);
      if (x == dir) {
        await ALREADY_FACING();
        return true;
      }
      await NEW_MIRROR_DIR(x);
      return true;
    } else if (g.PRSI == INTDIR) {
      if ((g.P_DIRECTION == P.UP || g.P_DIRECTION == P.DOWN) || (g.P_DIRECTION == P.IN || g.P_DIRECTION == P.OUT)) {
        await CTHE_PRINT();
        printS(" can't be moved that way.\n");
        return true;
      } else if (eq(getb(PDIR_LIST, dir), g.P_DIRECTION)) {
        await ALREADY_FACING();
        return true;
      }
      await NEW_MIRROR_DIR(0 - (g.P_DIRECTION - P.NORTH));
      return true;
    }
    await NYMPH_APPEARS();
    tell("To direct the mirror, simply specify a ", D(INTDIR), "; for example, TURN THE MIRROR TO THE NORTH or AIM MIRROR SW");
    printS(". Bye!\"\n  She disappears with a wink.\n");
    return true;
  } else if (isVerb(V.SPIN, V.SWING, V.TURN, V.PUSH, V.MOVE)) {
    loop1: for (;;) {
      x = random(7) | 1;
      if (x == dir) {
        continue loop1;
      }
      break loop1;
    }
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
    putProp(g.PRSO, P.MIRROR_DIR, x);
    await CTHE_PRINT();
    tell(" spins randomly around, slows and stops. It's now facing ", wordText(get(DIR_NAMES, x)), S(g.PERIOD));
    if (eq(getProp(g.HERE, P.MIRROR_OBJ), obj)) {
      await REFLECTIONS();
    }
    return true;
  } else if (isVerb(V.LOOK_INSIDE)) {
    tell(S(g.YOU_SEE));
    if (loc(QUEEN) == g.HERE) {
      await THE_PRINT(QUEEN);
    } else {
      tell(D(ME));
    }
    tell(" reflected in ");
    await THE_PRINT();
    tell(S(g.PERIOD));
    return true;
  } else if (isVerb(V.HIT, V.SQUEEZE, V.KICK, V.REACH_IN, V.POP, V.MUNG)) {
    await DESTROY_MIRROR(obj);
    await SAY_MIRROR_POPS(obj);
    return true;
  } else if (isVerb(V.THROW)) {
    move(g.PRSI, g.HERE);
    await CTHEI_PRINT();
    tell(" strikes ");
    await THE_PRINT();
    tell(", ");
    if (s16(getProp(g.PRSI, P.SIZE)) < s16(1)) {
      g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
      tell("slides off and lands at your feet.\n");
      return true;
    }
    tell("which explodes with a flabby ");
    (await ITALICIZE("pop"));
    printS(g.PERIOD);
    await DESTROY_MIRROR(obj);
    return true;
  } else if (x = inTable(g.PRSA, E_VERBS, ENTER_VERBS)) {
    tell("Wrong fantasy.\n");
    return true;
  } else {
    return false;
  }
}

