async function START_MIRROR() {
  let len = 0, obj = 0, x = 0;
  if (g.LIT$ == 0) {
    tell(S(g.TAB), "Moments later, you hear a flabby ");
    (await ITALICIZE("pop"));
    tell(S(g.PERIOD));
    return true;
  }
  x = await PLAIN_ROOM$();
  if (!(x == 0) || (g.HERE == ON_BRIDGE || g.HERE == APLANE || g.HERE == IN_SKY || g.HERE == IN_SPLENDOR)) {
    await SAY_BUBBLE();
    tell(", but ");
    if (!(x == 0)) {
      setFlag(CORBIES, SEEN);
      tell("a corbie instantly swoops down to pop it.\n");
      return true;
    } else if (g.HERE == ON_BRIDGE) {
      tell("river mist instantly dissolves it.\n");
      return true;
    } else if (g.HERE == APLANE || g.HERE == IN_SPLENDOR) {
      tell("it");
      printS(" disappears in a spectral flash");
      tell(S(g.PERIOD));
      return true;
    }
    tell("upper air currents soon blow it out of sight.\n");
    return true;
  }
  len = get(MIRROR_LIST, 0);
  loop1: for (;;) {
    obj = get(MIRROR_LIST, len);
    x = loc(obj);
    if (x == 0) {
      break loop1;
    } else if (x == g.HERE) {
      await DESTROY_MIRROR(obj);
      await SAY_BUBBLE();
      tell(" and bounces into the other bubble hovering nearby. Both disappear with a flabby ");
      (await ITALICIZE("pop"));
      tell(S(g.PERIOD));
      return true;
    } else if (--len < 1) {
      await SAY_BUBBLE();
      tell(", but it pops almost immediately.\n");
      break loop1;
    }
  }
  await SAY_BUBBLE();
  tell("! You watch as it flattens into a perfectly circular mirror, rotating more and more slowly until it faces ");
  printB(get(DIR_NAMES, await CREATE_MIRROR$(obj)));
  tell(S(g.PERIOD));
  if (loc(URGRUE) == g.HERE) {
    tell(S(g.TAB), "\"How droll,\" remarks ");
    await THE_PRINT(URGRUE);
    tell(S(g.PERIOD));
  }
  if (eq(getProp(g.HERE, P.MIRROR_OBJ), NO_MIRROR)) {
    putProp(g.HERE, P.MIRROR_OBJ, obj);
    await REFLECTIONS();
  }
  return true;
}

async function SAY_BUBBLE() {
  tell(S(g.TAB), "A silvery bubble blows out of ");
  await THE_PRINT(CIRCLET);
  return true;
}

async function REFLECTIONS() {
  let alert = 0, popit = 0, rm = 0, tbl = 0, x = 0, obj = 0, angle = 0, dir = 0, xdir = 0;
  x = getb(GRUE_ROOMS, 0);
  loop1: for (;;) {
    rm = getb(GRUE_ROOMS, x);
    if (g.HERE == rm) {
      ++alert;
    }
    clearFlag(rm, LIGHTED);
    putProp(rm, P.BEAM_DIR, NO_MIRROR);
    if (--x < 1) {
      break loop1;
    }
  }
  if (hasFlag(NWALL, OPENED)) {
    setFlag(NE_CAVE, LIGHTED);
  }
  if (hasFlag(SWALL, OPENED)) {
    setFlag(SE_CAVE, LIGHTED);
  }
  obj = getProp(SE_CAVE, P.MIRROR_OBJ);
  if (obj == false || obj == NO_MIRROR) {
  } else if (hasFlag(SWALL, OPENED) && eq(getProp(obj, P.MIRROR_DIR), I_SOUTH)) {
    putProp(SE_CAVE, P.BEAM_DIR, I_SE);
    setFlag(SE_CAVE, LIGHTED);
    rm = SE_CAVE;
    dir = I_SW;
    loop2: for (;;) {
      tbl = getProp(rm, getb(PDIR_LIST, dir));
      if (tbl == 0) {
        break loop2;
      } else if (!(eq(get(tbl, XTYPE) & 65280, CONNECT, SCONNECT))) {
        break loop2;
      }
      xdir = dir + 4;
      if (s16(xdir) > s16(I_NW)) {
        xdir = xdir - 8;
      }
      rm = get(tbl, XROOM);
      obj = getProp(rm, P.MIRROR_OBJ);
      if (obj == 0) {
        break loop2;
      } else if (hasFlag(rm, LIGHTED)) {
        ++popit;
      }
      putProp(rm, P.BEAM_DIR, xdir);
      setFlag(rm, LIGHTED);
      if (obj == NO_MIRROR) {
        continue loop2;
      }
      angle = getProp(obj, P.MIRROR_DIR);
      if (angle == dir) {
        if (g.HERE == rm) {
          tell(S(g.TAB), "The back of ");
          await THE_PRINT(MIRROR0);
          tell(" is illuminated by a sunbeam.\n");
        }
        break loop2;
      } else if (angle == xdir) {
        if (g.HERE == rm) {
          tell(S(g.TAB), "A sunbeam is reflected ", wordText(get(DIR_NAMES, xdir)), S(g.PERIOD));
        }
        break loop2;
      }
      x = dir + 2;
      if (s16(x) > s16(I_NW)) {
        x = x - 8;
      }
      if (angle == x) {
        if (g.HERE == rm) {
          await MENTION_GLIMMER(xdir);
        }
        continue loop2;
      }
      x = dir - 2;
      if (s16(x) < s16(I_NORTH)) {
        x = x + 8;
      }
      if (angle == x) {
        if (g.HERE == rm) {
          await MENTION_GLIMMER(xdir);
        }
        continue loop2;
      }
      x = dir + 3;
      if (s16(x) > s16(I_NW)) {
        x = x - 8;
      }
      if (angle == x) {
        dir = dir + 2;
        if (s16(dir) > s16(I_NW)) {
          dir = dir - 8;
        }
        if (g.HERE == rm) {
          await SAY_BEAM(xdir, dir);
        }
        continue loop2;
      }
      x = dir + 5;
      if (s16(x) > s16(I_NW)) {
        x = x - 8;
      }
      if (angle == x) {
        dir = dir - 2;
        if (s16(dir) < s16(I_NORTH)) {
          dir = dir + 8;
        }
        if (g.HERE == rm) {
          await SAY_BEAM(xdir, dir);
        }
        continue loop2;
      }
      break loop2;
    }
  }
  if (!(alert == 0)) {
    await SAY_IF_HERE_LIT();
  }
  await REFRESH_MAP();
  if (!(popit == 0)) {
    putProp(getProp(SE_CAVE, P.MIRROR_OBJ), P.SIZE, 1);
  }
  return false;
}

