async function MAW_F(context = false) {
  let obj = 0, x = 0;
  if (!(context == 0)) {
    obj = g.PRSO;
    if (!(g.NOW_PRSI$ == 0)) {
      obj = g.PRSI;
    }
    if (context == M_BEG) {
      return await CANT_REACH_WHILE_IN$(obj, MAW);
    } else if (context == M_CONT) {
      if (loc(PLAYER) == MAW) {
        if (!(obj == TEAR)) {
          return false;
        } else if (hasFlag(obj, TAKEABLE)) {
          return false;
        } else if (x = inTable(g.PRSA, TOUCHVERBS, NTOUCHES)) {
          await TOUCH_TEAR();
          return M_FATAL;
        }
        return false;
      } else if (x = inTable(g.PRSA, TOUCHVERBS, NTOUCHES)) {
        (await YOUD_HAVE_TO("climb up into", MAW));
        return true;
      }
      return false;
    }
    return false;
  } else if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE)) {
    await SEE_MAW();
    return true;
  }
  return await HANDLE_MAW$();
}

