async function FARM_DOOR_F() {
  if (!(g.HERE == IN_FARM)) {
    return false;
  } else if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.OPEN, V.OPEN_WITH, V.HIT, V.MUNG, V.KICK) && (loc(TWISTER) == g.HERE) && !(hasFlag(g.PRSO, OPENED))) {
    tell("No use. The wind is holding ");
    await THE_PRINT();
    tell(" tightly shut.\n");
    return true;
  } else {
    return false;
  }
}

async function FARM_WINDOW_F() {
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.PUT, V.THROW, V.THROW_OVER, V.EMPTY_INTO)) {
      if (!(hasFlag(g.PRSI, OPENED))) {
        (await YOUD_HAVE_TO("open", g.PRSI));
        return true;
      }
      await VANISH();
      await CTHE_PRINT();
      tell(" falls ");
      if (g.HERE == g.FARM_ROOM || g.HERE == IN_FROON) {
        move(g.PRSO, IN_FARM);
        tell("in");
      } else {
        if (g.STORM_TIMER == 0) {
          move(g.PRSO, g.FARM_ROOM);
        }
        tell("out");
      }
      tell("side ");
      await THEI_PRINT();
      printS(" and disappears from view.\n");
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE)) {
    await CTHE_PRINT();
    tell(S(g.SIS));
    if (hasFlag(g.PRSO, OPENED)) {
      tell("wide open.\n");
      return true;
    }
    tell("closed.\n");
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.LOOK_OUTSIDE)) {
    if (g.HERE == g.FARM_ROOM || g.HERE == IN_FROON) {
      if (isVerb(V.LOOK_OUTSIDE)) {
        tell(S(g.ALREADY), "outside ");
        await THE_PRINT();
        tell(S(g.PERIOD));
        return true;
      }
      await CANT_SEE_MUCH();
      return true;
    } else if (!(loc(TWISTER))) {
      tell("It seems to be getting darker.\n");
      return true;
    }
    tell("Whirling clouds of dust obscure the view.\n");
    return true;
  } else if (isVerb(V.HIT, V.MUNG, V.KICK)) {
    await WASTE_OF_TIME();
    return true;
  } else if (isVerb(V.LEAP, V.ENTER, V.THROUGH, V.CLIMB_OVER, V.ESCAPE, V.DIVE)) {
    if (!(hasFlag(g.PRSO, OPENED))) {
      (await YOUD_HAVE_TO("open"));
      return true;
    } else if (g.HERE == g.FARM_ROOM || g.HERE == IN_FROON) {
      await WINDOW_SQUEEZE(IN_FARM);
      return true;
    } else if (!(hasFlag(FARMHOUSE, SEEN))) {
      await WINDOW_SQUEEZE(get(getProp(IN_FARM, P.NORTH), XROOM));
      return true;
    }
    tell("You leap recklessly out the open ", D(g.PRSO), " into a maelstrom of wind and dust, then plummet to a painful death");
    await JIGS_UP();
    return true;
  } else {
    return false;
  }
}

