async function HANDLE_SCARES$(obj) {
  let s3 = 0, wrd = 0, x = 0;
  let $1, $2;
  if (obj == SCARE3) {
    ++s3;
  }
  wrd = W.GRAY;
  if (hasFlag(g.HERE, SEEN) && hasFlag(obj, SEEN)) {
    wrd = get(getPropAddr(obj, P.ADJECTIVE), 0);
  }
  if (hasFlag(g.HERE, SEEN) && (await ADJ_USED$(W.GRAY, W.GREY))) {
    await NOTE_COLOR(obj);
    return M_FATAL;
  }
  if ((await NOUN_USED$(W.RAGS, W.CLOTH)) || (await ADJ_USED$(wrd, W.GRAY, W.GREY))) {
    if (!(g.NOW_PRSI$ == 0)) {
      if (x = inTable(g.PRSA, PUTVERBS, NUMPUTS)) {
        await WASTE_OF_TIME();
        return true;
      }
      return false;
    } else if (isVerb(V.EXAMINE, V.LOOK_ON, V.WEAR)) {
      if (!(hasFlag(obj, SEEN)) && hasFlag(g.HERE, SEEN)) {
        wrd = await RAG_COLOR_WORD$(obj);
      }
      tell(S(g.XTHE), wordText(wrd), " rags on ");
      await THE_PRINT();
      tell(" are tattered and useless.\n");
      return true;
    } else if (isVerb(V.SEARCH, V.LOOK_INSIDE, V.LOOK_UNDER)) {
      tell("You find nothing ");
      $1 = await PICK_NEXT(YAWNS);
      tell(S($1));
      tell(S(g.PERIOD));
      return true;
    } else if (x = inTable(g.PRSA, MOVEVERBS, NMVERBS)) {
      tell("Your grasp only shreds the rags worse than before.\n");
      return true;
    }
    return false;
  } else if (await NOUN_USED$(W.CORN, W.PATCH, W.HUSKS)) {
    if (!(g.NOW_PRSI$ == 0)) {
      if (x = inTable(g.PRSA, PUTVERBS, NUMPUTS)) {
        await PERFORM(V.DROP, g.PRSO);
        return true;
      }
      return false;
    } else if (isVerb(V.TAKE)) {
      if (g.HERE == g.FARM_ROOM) {
        tell("Whoever owns the corn might not like that.\n");
        return true;
      }
      tell("There's none left worth taking.\n");
      return true;
    } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
      tell("The corn around ");
      await THE_PRINT();
      tell(S(g.SIS));
      if (!(s3 == 0)) {
        tell("almost ready for harvest.\n");
        return true;
      }
      tell("dead; only withered husks remain.\n");
      return true;
    } else if (isVerb(V.LOOK_INSIDE, V.LOOK_UNDER, V.SEARCH)) {
      await ASIDE_FROM(g.PRSO);
      tell("nothing ");
      $2 = await PICK_NEXT(YAWNS);
      tell(S($2));
      tell(" in the corn.\n");
      return true;
    } else if (isVerb(V.EAT, V.TASTE)) {
      if (!(s3 == 0)) {
        tell("It's not quite ripe enough.\n");
        return true;
      }
      tell(S(g.NOTHING), "left to eat.\n");
      return true;
    } else if (isVerb(V.SMELL)) {
      tell("The corn smells ");
      if (!(s3 == 0)) {
        tell("almost ripe.\n");
        return true;
      }
      tell("rotten.\n");
      return true;
    } else if (isVerb(V.DRINK)) {
      await IMPOSSIBLE();
      return true;
    } else if (x = inTable(g.PRSA, E_VERBS, ENTER_VERBS)) {
      if (!(s3 == 0)) {
        tell("Thick husks block your path.\n");
        return true;
      }
      tell("Dead husks crunch underfoot.\n");
      return true;
    } else if (x = inTable(g.PRSA, X_VERBS, EXIT_VERBS)) {
      tell("Which way?\n");
      return true;
    } else if (x = inTable(g.PRSA, TOUCHVERBS, NTOUCHES)) {
      await WASTE_OF_TIME();
      return true;
    }
    return false;
  } else if (!(g.NOW_PRSI$ == 0)) {
    if (x = inTable(g.PRSA, PUTVERBS, NUMPUTS)) {
      await PRSO_SLIDES_OFF_PRSI();
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
    if (!(hasFlag(obj, SEEN)) && hasFlag(g.HERE, SEEN)) {
      wrd = await RAG_COLOR_WORD$(obj);
    }
    tell("Considering the stormy climate hereabouts, it's remarkable that this ", D(g.PRSO), " is still standing. Threadbare ", wordText(wrd), " rags hang from the wooden limbs, flapping");
    printS(" in the steady wind.\n");
    return true;
  } else if (isVerb(V.LISTEN)) {
    tell("Its limp rags flap");
    printS(" in the steady wind.\n");
    return true;
  } else if (x = inTable(g.PRSA, MOVEVERBS, NMVERBS)) {
    await ROOTED(obj);
    return true;
  } else {
    return false;
  }
}

async function ROOTED(obj) {
  await CTHE_PRINT(obj);
  tell(" is firmly rooted in the ground.\n");
  return true;
}

async function RAG_COLOR_WORD$(obj) {
  let wrd = 0, bad = 0;
  if (hasFlag(obj, SEEN)) {
    return get(getPropAddr(obj, P.ADJECTIVE), 0);
  }
  wrd = await SET_RAG_COLOR(obj);
  if (obj == SCARE3) {
    g.SCARES_SEEN = 3;
  } else if (!(++g.SCARES_SEEN > 1)) {
    return wrd;
  }
  if (hasFlag(FARMHOUSE, NODESC) && hasFlag(FARM, NODESC)) {
    await QUEUE(I_HOUSEFALL.id);
  }
  if (!(hasFlag(SCARE1, SEEN))) {
    await SET_RAG_COLOR(SCARE1);
  }
  if (!(hasFlag(SCARE2, SEEN))) {
    await SET_RAG_COLOR(SCARE2);
  }
  if (!(hasFlag(SCARE3, SEEN))) {
    bad = await SET_RAG_COLOR(SCARE3);
  } else {
    bad = get(getPropAddr(SCARE3, P.ADJECTIVE), 0);
  }
  g.BADKEY = KEY1;
  if (bad == W.MAUVE) {
    g.BADKEY = KEY2;
  } else if (bad == W.LAVENDER) {
    g.BADKEY = KEY3;
  }
  return wrd;
}

async function SET_RAG_COLOR(obj) {
  let wrd = 0;
  setFlag(obj, SEEN);
  wrd = await PICK_ONE(SCARE_COLORS);
  put(getPropAddr(obj, P.ADJECTIVE), 0, wrd);
  return wrd;
}

