async function HANDLE_KEYS$(obj) {
  let word = 0, k1 = 0, k2 = 0, k3 = 0;
  word = get(getPropAddr(obj, P.ADJECTIVE), 0);
  if (!(await SEE_COLOR$())) {
    word = W.GRAY;
  }
  if (await NOUN_USED$(W.KEYS)) {
    k1 = await VISIBLE$(KEY1);
    k2 = await VISIBLE$(KEY2);
    k3 = await VISIBLE$(KEY3);
    if (((obj == KEY1) && (k2 == 0) && (k3 == 0)) || ((obj == KEY2) && (k1 == 0) && (k3 == 0)) || ((obj == KEY3) && (k2 == 0) && (k1 == 0))) {
      await ONLY_ONE();
      return M_FATAL;
    } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
      tell("There are three keys, colored mauve, puce and lavender.\n");
      return true;
    }
  }
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.OPEN, V.UNLOCK)) {
      tell("Forget it. That phoney ");
      await DPRINT(g.PRSI);
      tell(" couldn't open anything.\n");
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON, V.READ)) {
    if (!(isVerb(V.READ))) {
      tell("This is actually a cheap piece of styrofoam, cut into the shape of a giant key, spray painted ", wordText(word), " and sprinkled with bits of glitter. ");
    }
    tell("The words ");
    (await ITALICIZE("City of Froon"));
    tell(" are scrawled in crayon across the front.\n");
    return true;
  } else if (isVerb(V.SMELL)) {
    tell("It smells like ", wordText(word), " paint.\n");
    return true;
  } else if (hasFlag(g.PRSO, TOUCHED)) {
    return false;
  } else if (isVerb(V.POINT)) {
    await AWARD_KEY(g.PRSO);
    return true;
  } else if (isVerb(V.TAKE)) {
    if (!(await ITAKE())) {
      return true;
    }
    tell("You ceremoniously lift ");
    await THE_PRINT();
    await OUT_OF_LOC(JBOX);
    tell(S(g.PERIOD));
    await EXIT_FROON(g.PRSO);
    return true;
  } else {
    return false;
  }
}

async function AWARD_KEY(obj) {
  setFlag(obj, TOUCHED);
  move(obj, PLAYER);
  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
  g.P_IT_OBJECT = obj;
  tell("With a gracious bow, ");
  await THE_PRINT(MAYOR);
  tell(" sets ");
  await THE_PRINT(obj);
  tell(" onto your outstretched palm.\n");
  await EXIT_FROON(obj);
  return true;
}

async function EXIT_FROON(obj) {
  let wrd = 0, s1 = 0, s2 = 0, s3 = 0;
  if (g.BADKEY == 0) {
    wrd = get(getPropAddr(obj, P.ADJECTIVE), 0);
    s1 = get(getPropAddr(SCARE1, P.ADJECTIVE), 0);
    s2 = get(getPropAddr(SCARE2, P.ADJECTIVE), 0);
    s3 = get(getPropAddr(SCARE3, P.ADJECTIVE), 0);
    if (!(hasFlag(SCARE3, SEEN))) {
      loop1: for (;;) {
        s3 = await PICK_ONE(SCARE_COLORS);
        if (s3 == wrd || s3 == s2 || s3 == s1) {
          continue loop1;
        }
        setFlag(SCARE3, SEEN);
        put(getPropAddr(SCARE3, P.ADJECTIVE), 0, s3);
        break loop1;
      }
    }
    if (!(hasFlag(SCARE2, SEEN))) {
      loop2: for (;;) {
        s2 = await PICK_ONE(SCARE_COLORS);
        if (s2 == s3 || s2 == s1) {
          continue loop2;
        }
        setFlag(SCARE2, SEEN);
        put(getPropAddr(SCARE2, P.ADJECTIVE), 0, s2);
        break loop2;
      }
    }
    if (!(hasFlag(SCARE1, SEEN))) {
      loop3: for (;;) {
        s1 = await PICK_ONE(SCARE_COLORS);
        if (s1 == s3 || s1 == s2) {
          continue loop3;
        }
        setFlag(SCARE1, SEEN);
        put(getPropAddr(SCARE1, P.ADJECTIVE), 0, s1);
        break loop3;
      }
    }
  }
  await DEQUEUE(I_FROON.id);
  await QUEUE(I_CORBIES.id);
  remove(FARM);
  await REPLACE_GLOBAL$(g.FARM_ROOM, FARM_DOOR, NULL);
  await REPLACE_GLOBAL$(g.FARM_ROOM, FARM_WINDOW, NULL);
  (await NEW_EXIT$(g.FARM_ROOM, P.SOUTH, SORRY_EXIT, "The ground is a bit too rough that way."));
  await NEW_EXIT$(g.FARM_ROOM, P.IN, NO_EXIT, 0, 0);
  tell("  \"An excellent choice,\" remarks ");
  await THE_PRINT(MAYOR);
  tell(". \"Bye!\"\n");
  await REGAIN_SENSES();
  await GOTO(g.FARM_ROOM);
  return true;
}

