async function GDIAL_F() {
  let x = 0;
  if ((await NOUN_USED$(W.PAINTINGS, W.PICTURES)) || (await ADJ_USED$(W.SIX))) {
    if (!(g.NOW_PRSI$ == 0)) {
      if (isVerb(V.TURN_TO, V.POINT_AT, V.PUSH_TO)) {
        await HOW_TO_CLICK();
        return true;
      }
    } else if (isVerb(V.EXAMINE, V.LOOK_ON, V.READ)) {
      tell(S(g.YOU_SEE), "a circle of ");
      printS("six little pictures, cunningly painted: an eye, an ear, a nose, a mouth, a hand and a clock");
      tell(", with a dial in the center.\n");
      return true;
    } else if (x = inTable(g.PRSA, MOVEVERBS, NMVERBS)) {
      await IMPOSSIBLE();
      return true;
    }
  }
  if (!(g.NOW_PRSI$ == 0)) {
    if (x = inTable(g.PRSA, PUTVERBS, NUMPUTS)) {
      await IMPOSSIBLE();
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
    await CTHE_PRINT();
    tell(S(g.SON));
    await THE_PRINT(GURDY);
    tell(" is encircled by ");
    printS("six little pictures, cunningly painted: an eye, an ear, a nose, a mouth, a hand and a clock");
    tell(". At the moment, the dial points to ");
    await THE_PRINT(get(PICT_LIST, g.DPOINTER));
    tell(S(g.PERIOD));
    return true;
  } else if (isVerb(V.TURN_TO, V.POINT_AT, V.PUSH_TO)) {
    if (g.PRSI == LEFT) {
      if (--g.DPOINTER < 0) {
        g.DPOINTER = 5;
      }
      (await CLICK_DIAL("left"));
      return true;
    } else if (g.PRSI == RIGHT) {
      if (++g.DPOINTER > 5) {
        g.DPOINTER = 0;
      }
      (await CLICK_DIAL("right"));
      return true;
    } else if (g.PRSI == INTDIR) {
      await CTHE_PRINT();
      tell(" only turns left or right.\n");
      return true;
    }
    await TURN_DIAL();
    return true;
  } else if (isVerb(V.SPIN, V.ADJUST, V.WIND, V.TOUCH)) {
    loop1: for (;;) {
      x = random(6);
      --x;
      if (x == g.DPOINTER) {
        continue loop1;
      }
      break loop1;
    }
    g.DPOINTER = x;
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
    await PRSO_FIDDLE();
    return true;
  } else if (x = inTable(g.PRSA, MOVEVERBS, NMVERBS)) {
    await FIRMLY_ATTACHED(g.PRSO, GURDY);
    return true;
  } else {
    return false;
  }
}

async function CLICK_DIAL(str = false) {
  g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
  (await ITALICIZE("Click"));
  tell(". You turn ");
  await THE_PRINT(GDIAL);
  if (!(str == 0)) {
    tell(" once to the ", S(str), ". It now ");
  } else {
    tell(" until it ");
  }
  tell("points to ");
  await THE_PRINT(get(PICT_LIST, g.DPOINTER));
  tell(S(g.PERIOD));
  if (hasFlag(GURDY, OPENED)) {
    printS(g.TAB);
    await MENTION_PUFF();
    printS(g.PERIOD);
  }
  return true;
}

async function TURN_DIAL() {
  let x = 0;
  if (g.PRSI == g.PRSO) {
    await IMPOSSIBLE();
    return true;
  } else if (x = inTable(g.PRSI, PICT_LIST, 6)) {
    x = getProp(g.PRSI, P.DNUM);
    if (x == g.DPOINTER) {
      await CTHE_PRINT(GDIAL);
      tell(" already points to ");
      await THEI_PRINT();
      tell(S(g.PERIOD));
      return true;
    }
    g.DPOINTER = x;
    await CLICK_DIAL();
    return true;
  } else if (g.PRSI == INTNUM) {
    if (s16(g.P_NUMBER) < s16(1)) {
      await HOW_TO_CLICK();
      return true;
    } else if (s16(g.P_NUMBER) > s16(6)) {
      tell("There are only six ", wordText(W.PAINTINGS), S(g.SON));
      await THE_PRINT(GURDY);
      tell(S(g.PERIOD));
      return true;
    }
    g.DPOINTER = g.P_NUMBER - 1;
    await CLICK_DIAL();
    return true;
  }
  await CTHE_PRINT(GDIAL);
  tell(S(g.SON));
  await THE_PRINT(GURDY);
  printS(" won't turn that way");
  printS(g.PERIOD);
  return true;
}

async function HOW_TO_CLICK() {
  await PCLEAR();
  await NYMPH_APPEARS();
  tell("You must specify one of the six paintings; for example, TURN THE DIAL TO THE PAINTING OF THE EAR or POINT ARROW AT MOUTH");
  printS(". Bye!\"\n  She disappears with a wink.\n");
  return true;
}

