async function ROSE_F() {
  let nodroop = 0, wrd = 0;
  if (hasFlag(g.HERE, INDOORS) || (g.HERE == IN_GARDEN || g.HERE == APLANE || g.HERE == IN_FROON || g.HERE == IN_SPLENDOR)) {
    ++nodroop;
  }
  if (!(g.NOW_PRSI$ == 0)) {
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON)) {
    await CTHE_PRINT();
    tell("'s delicate stem ");
    if (!(nodroop == 0)) {
      tell("is standing straight and tall.\n");
      return true;
    } else if (await PLAIN_ROOM$()) {
      tell("blows wildly back and forth in the stormy winds.\n");
      return true;
    }
    setFlag(BREEZE, SEEN);
    tell("is tilted to the ", wordText(get(DIR_NAMES, g.WINDIR)), S(g.PERIOD));
    if (!(hasFlag(g.PRSO, IDENTIFIED))) {
      setFlag(g.PRSO, IDENTIFIED);
      tell(S(g.TAB));
      await REFER_TO_PACKAGE();
    }
    return true;
  } else if (isVerb(V.TAKE, V.PICK, V.UPROOT, V.PULL, V.LOOSEN, V.RAISE) && !(hasFlag(g.PRSO, TOUCHED))) {
    await PICK_ROSE();
    return true;
  } else if (isVerb(V.TURN_TO, V.POINT_AT, V.PUSH_TO)) {
    if (!(loc(g.PRSO) == PLAYER)) {
      (await YOUD_HAVE_TO("be holding"));
      return true;
    } else if (g.PRSI == LEFT) {
      if (--g.WINDIR < I_NORTH) {
        g.WINDIR = I_NW;
      }
      wrd = W.LEFT;
    } else if (g.PRSI == RIGHT) {
      if (++g.WINDIR > I_NW) {
        g.WINDIR = I_NORTH;
      }
      wrd = W.RIGHT;
    } else {
      if (g.PRSI == INTDIR) {
        if ((s16(g.P_DIRECTION) > s16(P.NW - 1)) && (s16(g.P_DIRECTION) < s16(P.NORTH + 1))) {
          g.WINDIR = 0 - (g.P_DIRECTION - P.NORTH);
          wrd = get(DIR_NAMES, g.WINDIR);
        } else if (g.P_DIRECTION == P.UP || g.P_DIRECTION == P.DOWN) {
          await CTHE_PRINT();
          if (await PLAIN_ROOM$()) {
            tell(" blows back and forth.\n");
            return true;
          } else if (!(nodroop == 0)) {
            tell(" springs up again.\n");
            return true;
          }
          tell(" droops back to the ", wordText(get(DIR_NAMES, g.WINDIR)), S(g.PERIOD));
          return true;
        }
      } else {
        tell(S(g.CANT), wordText(g.P_PRSA_WORD), C(SP));
        await THE_PRINT();
        tell(" that way.\n");
        return true;
      }
    }
    tell(S(g.CYOU), wordText(g.P_PRSA_WORD), C(SP));
    await THE_PRINT();
    tell("'s stem to the ", wordText(wrd));
    if (!(nodroop == 0)) {
      tell(", but it springs upright again.\n");
      return true;
    } else if (await PLAIN_ROOM$()) {
      tell(", but the wind blows it wildly around.\n");
      return true;
    }
    tell(S(g.PERIOD));
    await NEW_WINDIR$();
    return true;
  } else if (isVerb(V.SPIN, V.ADJUST, V.WIND, V.TOUCH)) {
    await PRSO_FIDDLE();
    await NEW_WINDIR$(await NEXT_WINDIR$());
    return true;
  } else if (isVerb(V.EAT, V.TASTE)) {
    tell("You hurt your mouth on a thorn. Ouch!\n");
    await UPDATE_STAT(-2);
    return true;
  } else if (isVerb(V.DRINK, V.DRINK_FROM)) {
    await IMPOSSIBLE();
    return true;
  } else if (isVerb(V.SMELL)) {
    await CTHE_PRINT();
    tell("'s scent is unusually delicate.\n");
    return true;
  } else if (isVerb(V.WHAT)) {
    await REFER_TO_PACKAGE();
    return M_FATAL;
  } else {
    return false;
  }
}

