async function ROLL_ONION(dir) {
  let x = 0, ohere = 0;
  if (await SPARK$(false, ONION)) {
    tell(S(g.TAB));
  }
  if (((g.HERE == NE_WALL) && (dir == P.SE || dir == P.IN) && hasFlag(NE_WALL, OPENED)) || ((g.HERE == SE_WALL) && (dir == P.SW || dir == P.IN) && hasFlag(SE_WALL, OPENED))) {
    await CTHE_PRINT(ONION);
    tell(" won't fit through the ", wordText(W.OPENING), S(g.PERIOD));
    return true;
  } else if (g.HERE == IN_KITCHEN) {
    if (dir == P.DOWN || dir == P.IN) {
      tell(S(g.XTHE));
      if (hasFlag(CELLAR_DOOR, MUNGED)) {
        tell("hole in the wall");
      } else {
        tell(D(CELLAR_DOOR));
      }
      tell(" isn't wide enough to fit ");
      await THE_PRINT(ONION);
      if (!(hasFlag(CELLAR_DOOR, OPENED))) {
        tell(". Besides, it's closed");
      }
      printS(g.PERIOD);
      return true;
    } else if ((dir == P.EAST || dir == P.OUT) && !(hasFlag(ONION, SEEN))) {
      tell("As you roll ");
      await THE_PRINT(ONION);
      tell(" towards the exit, ");
      await THE_PRINT(COOK);
      tell(" jumps into your path. \"");
      if (!(hasFlag(ONION, TOUCHED))) {
        tell("This ain't no free soup kitchen");
        printS(",\" he barks, shoving the ungainly vegetable back into place.\n");
        tell(S(g.TAB));
        await COOK_MENTIONS_ONION();
        return true;
      } else if (!(hasFlag(BOTTLE, IDENTIFIED))) {
        tell("Leave it alone");
      } else {
        setFlag(COOK, SEEN);
        tell("No bottle, no onion");
      }
      printS(",\" he barks, shoving the ungainly vegetable back into place.\n");
      return true;
    }
  }
  ohere = g.HERE;
  await DO_WALK(dir);
  if (!(g.HERE == ohere || g.HERE == DEATH)) {
    move(ONION, g.HERE);
    g.P_IT_OBJECT = ONION;
    g.NEW_DBOX = g.NEW_DBOX | SHOWING_ROOM;
    tell(S(g.TAB));
    await CTHE_PRINT(ONION);
    tell(" rolls to a stop.\n");
  }
  return false;
}

