async function HANDLE_CASE$(obj, top, context) {
  let any = 0, anytop = 0, x = 0;
  if (!(context == 0)) {
    if (context == M_CONT) {
      if (x = inTable(g.PRSA, TOUCHVERBS, NTOUCHES)) {
        await CANT_REACH_IN(obj);
        return true;
      } else if (isVerb(V.SMELL, V.TASTE, V.EAT)) {
        (await YOUD_HAVE_TO("open", obj));
        return true;
      }
      return false;
    }
    return false;
  } else if (await NOUN_USED$(W.SHELVES, W.SHELF)) {
    if (x = inTable(g.PRSA, TOUCHVERBS, NTOUCHES)) {
      await CANT_REACH_IN(obj);
      return true;
    } else if (!(g.NOW_PRSI$ == 0)) {
      return false;
    } else if (isVerb(V.LOOK_ON, V.EXAMINE)) {
      await LOOK_IN_CASE(obj);
      return true;
    }
  }
  anytop = await SEE_ANYTHING_IN$(top);
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.PUT, V.PUT_UNDER, V.PUT_BEHIND, V.EMPTY_INTO)) {
      await ITS_CLOSED(g.PRSI);
      return true;
    } else if (isVerb(V.PUT_ON)) {
      g.NEW_DBOX = g.NEW_DBOX | SHOWING_ALL;
      move(g.PRSO, top);
      tell("You put ");
      await THE_PRINT();
      tell(S(g.SON));
      await THE_PRINT(obj);
      tell(S(g.PERIOD));
      if (!(hasFlag(g.PRSO, IDENTIFIED))) {
        tell(S(g.TAB));
        await ASK_OWOMAN_ABOUT(g.PRSO);
      }
      return true;
    } else if (isVerb(V.THROW, V.THROW_OVER)) {
      await MUNG_CASE_WITH(g.PRSO);
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE)) {
    tell("The interior of the glass ", D(g.PRSO), " is lined with ");
    if (await SEE_ANYTHING_IN$()) {
      ++any;
      tell("shelves, upon which you see ");
      await CONTENTS();
      g.P_IT_OBJECT = g.PRSO;
    } else {
      tell("empty shelves");
    }
    if (!(anytop == 0)) {
      tell(". ");
      if (!(any == 0)) {
        tell("You also");
      } else {
        tell("On top of the case you");
      }
      tell(" see ");
      await CONTENTS(top);
      g.P_IT_OBJECT = g.PRSO;
      if (!(any == 0)) {
        tell(" on top of the case");
      }
    }
    printS(g.PERIOD);
    return true;
  } else if (isVerb(V.LOOK_ON)) {
    tell(S(g.YOU_SEE));
    await CONTENTS(top);
    g.P_IT_OBJECT = g.PRSO;
    tell(S(g.SON));
    await THE_PRINT();
    tell(S(g.PERIOD));
    return true;
  } else if (isVerb(V.SEARCH, V.LOOK_INSIDE, V.LOOK_UNDER, V.LOOK_BEHIND)) {
    await LOOK_IN_CASE(g.PRSO);
    return true;
  } else if (isVerb(V.OPEN, V.REACH_IN, V.EMPTY)) {
    if (!(anytop == 0) && isVerb(V.EMPTY)) {
      g.PRSO = top;
      await V_EMPTY();
      g.PRSO = obj;
      return true;
    }
    tell(S(g.CTHELADY), " slaps ", D(HANDS), " away. \"Ask.\"\n");
    return true;
  } else if (isVerb(V.HIT, V.MUNG, V.OPEN_WITH)) {
    await MUNG_CASE_WITH(g.PRSI);
    return true;
  } else if (isVerb(V.KICK)) {
    await MUNG_CASE_WITH(FEET);
    return true;
  } else if (isVerb(V.CLOSE)) {
    (await ITS_ALREADY("closed"));
    return true;
  } else if (x = inTable(g.PRSA, E_VERBS, CLIMB_ON_VERBS)) {
    await MUNG_CASE_WITH(HANDS);
    return true;
  } else if (x = inTable(g.PRSA, X_VERBS, CLIMB_DOWN_VERBS)) {
    await NOT_ON();
    return true;
  } else {
    return false;
  }
}

async function LOOK_IN_CASE(obj) {
  if (!(await SEE_ANYTHING_IN$(obj))) {
    tell("The shelves in ");
    await THE_PRINT(obj);
    tell(" are empty.\n");
    return true;
  }
  tell("Peering under the glass", S(g.LYOU_SEE));
  await CONTENTS(obj);
  g.P_IT_OBJECT = obj;
  printS(g.PERIOD);
  return true;
}

