async function MUNG_CASE_WITH(obj) {
  setFlag(OWOMAN, SEEN);
  if (obj == HANDS || obj == FEET) {
    tell("\"Stop that");
  } else {
    tell("\"Put th");
    if (hasFlag(obj, PLURAL)) {
      tell("ose ");
    } else {
      tell("at ");
    }
    await DPRINT(obj);
    tell(" down");
  }
  tell(",\" demands ");
  await THE_PRINT(OWOMAN);
  tell(S(g.PERIOD));
  return true;
}

