async function HANDLE_ARMOR$(obj) {
  let w_ = 0, c_ = 0, efx = 0, x = 0;
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.PUT, V.EMPTY_INTO, V.PUT_UNDER, V.PUT_BEHIND)) {
      await CTHEI_PRINT();
      tell(" has no pockets in which to ", wordText(g.P_PRSA_WORD), " things.\n");
      return true;
    } else if (isVerb(V.PUT_ON, V.THROW, V.THROW_OVER)) {
      await NO_GOOD_SURFACE();
      return true;
    }
    return false;
  }
  if ((loc(obj) == PLAYER) && hasFlag(obj, WORN)) {
    ++w_;
  }
  if (isVerb(V.REACH_IN, V.EMPTY, V.LOOK_INSIDE, V.SEARCH, V.LOOK_UNDER, V.LOOK_BEHIND, V.SHAKE)) {
    if (!(w_ == 0)) {
      tell("Except for ", D(ME), ", the ");
    } else {
      tell(S(g.XTHE));
    }
    await DPRINT(g.PRSO);
    tell(" is empty.\n");
    return true;
  } else if (isVerb(V.OPEN, V.OPEN_WITH, V.CLOSE)) {
    tell(S(g.DONT), "need to do that with this ", D(g.PRSO), S(g.PERIOD));
    return true;
  } else if (obj == CLOAK) {
    return false;
  }
  efx = getProp(obj, P.EFFECT);
  if ((loc(CLOAK) == PLAYER) && hasFlag(CLOAK, WORN)) {
    ++c_;
  }
  if (isVerb(V.WEAR, V.USE)) {
    if (!(w_ == 0)) {
      return false;
    } else if (x = first(PLAYER)) {
      loop1: for (;;) {
        if (!(x == CLOAK || x == HELM) && hasFlag(x, CLOTHING) && hasFlag(x, WORN) && getProp(x, P.EFFECT)) {
          break loop1;
        }
        if (!(x = next(x))) {
          break loop1;
        }
      }
    }
    if (!(x == 0)) {
      (await YOUD_HAVE_TO("take off", x));
      return true;
    } else if (!(loc(obj) == PLAYER)) {
      (await YOUD_HAVE_TO("pick up"));
      return true;
    }
    setFlag(g.PRSO, WORN);
    tell(S(g.CYOU));
    if (!(c_ == 0)) {
      tell("slip off your ");
      await DPRINT(CLOAK);
      tell(", ");
    }
    tell("put on ");
    await THE_PRINT();
    if (!(c_ == 0)) {
      tell(" and throw the cloak back over it");
    }
    await DO_WEAR(efx);
    return true;
  } else if (isVerb(V.TAKE_OFF)) {
    if (w_ == 0) {
      return false;
    }
    clearFlag(g.PRSO, WORN);
    tell(S(g.CYOU));
    if (!(c_ == 0)) {
      tell("remove your ");
      await DPRINT(CLOAK);
      tell(", ");
    }
    tell("take off ");
    await THE_PRINT();
    if (!(c_ == 0)) {
      tell(" and slip the cloak back on");
    }
    await DO_WEAR(0 - efx);
    return true;
  } else {
    return false;
  }
}

