async function GLASS_F() {
  let x = 0;
  if (await NOUN_USED$(W.SAND)) {
    if (isVerb(V.SHAKE)) {
    } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE, V.SEARCH)) {
      tell("The sand in ");
      await THE_PRINT();
      tell(S(g.SIS));
      if (!(g.GLASS_TOP == 0)) {
        tell("falling in a steady trickle.\n");
        return true;
      }
      tell("exceptionally fine.\n");
      return true;
    } else if (inTable(g.PRSA, TOUCHVERBS, NTOUCHES)) {
      tell(S(g.CANT), "reach the sand. ");
      await ITS_SEALED(GLASS);
      return true;
    }
  }
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.PUT, V.EMPTY_INTO)) {
      await ITS_SEALED(GLASS);
      return true;
    }
    return false;
  } else if (isVerb(V.OPEN, V.OPEN_WITH, V.REACH_IN, V.CLOSE)) {
    await ITS_SEALED(GLASS);
    return true;
  } else if (isVerb(V.SHAKE)) {
    if (!(loc(g.PRSO) == PLAYER)) {
      (await YOUD_HAVE_TO("be holding"));
      return true;
    }
    tell("You give the ");
    if (!(g.GLASS_TOP == 0)) {
      tell("trickling sand in the ");
    }
    tell(D(GLASS), " a vigorous shake.\n");
    if (g.GLASS_TOP == 0) {
      await QUEUE(I_GLASS.id);
      await ARCH_ON();
    }
    loop1: for (;;) {
      x = random(4);
      if (x == g.GLASS_TOP) {
        continue loop1;
      }
      break loop1;
    }
    g.GLASS_TOP = x;
    g.GLASS_BOT = 0 - (x - FULL);
    return true;
  } else if (isVerb(V.TURN, V.SPIN)) {
    if (isVerb(V.SPIN) || (g.PRSI == false || g.PRSI == HANDS)) {
      if (!(loc(g.PRSO) == PLAYER)) {
        (await YOUD_HAVE_TO("be holding"));
        return true;
      }
      tell("You turn over ");
      await THE_PRINT();
      tell(", and watch as the sand ");
      if (g.GLASS_TOP == 0) {
        g.GLASS_TOP = FULL;
        g.GLASS_BOT = 0;
        await QUEUE(I_GLASS.id);
        tell("begins to fall in a slow, steady trickle.\n");
        await ARCH_ON();
        return true;
      }
      tell("reverses ", D(INTDIR), " and resumes its steady trickle.\n");
      x = g.GLASS_TOP;
      g.GLASS_TOP = g.GLASS_BOT;
      g.GLASS_BOT = x;
      return true;
    }
    tell(S(g.DONT), "need ");
    await THEI_PRINT();
    tell(S(g.STO), wordText(g.P_PRSA_WORD), C(SP));
    await THE_PRINT();
    tell(S(g.PERIOD));
    return true;
  } else if (isVerb(V.EXAMINE, V.LOOK_INSIDE, V.SEARCH)) {
    tell("The miniature ", D(GLASS), " is wrought of brass and crystal");
    if (!(g.GLASS_TOP == 0)) {
      tell(". Fine, white sand is falling through it in a steady trickle.\n");
      return true;
    }
    tell(", and filled with fine, white sand.\n");
    return true;
  } else if (isVerb(V.LAMP_OFF) && (g.P_PRSA_WORD == W.STOP || g.P_PRSA_WORD == W.HALT)) {
    if (g.GLASS_TOP == 0) {
      tell("The sand in ");
      await THE_PRINT();
      tell(" isn't trickling", S(g.AT_MOMENT));
      return true;
    }
    tell("Patience. It'll stop eventually.\n");
    return true;
  } else {
    return false;
  }
}

