async function READ_SCROLL() {
  let syns = 0, tbl = 0, wrd = 0, stat = 0, x = 0;
  if (!(loc(g.PRSO) == PLAYER)) {
    tell("The writing on ");
    await THE_PRINT();
    tell(" is quite tiny. You'll have to pick it up to read it.\n");
    return true;
  }
  syns = getPropAddr(g.PRSO, P.SYNONYM);
  wrd = get(syns, 1);
  if (wrd == W.ZZZP) {
    tbl = await PICK_ONE(MAGIC_WORDS);
    put(tbl, 2, 1);
    wrd = get(tbl, 0);
    put(syns, 1, wrd);
    put(getPropAddr(g.PRSO, P.ADJECTIVE), 1, wrd);
    putProp(g.PRSO, P.NAME_TABLE, get(tbl, 1));
  }
  tell("The meaning of ");
  await THE_PRINT();
  tell(" is obscure. It seems to have something to do with ", S(getProp(g.PRSO, P.DNUM)), ". ");
  x = getProp(g.PRSO, P.READIQ);
  stat = get(g.STATS, INTELLIGENCE);
  if (!(s16(stat) < s16(x))) {
    printS("The word ");
    if (g.HOST == APPLE_2E || g.HOST == APPLE_2C || g.HOST == C128) {
      tell("\"");
    } else {
      highlight(H_ITALIC);
    }
    await PRINT_TABLE(getProp(g.PRSO, P.NAME_TABLE));
    if (g.HOST == APPLE_2E || g.HOST == APPLE_2C || g.HOST == C128) {
      tell("\"");
    }
    highlight(H_NORMAL);
    tell(S(g.SIS));
  } else if (g.VT220 == 0) {
    tell("Strange, flowing runes are ");
  } else {
    tell("The runes ");
    await RUNE(wrd);
    tell(" are ");
  }
  tell("inscribed across the top");
  if (s16(stat) < s16(x)) {
    tell("; you could probably understand them if you'd studied harder at school");
  }
  printS(g.PERIOD);
  return true;
}

async function RUNE(wrd) {
  let ptr = 0, len = 0, char = 0, x = 0;
  dirOut(D_TABLE_ON, g.AUX_TABLE);
  printB(wrd);
  dirOut(D_TABLE_OFF);
  len = get(g.AUX_TABLE, 0) + 1;
  ptr = 2;
  loop1: for (;;) {
    x = setFont(F_NEWFONT);
    char = getb(g.AUX_TABLE, ptr);
    if ((s16(char) < s16(97)) || (s16(char) > s16(122))) {
      x = setFont(F_DEFAULT);
    }
    printC(char);
    if (++ptr > len) {
      break loop1;
    }
  }
  x = setFont(F_DEFAULT);
  return false;
}

