async function NEXT_POTION$(rm = 0, fcn = 0) {
  let obj = 0, x = 0;
  obj = await PICK_ONE(POTION_LIST);
  if (hasFlag(obj, NODESC)) {
    clearFlag(obj, NODESC);
    x = await PICK_ONE(POTION_TABLES);
    putProp(obj, P.ACTION, get(x, 0));
    putProp(obj, P.SDESC, get(x, 1));
    x = get(x, 2);
    put(getPropAddr(obj, P.SYNONYM), 0, x);
    put(getPropAddr(obj, P.ADJECTIVE), 0, x);
    if (arguments.length > 0) {
      move(obj, rm);
    }
    if (arguments.length > 1) {
      putProp(obj, P.DESCFCN, fcn);
    }
    return obj;
  } else {
    return false;
  }
}

async function HANDLE_POTION$(int) {
  if (!(g.NOW_PRSI$ == 0)) {
    if (isVerb(V.POUR_FROM)) {
      printS("Wastrel.\n");
      return true;
    }
    return false;
  } else if (isVerb(V.EXAMINE, V.LOOK_ON, V.READ)) {
    setFlag(BPOTION, SEEN);
    tell("A legend on the potion says, \"Shake before using. Another fine product of the ");
    (await FROBOZZ("Potion"));
    tell(S(g.PERQ));
    return true;
  } else if (isVerb(V.LOOK_INSIDE, V.SEARCH)) {
    tell(S(g.XTHE), wordText(get(getPropAddr(g.PRSO, P.ADJECTIVE), 1)), " liquid ");
    if (hasFlag(g.PRSO, MUNGED)) {
      tell("swirls with potency.\n");
      return true;
    }
    tell("looks a bit flat.\n");
    return true;
  } else if (isVerb(V.OPEN, V.OPEN_WITH)) {
    tell(S(g.DONT), "need to. It'll open itself when you drink it.\n");
    return true;
  } else if (isVerb(V.POUR, V.EMPTY, V.EMPTY_INTO)) {
    printS("Wastrel.\n");
    return true;
  } else if (isVerb(V.CLOSE)) {
    (await ITS_ALREADY("closed"));
    return true;
  } else if (isVerb(V.SHAKE)) {
    if (!(loc(g.PRSO) == PLAYER)) {
      (await YOUD_HAVE_TO("be holding"));
      return true;
    }
    setFlag(g.PRSO, MUNGED);
    tell("You give the potion a vigorous shake.\n");
    return true;
  } else if (isVerb(V.DRINK, V.USE)) {
    if (!(loc(g.PRSO) == PLAYER)) {
      (await YOUD_HAVE_TO("be holding"));
      return true;
    } else if (hasFlag(g.PRSO, MUNGED) && !(hasFlag(g.PRSO, NEUTRALIZED))) {
      await QUEUE(int, 2);
    }
    await VANISH();
    tell("Gloop, gloop, gloop! You drain ");
    await THE_PRINT();
    tell(" to the last drop, and watch as the container melts into nothingness.\n");
    if (loc(OWOMAN) == g.HERE) {
      setFlag(OWOMAN, SEEN);
      tell("  \"");
      if (!(hasFlag(BPOTION, SEEN))) {
        tell("Should've read it first");
      } else if ((int == I_DEATH.id) && hasFlag(g.PRSO, MUNGED) && !(hasFlag(g.PRSO, NEUTRALIZED))) {
        tell("Nice knowing you");
      } else {
        tell("Cheers");
      }
      tell(",\" mutters ");
      await THE_PRINT(OWOMAN);
      tell(S(g.PERIOD));
    }
    return true;
  } else if (await FIRST_TAKE$()) {
    return true;
  } else if (isVerb(V.MUNG, V.CUT, V.HIT)) {
    tell("And risk breaking this expensive ");
    await DPRINT(g.PRSO);
    tell("? ");
    await WASTE_OF_TIME();
    return true;
  } else {
    return false;
  }
}

