async function READ_YES_LEXV() {
  let key = 0;
  copyTable(YES_LEXV, 0, YES_LEXV_LENGTH);
  putb(YES_LEXV, 0, 2);
  copyTable(YES_INBUF, 0, YES_INBUF_LENGTH);
  putb(YES_INBUF, 0, YES_INBUF_LENGTH - 2);
  for (;;) {
    setColor(g.INCOLOR, g.BGND);
    key = await read(YES_INBUF, YES_LEXV);
    if (key == EOL || key == LF) {
      setColor(g.FORE, g.BGND);
      return false;
    }
  }
}

async function YES_WORD$(word) {
  if (word == 0) {
    return false;
  } else if (word == W.Y || word == W.YES || word == W.YUP) {
    return true;
  } else if (word == W.OKAY || word == W.OK || word == W.SURE) {
    return true;
  } else {
    return false;
  }
}

async function NO_WORD$(word) {
  if (word == 0) {
    return false;
  } else if (word == W.N || word == W.NO || word == W.NOPE) {
    return true;
  } else if (word == W.NEGATIVE || word == W.NAY) {
    return true;
  } else {
    return false;
  }
}

async function YES$() {
  let word = 0, tbl = 0;
  setColor(g.FORE, g.BGND);
  crlf();
  loop1: for (;;) {
    tell("\n[Please type YES or NO.] >");
    await READ_YES_LEXV();
    if (getb(YES_LEXV, P_LEXWORDS) == 0) {
      continue loop1;
    }
    word = get(YES_LEXV, P_LEXSTART);
    if (word == 0) {
      continue loop1;
    } else if (await YES_WORD$(word)) {
      return true;
    } else if (await NO_WORD$(word)) {
      return false;
    }
  }
}

async function STARTUP() {
  let x = 0, tbl = 0, cnt = 0;
  copyTable(VOCAB, VOCAB2, getb(VOCAB, 0) + 2);
  await DEFAULT_SOFTS();
  tbl = get(MACHINE_COLORS, g.HOST);
  if (!(tbl == 0)) {
    tbl = get(tbl, 1);
    g.BGND = getb(tbl, 0);
    g.FORE = getb(tbl, 1);
    g.INCOLOR = getb(tbl, 2);
    g.GCOLOR = getb(tbl, 3);
  }
  if (g.HOST == DEC_20) {
    clearScreen(-1);
    tell("\nIs this a VT220?");
    if (!(await YES$())) {
      g.VT100 = true;
      await SETUP_APPLE_MODE();
    }
  }
  setColor(g.FORE, g.BGND);
  clearScreen(-1);
  crlf();
  printS("Copyright (C)1987 Infocom, Inc. All rights reserved.");
  crlf();
  printS("\nDo you want to ");
  tell("begin a new game, restore a saved game, or quit?\n\n");
  loop1: for (;;) {
    setColor(g.FORE, g.BGND);
    tell("[Type BEGIN, RESTORE or QUIT.] >");
    await READ_YES_LEXV();
    if (getb(YES_LEXV, P_LEXWORDS) == 0) {
      continue loop1;
    }
    x = get(YES_LEXV, P_LEXSTART);
    if (x == 0) {
      continue loop1;
    } else if (x == W.BEGIN || x == W.B || x == W.RESTART) {
      await PROLOGUE();
      clearScreen(-1);
      return true;
    } else if (x == W.RESTORE) {
      await V_RESTORE();
      crlf();
    } else if (x == W.Q || x == W.QUIT) {
      crlf();
      await quit();
      return false;
    }
  }
}

