async function SETUP_CHARACTER() {
  let last = 0, x = 0, stat = 0;
  putb(DBOX, 0, SP);
  copyTable(DBOX, DBOX + 1, -1551);
  loop1: for (;;) {
    setColor(g.FORE, g.BGND);
    clearScreen(-1);
    splitWindow(14);
    if (hasFlag(PLAYER, NAMED)) {
      await SHOW_RANK(g.WIDTH);
    }
    await TO_TOP_WINDOW();
    setColor(g.FORE, g.BGND);
    await CENTER(5, 15);
    tell("Character Setup");
    stat = 0;
    loop2: for (;;) {
      await SHOW_MENU_ITEM(stat);
      if (++stat > 4) {
        break loop2;
      }
    }
    await USE_ARROWS();
    printS("highlight your selection.\n\nType [RETURN] to continue. >");
    stat = last;
    loop3: for (;;) {
      await TO_TOP_WINDOW();
      await SHOW_MENU_ITEM(stat, 1);
      await TO_BOTTOM_WINDOW();
      x = await DO_INPUT();
      if (x == DOWN_ARROW || x == SP || x == UP_ARROW) {
        await TO_TOP_WINDOW();
        await SHOW_MENU_ITEM(stat);
        if (x == UP_ARROW) {
          if (--stat < 0) {
            stat = 4;
          }
          continue loop3;
        }
        if (++stat > 4) {
          stat = 0;
        }
        continue loop3;
      } else if (x == EOL || x == LF) {
        if (stat == 0) {
          await QUICK_SETUP();
          break loop3;
        } else if (stat == 1) {
          await PICK_A_CHAR();
          break loop3;
        } else if (stat == 2) {
          await ROLL_YOUR_OWN();
          break loop3;
        } else if (stat == 3) {
          await MANUAL();
          crlf();
          if (!(g.POTENTIAL == 0)) {
            tell("\nYour unused Potential has been evenly distributed.\n");
          }
          break loop3;
        }
        crlf();
        crlf();
        await V_QUIT();
        await TO_TOP_WINDOW();
        await SHOW_MENU_ITEM(stat);
        await USE_ARROWS();
        printS("highlight your selection.\n\nType [RETURN] to continue. >");
        stat = 0;
        continue loop3;
      }
      sound(2);
    }
    await TO_BOTTOM_WINDOW();
    crlf();
    if (stat == 0) {
      break loop1;
    }
    last = stat;
    printS("\nAre you sure ");
    tell("these are the attributes you want?");
    if (!(await YES$())) {
      continue loop1;
    }
    await GET_SEX();
    await GET_NAME();
    setFlag(PLAYER, NAMED);
    await SHOW_RANK(g.WIDTH);
    printS("\nAre you sure ");
    await PRINT_TABLE(CHARNAME);
    tell(" is the character you want?");
    if (await YES$()) {
      break loop1;
    }
  }
  g.SAY_STAT = true;
  copyTable(g.STATS, g.MAXSTATS, 16);
  if (!(stat == 0)) {
    printS("\nDo you want to ");
    tell("save this character before you proceed?");
    if (await YES$()) {
      putb(g.OOPS_INBUF, 1, 0);
      x = await save();
      if (x == 0) {
        (await FAILED("SAVE"));
      } else if (x == 1) {
        (await COMPLETED("SAVE"));
      } else {
        await INITVARS();
        return false;
      }
    }
  }
  g.CHECKSUM = 0;
  stat = ENDURANCE;
  loop4: for (;;) {
    g.CHECKSUM = g.CHECKSUM + get(g.STATS, stat);
    if (++stat > LUCK) {
      break loop4;
    }
  }
  if (s16(g.CHECKSUM) > s16(66)) {
    await CHEATER();
    return false;
  }
  tell("\nPress any key to begin the story. >");
  x = await readChar(1);
  return false;
}

