async function APPLE_BARS(y = 0, x = 0) {
  let stat = 0;
  if (!(arguments.length > 0)) {
    y = 4;
  }
  g.BARY = y;
  if (!(arguments.length > 1)) {
    x = div(g.WIDTH - 18, 2);
  }
  g.BARX = x;
  await TO_TOP_WINDOW();
  cursorSet(3, g.BARX - 1);
  highlight(H_INVERSE);
  printTable(DBOX, APPBOX, 8);
  cursorSet(g.BARY, g.BARX);
  printTable(BAR_LABELS, LABEL_WIDTH, ARMOR_CLASS);
  loop1: for (;;) {
    await BAR_NUMBER(stat, get(g.STATS, stat));
    if (++stat > LUCK) {
      break loop1;
    }
  }
  await TO_BOTTOM_WINDOW();
  return false;
}

async function PICK_A_CHAR() {
  let char = 0, lmargin = 0, nx = 0, ny = 0, ntbl = 0, x = 0;
  clearScreen(S_WINDOW);
  if (hasFlag(PLAYER, NAMED)) {
    await SHOW_RANK(g.WIDTH);
  }
  x = g.BARWIDTH;
  if (g.VT220 == 0) {
    x = APPBOX;
  }
  nx = div(g.WIDTH - (BARMAR + x), 2);
  lmargin = nx - 1;
  g.IN_DBOX = SHOWING_STATS;
  await TO_TOP_WINDOW();
  if (g.VT220 == 0) {
    setColor(g.FORE, g.BGND);
    await DO_CURSET(3, lmargin);
    highlight(H_INVERSE);
    printTable(DBOX, 9, 8);
  }
  loop1: for (;;) {
    await DO_CURSET(char + 4, nx);
    tell(S(get(CNAMES, char)));
    if (++char > 5) {
      break loop1;
    }
  }
  copyTable(get(CSTATS, 0), g.STATS, 12);
  x = (lmargin + BARMAR) + 1;
  if (g.VT220 == 0) {
    await APPLE_BARS(4, x);
  } else {
    await STATBARS(4, x, LUCK);
  }
  await USE_ARROWS();
  tell("select the character you want");
  await PRESS_RETURN();
  await TO_TOP_WINDOW();
  char = 0;
  for (;;) {
    ny = char + 4;
    ntbl = get(CNAMES, char);
    await DO_CURSET(ny, nx);
    setColor(g.FORE, g.BGND);
    if (g.VT220 == 0) {
      highlight(H_NORMAL);
    } else if ((g.COLORS$ == 0) || (g.FORE == g.GCOLOR)) {
      highlight(H_INVERSE);
    }
    highlight(H_MONO);
    tell(S(ntbl));
    copyTable(get(CSTATS, char), g.STATS, 12);
    highlight(H_NORMAL);
    x = ENDURANCE;
    loop3: for (;;) {
      await apply(g.STAT_ROUTINE, x, get(g.STATS, x));
      if (++x > LUCK) {
        break loop3;
      }
    }
    await TO_BOTTOM_WINDOW();
    loop4: for (;;) {
      x = await DO_INPUT();
      if (x == EOL || x == LF) {
        await SETUP_TOP();
        return false;
      } else if (x == DOWN_ARROW || x == SP || x == UP_ARROW) {
        await TO_TOP_WINDOW();
        await DO_CURSET(ny, nx);
        setColor(g.FORE, g.BGND);
        if (g.VT220 == 0) {
          highlight(H_INVERSE);
        } else {
          highlight(H_NORMAL);
          if (!(g.COLORS$ == 0)) {
            setColor(g.GCOLOR, g.BGND);
          }
        }
        highlight(H_MONO);
        tell(S(ntbl));
        if (!(x == UP_ARROW)) {
          if (++char > 5) {
            char = 0;
          }
          break loop4;
        }
        if (--char < 0) {
          char = 5;
        }
        break loop4;
      }
      sound(S_BOOP);
    }
  }
  return false;
}

