async function MANUAL() {
  let a_ = 0, oa = 0, x = 0, nx = 0, y = 0, z = 0, bx = 0, obx = 0, op = 0, key = 0, tbl = 0;
  a_ = ENDURANCE;
  loop1: for (;;) {
    put(g.STATS, a_, 1);
    if (++a_ > ARMOR_CLASS) {
      break loop1;
    }
  }
  await SETUP_TOP();
  g.POTENTIAL = INIT_POTENTIAL;
  await TO_TOP_WINDOW();
  y = g.BARY + 7;
  if (g.VT220 == 0) {
    cursorSet(y, g.BARX - 1);
    highlight(H_INVERSE);
    printTable(DBOX, APPBOX, 2);
    cursorSet(y, g.BARX);
    tell("   Potential");
    await BAR_NUMBER(7, g.POTENTIAL);
  } else {
    await DO_CURSET(g.BARY + ARMOR_CLASS, g.BARX);
    printTable(DBOX, g.BARWIDTH);
    await DO_CURSET(y, g.BARX);
    setColor(g.FORE, g.BGND);
    tell("   Potential");
    await RAWBAR(7, g.POTENTIAL);
  }
  await USE_ARROWS();
  tell("select an attribute. Then use the ");
  if (g.HOST == MACINTOSH) {
    tell("+");
  } else if (!(g.VT220 == 0)) {
    z = setFont(F_NEWFONT);
    printC(33);
  } else if (g.HOST == IBM) {
    printC(27);
  } else if (g.HOST == APPLE_2C) {
    z = setFont(F_NEWFONT);
    printC(72);
  } else {
    tell("LEFT");
  }
  z = setFont(F_DEFAULT);
  tell(S(g.AND));
  if (g.HOST == MACINTOSH) {
    tell("-");
  } else if (!(g.VT220 == 0)) {
    z = setFont(F_NEWFONT);
    printC(34);
  } else if (g.HOST == IBM) {
    printC(26);
  } else if (g.HOST == APPLE_2C) {
    z = setFont(F_NEWFONT);
    printC(85);
  } else {
    tell("RIGHT arrow");
  }
  z = setFont(F_DEFAULT);
  tell(" keys to adjust that attribute");
  await PRESS_RETURN();
  op = -1;
  oa = -1;
  a_ = ENDURANCE;
  loop2: for (;;) {
    await TO_TOP_WINDOW();
    tbl = BAR_LABELS + (a_ * LABEL_WIDTH);
    if (!(a_ == oa)) {
      oa = a_;
      await DO_CURSET(g.BARY + a_, g.BARX);
      setColor(g.FORE, g.BGND);
      if (!(g.VT220 == 0)) {
        highlight(H_INVERSE);
      }
      printTable(tbl, LABEL_WIDTH);
      highlight(H_NORMAL);
      highlight(H_MONO);
      setColor(g.GCOLOR, g.BGND);
    }
    if (!(op == g.POTENTIAL)) {
      await apply(g.STAT_ROUTINE, 7, g.POTENTIAL);
      op = g.POTENTIAL;
    }
    await TO_BOTTOM_WINDOW();
    key = await DO_INPUT();
    if (key == EOL || key == LF) {
      break loop2;
    }
    await TO_TOP_WINDOW();
    if (key == UP_ARROW || key == DOWN_ARROW || key == SP) {
      await DO_CURSET(g.BARY + a_, g.BARX);
      setColor(g.FORE, g.BGND);
      if (g.VT220 == 0) {
        highlight(H_INVERSE);
      }
      printTable(tbl, LABEL_WIDTH);
      highlight(H_NORMAL);
      highlight(H_MONO);
      setColor(g.GCOLOR, g.BGND);
      if (key == UP_ARROW) {
        if (--a_ < ENDURANCE) {
          a_ = LUCK;
        }
        continue loop2;
      }
      if (++a_ > LUCK) {
        a_ = ENDURANCE;
      }
      continue loop2;
    } else if ((key == LEFT_ARROW || key == 45 || key == 95) && !(g.POTENTIAL == INIT_POTENTIAL)) {
      x = get(g.STATS, a_);
      if (s16(x) > s16(1)) {
        ++g.POTENTIAL;
        nx = x - 1;
        put(g.STATS, a_, nx);
        await apply(g.STAT_ROUTINE, a_, nx);
        continue loop2;
      }
    } else if (g.POTENTIAL == 0) {
    } else if (key == RIGHT_ARROW || key == 43 || key == 61) {
      --g.POTENTIAL;
      x = get(g.STATS, a_);
      nx = x + 1;
      put(g.STATS, a_, nx);
      await apply(g.STAT_ROUTINE, a_, nx);
      continue loop2;
    }
    sound(2);
  }
  await TO_TOP_WINDOW();
  await FUDGE_STATS();
  copyTable(g.STATS, g.MAXSTATS, 16);
  a_ = ENDURANCE;
  loop3: for (;;) {
    await apply(g.STAT_ROUTINE, a_, get(g.STATS, a_));
    if (++a_ > LUCK) {
      break loop3;
    }
  }
  if (g.VT220 == 0) {
    await DO_CURSET(y, g.BARX - 1);
    printTable(DBOX, 18, 2);
    highlight(H_INVERSE);
  } else {
    await DO_CURSET(y, g.BARX);
    highlight(H_NORMAL);
    highlight(H_MONO);
    printTable(DBOX, g.BARWIDTH);
    setColor(g.FORE, g.BGND);
  }
  await DO_CURSET(g.BARY, g.BARX);
  printTable(BAR_LABELS, LABEL_WIDTH, ARMOR_CLASS);
  await TO_BOTTOM_WINDOW();
  return false;
}

async function ROLL_YOUR_OWN() {
  let stat = 0, xstat = 0, old = 0, delta = 0, stat_order = 0, x = 0;
  stat = ENDURANCE;
  loop1: for (;;) {
    put(g.STATS, stat, 1);
    if (++stat > ARMOR_CLASS) {
      break loop1;
    }
  }
  await SETUP_TOP();
  await TO_BOTTOM_WINDOW();
  tell("\n\nA new set of attributes will appear each time you press the [SPACE] bar.\n\nPress [RETURN] to select a set that you like. >");
  put(g.AUX_TABLE, 0, 7);
  stat_order = g.AUX_TABLE + 4;
  stat = ENDURANCE;
  loop2: for (;;) {
    put(stat_order, stat, stat);
    if (++stat > LUCK) {
      break loop2;
    }
  }
  stat_order = g.AUX_TABLE + 20;
  for (;;) {
    await TO_TOP_WINDOW();
    put(g.AUX_TABLE, 1, 0);
    stat = ENDURANCE;
    loop4: for (;;) {
      putb(stat_order, stat, await PICK_ONE(g.AUX_TABLE));
      if (++stat > LUCK) {
        break loop4;
      }
    }
    g.POTENTIAL = 66;
    stat = ENDURANCE;
    loop5: for (;;) {
      xstat = getb(stat_order, stat);
      delta = 1;
      if (!(g.POTENTIAL == 0)) {
        delta = random(11);
        --delta;
        delta = AVERAGE + (SPREAD - delta);
        if (s16(delta) > s16(g.POTENTIAL)) {
          delta = g.POTENTIAL;
        }
        g.POTENTIAL = g.POTENTIAL - delta;
      }
      put(g.STATS, xstat, delta);
      if (++stat > LUCK) {
        break loop5;
      }
    }
    await FUDGE_STATS();
    stat = ENDURANCE;
    loop6: for (;;) {
      await apply(g.STAT_ROUTINE, stat, get(g.STATS, stat));
      if (++stat > LUCK) {
        break loop6;
      }
    }
    await TO_BOTTOM_WINDOW();
    loop7: for (;;) {
      x = await readChar(1);
      if (x == EOL || x == LF) {
        return false;
      } else if (x == SP) {
        break loop7;
      }
      sound(S_BOOP);
    }
  }
}

async function FUDGE_STATS() {
  let total = 0, stat = 0;
  if (g.POTENTIAL == 0) {
    return false;
  }
  total = g.POTENTIAL;
  for (;;) {
    put(g.STATS, stat, get(g.STATS, stat) + 1);
    if (--total < 1) {
      return false;
    } else if (++stat > LUCK) {
      stat = ENDURANCE;
    }
  }
}

async function GET_NAME() {
  let cnt = 0, ptr = 0, apo = 0, dash = 0, bad = 0, any = 0, cap = 0, space = 0, len = 0, x = 0, char = 0;
  if (!(hasFlag(PLAYER, NAMED))) {
    copyTable(DEFAULT_NAME, CHARNAME, DEFAULT_NAME_LENGTH);
  }
  tell("\nFinally, you must select a Name for your character.\n\nBy what Name shall your character be known?");
  loop1: for (;;) {
    copyTable(g.P_INBUF, 0, P_INBUF_LENGTH);
    putb(g.P_INBUF, 0, 80);
    tell("\n\n[The default is \"");
    await PRINT_TABLE(CHARNAME);
    tell(".\"] >");
    loop2: for (;;) {
      setColor(g.INCOLOR, g.BGND);
      x = await read(g.P_INBUF, 0);
      if (x == EOL || x == LF) {
        break loop2;
      }
      sound(2);
    }
    setColor(g.FORE, g.BGND);
    len = getb(g.P_INBUF, 1);
    if (len == 0) {
      break loop1;
    }
    x = len + 1;
    ptr = 2;
    apo = 0;
    dash = 0;
    bad = 0;
    any = 0;
    loop3: for (;;) {
      char = getb(g.P_INBUF, ptr);
      if ((s16(char) > s16(NaN)) && (s16(char) < s16(NaN))) {
        ++any;
      } else if (char == SP) {
      } else if (char == 39) {
        ++apo;
      } else if (char == 45) {
        ++dash;
      } else {
        ++bad;
        break loop3;
      }
      if (++ptr > x) {
        break loop3;
      }
    }
    if ((any == 0) || !(bad == 0) || (s16(apo) > s16(1)) || (s16(dash) > s16(1))) {
      (await BAD_NAME("silly"));
      continue loop1;
    } else if (s16(len) > s16(CHARNAME_LENGTH)) {
      (await BAD_NAME("too long"));
      continue loop1;
    }
    copyTable(CHARNAME, 0, 25);
    cnt = 0;
    ptr = 2;
    cap = 1;
    space = 0;
    any = 0;
    loop4: for (;;) {
      char = getb(g.P_INBUF, ptr);
      if (char == SP) {
        ++cap;
        ++space;
        if (!(any == 0) && (space == 1)) {
          ++cnt;
          putb(CHARNAME, cnt, SP);
        }
      } else {
        ++any;
        space = 0;
        if (char == 39 || char == 45) {
          ++cap;
        } else if (!(cap == 0)) {
          cap = 0;
          char = char - SP;
        }
        ++cnt;
        putb(CHARNAME, cnt, char);
      }
      if (++ptr > x) {
        break loop4;
      }
    }
    putb(CHARNAME, 0, cnt);
    tell("\nIs \"");
    await PRINT_TABLE(CHARNAME);
    tell("\" correct?");
    if (await YES$()) {
      break loop1;
    }
    (await BAD_NAME("cast into the void"));
  }
  setFlag(PLAYER, NAMED);
  await SHOW_RANK(g.WIDTH);
  return false;
}

