async function OPTIONS() {
  let u = 0, word = 0, key = 0;
  if (g.CAN_UNDO == 0) {
  } else if (g.LAST_MONSTER == 0) {
    ++u;
  }
  printS("\nDo you want to ");
  if (!(u == 0)) {
    tell("undo your last command, ");
  }
  tell("restore a previously saved game, restart from the beginning, or quit?\n\n");
  loop1: for (;;) {
    tell("[Type ");
    if (!(u == 0)) {
      tell("UNDO, ");
    }
    tell("RESTORE, RESTART or QUIT.] >");
    key = await READ_YES_LEXV();
    word = get(YES_LEXV, P_LEXSTART);
    if (getb(YES_LEXV, P_LEXWORDS) == 0) {
      continue loop1;
    } else if (!(u == 0) && (word == W.UNDO)) {
      await V_UNDO();
    } else if (word == W.RESTORE) {
      await V_RESTORE();
    } else if (word == W.RESTART) {
      await restart();
      (await FAILED("RESTART"));
    } else if (word == W.QUIT || word == W.Q) {
      crlf();
      await quit();
    }
  }
  return false;
}

